// @001A816C  76 bytes
// ==========================================================================
// Walks the definition's 20-byte tracks and the reanimator's 100-byte track
// instances in step and compares every track name with the one asked for.
// mDefinition is +0x1C, mTrackCount +0x04 of that, mTracks its first word,
// mTrackInstances +0x68; a match writes the bool to the instance byte at +0x60.
//
// r0 is the leftover of the last strcasecmp, or of ReanimationTryToGet when the
// reanimation is missing or has no tracks. No caller reads it.
int Zombie::ReanimIgnoreClipRect(char const* theTrackName, bool theIgnoreClipRect)
{
    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr)
        return 0;

    ReanimatorTrack *aTracks = aBodyReanim->mDefinition->mTracks;
    ReanimatorTrackInstance *aTrackInstances = aBodyReanim->mTrackInstances;
    int aTrackCount = aBodyReanim->mDefinition->mTrackCount;

    int result = 0;
    for (int i = 0; i < aTrackCount; i++)
    {
        result = strcasecmp(aTracks[i].mName, theTrackName);
        if (result == 0)
            aTrackInstances[i].mIgnoreClipRect = theIgnoreClipRect;
    }
    return result;
}

