    float aPosY = mPosY - 44.0f;

    int aTargetX;
    float aTargetY;
    if (thePlant != nullptr)
    {
        aTargetX = thePlant->mX;
        aTargetY = (float)thePlant->mY;
    }
    else
    {
        aTargetY = 0.0f;
        aTargetX = (int)(mPosX - 300.0f);
    }

    mApp->PlayFoley(FOLEY_BASKETBALL);

    // 9 is PROJECTILE_BASKETBALL. AddProjectile already hands back the pointer.
