// @001A85EC  102 bytes
// ==========================================================================
// The climb onto the high ground: altitude rises one pixel a frame up to 30 and
// falls one a frame back to zero, and the zombie stops being on the high ground
// once it is down. 4 and 5 are ZombieHeight's HEIGHT_UP_TO_HIGH_GROUND and
// HEIGHT_DOWN_OFF_HIGH_GROUND (this tree has no such enum, see Zombie.h); the
// ZOMBIE_POGO test keeps the pogo zombie out, its altitude comes from the
// bounce phases.
void Zombie::UpdateZombieHighGround()
{
    if (mZombieType != ZOMBIE_POGO)
    {
        if (mZombieHeight == 4)
        {
            mAltitude += 1.0f;
            if (mAltitude >= 30.0f)
            {
                mAltitude = 30.0f;
                mZombieHeight = 0;
            }
        }
        else if (mZombieHeight == 5)
        {
            mAltitude -= 1.0f;
            if (mAltitude <= 0.0f)
            {
                mZombieHeight = 0;
                mAltitude = 0.0f;
                mOnHighGround = false;
            }
        }
    }
    return;
}

