// ==========================================================================
// Zombie::OverrideParticleColor(TodParticleSystem *)
// @001A8668  82 bytes
// ==========================================================================
// A mind-controlled zombie tints its particles white; a chilled or frozen one
// tints them blue. The static the mind-controlled arm passes is 0xFFFFFFFF,
// i.e. white.
void Zombie::OverrideParticleColor(TodParticleSystem * theParticleSystem)
{
    if (theParticleSystem == nullptr)
        return;

    // A mind-controlled zombie tints its particles with the mind-control colour
    // the static constructor installs; a chilled or frozen one tints them blue.
    if (mMindControlled)
    {
        Sexy::Color aColor(gZombieTintRed, gZombieTintGreen, gZombieTintBlue, 255);
        theParticleSystem->OverrideColor(nullptr, aColor);
    }
    else
    {
        if (mChilledCounter <= 0 && mIceTrapCounter <= 0)
            return;

        Sexy::Color aColor(75, 75, 255, 255);
        theParticleSystem->OverrideColor(nullptr, aColor);
    }

    theParticleSystem->OverrideExtraAdditiveDraw(nullptr, true);
    return;
}

// ==========================================================================
// Zombie::UpdateZamboni(void)
// @001A86C0  208 bytes
// ==========================================================================
// The zamboni ices the row it is driving through. mIceMinX[mRow] keeps the
// leftmost point it has reached and mIceTimer[mRow] the time the ice lasts
// (endless in the Bobsled Bonanza challenge). mVelX eases from 0.25 to 0.05 as
// the zombie passes x = 700, and bleeds off 0.0005 a frame once its tires are
// flat.
void Zombie::UpdateZamboni()
{
    if (mFlatTires)
    {
        if (mVelX > 0.0005f)
            mVelX -= 0.0005f;
    }
    else if (mPosX > 400.0f)
    {
        // UpdateZamboni @0x1A8780 passes 0.25f and 0.05f to the speed curve.
        mVelX = TodAnimateCurveFloat(700, 300, (int)mPosX, 0.25f, 0.05f, CURVE_LINEAR);
    }

    int aMinX = (int)(mPosX + 118.0f);
    int aIceMinX = aMinX;
    bool aHasRoof = mBoard->StageHasRoof();
    if (aHasRoof)
    {
        if (aMinX < 500)
            aIceMinX = 500;
    }
    else if (aMinX < 25)
    {
        aIceMinX = 25;
    }

    if (mBoard->mIceMinX[mRow] > aIceMinX)
        mBoard->mIceMinX[mRow] = aIceMinX;

    if (aIceMinX < 800)
    {
        mBoard->mIceTimer[mRow] = 3000;
        if (mApp->mGameMode == GAMEMODE_CHALLENGE_BOBSLED_BONANZA)
            mBoard->mIceTimer[mRow] = 0x7FFFFFFF;
    }
}

