// ==========================================================================
// Zombie::UpdateClimbingLadder(void)
// @001A87AC  160 bytes
// ==========================================================================
// While a ladder stands in the column the zombie is walking into, it climbs:
// mAltitude gains 0.8 a frame and it edges half a pixel left each frame until
// its speed passes 0.5. The climb ends at 90 (or 120 coming off the high
// ground), and then the zombie falls -- 7 is HEIGHT_FALLING.
GridItem * Zombie::UpdateClimbingLadder()
{
    float aAltitude = mAltitude;
    if (mOnHighGround)
        aAltitude -= 30.0f;

    int aGridX = mBoard->PixelToGridXKeepOnBoard((int)((float)(mX + 5) + aAltitude * 0.5f), mY);
    GridItem *aLadder = mBoard->GetLadderAt(aGridX, mRow);

    float aClimbLimit = 90.0f;
    if (aLadder != nullptr)
    {
        float aNewAltitude = mAltitude + 0.8f;
        if (mVelX < 0.5f)
            mPosX -= 0.5f;
        mAltitude = aNewAltitude;
        if (mOnHighGround)
            aClimbLimit = 120.0f;
        if (aClimbLimit > aNewAltitude)
            return aLadder;
    }

    mZombieHeight = 7;
    return aLadder;
}

