// ==========================================================================
// Zombie::IsWalkingBackwards(void)
// @001A89FC  108 bytes
// ==========================================================================
// A mind-controlled zombie always walks backwards, and so does a zombiquarium
// one whose mVelZ is outside the quarter circles (10 is
// HEIGHT_ZOMBIQUARIUM). The digger walks backwards while it is rising,
// stunned or walking, and the yeti whenever it has lost its object.
int Zombie::IsWalkingBackwards()
{
    if (mMindControlled)
        return 1;

    if (mZombieHeight == 10 && (mVelZ < 1.5708f || mVelZ > 4.7124f))
        return 1;

    if (mZombieType == ZOMBIE_DIGGER)
    {
        if (mZombiePhase == PHASE_DIGGER_RISING
            || mZombiePhase == PHASE_DIGGER_STUNNED
            || mZombiePhase == PHASE_DIGGER_WALKING)
            return 1;

        if (mZombiePhase == PHASE_ZOMBIE_DYING
            || mZombiePhase == PHASE_ZOMBIE_BURNED
            || mZombiePhase == PHASE_ZOMBIE_MOWERED)
            return mHasObject;

        return 0;
    }

    if (mZombieType == ZOMBIE_YETI)
        return !mHasObject;

    return 0;
}

// ==========================================================================
// Zombie::DrawDancerReanim(Sexy::Graphics *,ZombieDrawPosition &)
// @001A8A70  432 bytes
// ==========================================================================
// The dancer gets a spotlight behind and in front of it once it is past
// PHASE_ZOMBIE_DYING and out of the two opening phases, and the light cycles
// through five colours as the zombie ages (case 0 keeps the default 250,250,160).
// The dump's `a1` is the Zombie -- it reads mZombiePhase at +0x38 and mApp at
// +0x10 -- and its `a2` is the Graphics; the ZombieDrawPosition argument is
// never read.
int Zombie::DrawDancerReanim(Sexy::Graphics * g, ZombieDrawPosition & theDrawPos)
{
    bool aShowSpotlight = mZombiePhase > PHASE_ZOMBIE_DYING
        && mZombiePhase != PHASE_DANCER_DANCING_IN
        && mZombiePhase != PHASE_DANCER_SNAPPING_FINGERS;

    if (!aShowSpotlight || mApp->mGameScene == SCENE_ZOMBIES_WON)
    {
        Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
        aBodyReanim->DrawRenderGroup(g, 0);
        return 0;
    }

    Sexy::Color aSpotlightColor(250, 250, 160);
    if (mZombieAge >= 700)
    {
        switch (7 * (mZombieAge / 100) % 5)
        {
            case 1:
                aSpotlightColor = Sexy::Color(114, 234, 170);
                break;
            case 2:
                aSpotlightColor = Sexy::Color(216, 126, 202);
                break;
            case 3:
                aSpotlightColor = Sexy::Color(90, 110, 140);
                break;
            case 4:
                aSpotlightColor = Sexy::Color(240, 90, 130);
                break;
            default:
                break;
        }
    }

    g->SetColorizeImages(true);
    g->SetColor(aSpotlightColor);
    TodDrawImageScaledF(g, IMAGE_SPOTLIGHT2, -30.0f, 60.0f, 4.0f, 4.0f);
    g->SetColorizeImages(false);

    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    aBodyReanim->DrawRenderGroup(g, 0);

    g->SetColorizeImages(true);
    g->SetColor(aSpotlightColor);
    TodDrawImageScaledF(g, IMAGE_SPOTLIGHT, -30.0f, -544.0f, 4.0f, 4.0f);
    g->SetColorizeImages(false);
  return 0;
}

// ==========================================================================
// Zombie::GetHelmDamageIndex(void)
// @001A8C2C  64 bytes
// ==========================================================================
// Three damage states by the health that is left: 2 below a third, 1 below two
// thirds, 0 above.
int Zombie::GetHelmDamageIndex()
{
    if (mHelmHealth < mHelmMaxHealth / 3)
        return 2;

    return mHelmHealth < 2 * mHelmMaxHealth / 3;
}

// ==========================================================================
// Zombie::GetBodyDamageIndex(void)
// @001A8C6C  116 bytes
// ==========================================================================
// The boss loses its body art at a half and at four fifths rather than at a
// third and two thirds.
int Zombie::GetBodyDamageIndex()
{
    if (mZombieType == ZOMBIE_BOSS)
    {
        if (mBodyHealth < mBodyMaxHealth / 2)
            return 2;

        return mBodyHealth < 4 * mBodyMaxHealth / 5;
    }

    if (mBodyHealth < mBodyMaxHealth / 3)
        return 2;

    return mBodyHealth < 2 * mBodyMaxHealth / 3;
}

// ==========================================================================
// Zombie::GetShieldDamageIndex(void)
// @001A8CE0  64 bytes
// ==========================================================================
int Zombie::GetShieldDamageIndex()
{
    if (mShieldHealth < mShieldMaxHealth / 3)
        return 2;

    return mShieldHealth < 2 * mShieldMaxHealth / 3;
}

// ==========================================================================
// Zombie::DrawIceTrap(Sexy::Graphics *,ZombieDrawPosition &,bool)
// @001A8D20  208 bytes
// ==========================================================================
// An ice trap is only drawn on a zombie that is not in the pool and is not the
// boss. Each type offsets and scales the block differently; the last argument
// picks the front (IMAGE_ICETRAP) or the back (IMAGE_ICETRAP2) art. The Y
// origin is the draw position's mBodyY (byte 12 of the record) plus 92.
void Zombie::DrawIceTrap(Sexy::Graphics *g, ZombieDrawPosition &theDrawPos, int theIceTrapCounter)
{
    if (mInPool || mZombieType == ZOMBIE_BOSS)
        return;

    ZombieDrawPosition &aDrawPos = theDrawPos;
    float aOffsetY = aDrawPos.mBodyY + 92.0f;
    float aOffsetX;
    float aScale;
    if (mZombieType == ZOMBIE_POGO)
    {
        aOffsetX = 36.0f;
        aOffsetY += 20.0f;
        aScale = 1.0f;
    }
    else if (mZombieType == ZOMBIE_GARGANTUAR || mZombieType == ZOMBIE_REDEYE_GARGANTUAR)
    {
        aOffsetX = 26.0f;
        aOffsetY -= 7.0f;
        aScale = 1.6f;
    }
    else
    {
        switch (mZombieType)
        {
            case ZOMBIE_BUNGEE:
                aOffsetX = 1.0f;
                aOffsetY -= 23.0f;
                aScale = 1.2f;
                break;
            case ZOMBIE_DIGGER:
                aOffsetX = 19.0f;
                aScale = 1.0f;
                break;
            case ZOMBIE_CATAPULT:
                aOffsetX = 78.0f;
                aScale = 1.0f;
                break;
            case ZOMBIE_BALLOON:
                aOffsetX = 37.0f;
                aOffsetY += 27.0f;
                aScale = 1.0f;
                break;
            default:
                aOffsetX = 46.0f;
                aScale = 1.0f;
                break;
        }
    }

    Sexy::Image *aImage = theIceTrapCounter != 0 ? IMAGE_ICETRAP : IMAGE_ICETRAP2;
    TodDrawImageScaledF(g, aImage, aOffsetX, aOffsetY, aScale, aScale);
    return;
}

// ==========================================================================
// Zombie::CanTargetPlant(Plant *,ZombieAttackType)
// @001A8E00  316 bytes
// ==========================================================================
int Zombie::CanTargetPlant(Plant * thePlant, ZombieAttackType theAttackType)
{
    if (mApp->IsWallnutBowlingLevel() && theAttackType != (ZombieAttackType)2)
        return 0;

    if (thePlant->NotOnGround()
        || thePlant->mSeedType == SEED_TANGLEKELP
        || (!mInPool && mBoard->IsPoolSquare(thePlant->mPlantCol, thePlant->mRow)))
    {
        return 0;
    }

    if (mZombiePhase == PHASE_DIGGER_TUNNELING)
    {
        if (thePlant->mSeedType == SEED_POTATOMINE && thePlant->mState == STATE_NOTREADY)
            return 1;
    }
    else if (thePlant->IsSpiky())
    {
        if (mZombieType == ZOMBIE_REDEYE_GARGANTUAR
            || mZombieType == ZOMBIE_GARGANTUAR
            || mZombieType == ZOMBIE_ZAMBONI
            || mBoard->IsPoolSquare(thePlant->mPlantCol, thePlant->mRow)
            || mBoard->GetFlowerPotAt(thePlant->mPlantCol, thePlant->mRow) != nullptr)
        {
            return 1;
        }
    }
    else
    {
        if (theAttackType == (ZombieAttackType)1)
        {
            if (thePlant->mSeedType == SEED_JALAPENO
                || thePlant->mSeedType == SEED_CHERRYBOMB
                || thePlant->mSeedType == SEED_BLOVER
                || thePlant->mSeedType == SEED_SQUASH)
            {
                return 0;
            }

            if (thePlant->mSeedType == SEED_ICESHROOM || thePlant->mSeedType == SEED_DOOMSHROOM)
                return thePlant->mIsAsleep;
        }

        if (mZombiePhase == PHASE_LADDER_CARRYING || mZombiePhase == PHASE_LADDER_PLACING)
        {
            bool aPlaceLadder = thePlant->mSeedType == SEED_WALLNUT
                                || thePlant->mSeedType == SEED_TALLNUT
                                || thePlant->mSeedType == SEED_PUMPKINSHELL;
            if (mBoard->GetLadderAt(thePlant->mPlantCol, thePlant->mRow) != nullptr)
                aPlaceLadder = false;

            if ((theAttackType == (ZombieAttackType)0 && aPlaceLadder)
                || (theAttackType == (ZombieAttackType)3 && !aPlaceLadder))
            {
                return 0;
            }
        }

        if (theAttackType != (ZombieAttackType)0 && theAttackType != (ZombieAttackType)2)
            return 1;

        PlantPriority aPriority = theAttackType == (ZombieAttackType)2 ? (PlantPriority)6 : (PlantPriority)0;
        Plant *aTopPlant = mBoard->GetTopPlantAt(thePlant->mPlantCol, thePlant->mRow, aPriority);
        if (aTopPlant == thePlant || aTopPlant == nullptr || CanTargetPlant(aTopPlant, theAttackType) == 0)
            return 1;
    }

    return 0;
}

// ==========================================================================
// Zombie::SquishAllInSquare(int,int,ZombieAttackType)
// @001A8F3C  94 bytes
// ==========================================================================
int Zombie::SquishAllInSquare(int theX, int theY, ZombieAttackType theAttackType)
{
    Plant *aPlant = nullptr;
    while (mBoard->IteratePlants(aPlant))
    {
        if (aPlant->mRow == theY && aPlant->mPlantCol == theX)
        {
            if (theAttackType == (ZombieAttackType)1 && aPlant->IsSpiky())
                continue;

            if (aPlant->mSeedType != SEED_SPIKEROCK)
                aPlant->Squish();
        }
    }
    return 0;
}

