// ==========================================================================
// Zombie::ZombieNotWalking(void)
// @001A8FB8  190 bytes
// ==========================================================================
bool Zombie::ZombieNotWalking()
{
    if (mIsEating || IsImmobilizied())
        return true;

    if (mZombiePhase == PHASE_NEWSPAPER_MADDENING
        || mZombiePhase == PHASE_JACK_IN_THE_BOX_POPPING
        || mZombiePhase == PHASE_CATAPULT_LAUNCHING
        || mZombiePhase == PHASE_CATAPULT_RELOADING
        || mZombiePhase == PHASE_GARGANTUAR_THROWING
        || mZombiePhase == PHASE_GARGANTUAR_SMASHING
        || mZombiePhase == PHASE_IMP_GETTING_THROWN
        || mZombiePhase == PHASE_IMP_LANDING
        || mZombiePhase == PHASE_DIGGER_RISING
        || mZombiePhase == PHASE_DIGGER_TUNNELING_PAUSE_WITHOUT_AXE
        || mZombiePhase == PHASE_DIGGER_RISE_WITHOUT_AXE
        || mZombiePhase == PHASE_DIGGER_STUNNED
        || mZombiePhase == PHASE_DANCER_SNAPPING_FINGERS
        || mZombiePhase == PHASE_DANCER_SNAPPING_FINGERS_WITH_LIGHT
        || mZombiePhase == PHASE_DANCER_SNAPPING_FINGERS_HOLD
        || mZombiePhase == PHASE_DANCER_RISING
        || mZombiePhase == PHASE_LADDER_PLACING
        || mZombiePhase == PHASE_DANCER_WALK_TO_RAISE
        || mZombiePhase == PHASE_DANCER_RAISE_LEFT_1
        || mZombiePhase == PHASE_DANCER_RAISE_RIGHT_1
        || mZombiePhase == PHASE_DANCER_RAISE_LEFT_2
        || mZombiePhase == PHASE_DANCER_RAISE_RIGHT_2
        || mZombieHeight == HEIGHT_IN_TO_CHIMNEY
        || mZombieHeight == HEIGHT_GETTING_BUNGEE_DROPPED
        || mZombieHeight == HEIGHT_ZOMBIQUARIUM
        || mZombieType == ZOMBIE_BUNGEE
        || mZombieType == ZOMBIE_BOSS)
    {
        return true;
    }

    if (mZombieType != ZOMBIE_DANCER && mZombieType != ZOMBIE_BACKUP_DANCER)
        return false;

    Zombie *aLeader;
    if (mZombieType == ZOMBIE_DANCER)
    {
        aLeader = this;
    }
    else
    {
        aLeader = mBoard->ZombieTryToGet(mRelatedZombieID);
        if (aLeader == nullptr)
            return false;
    }

    if (aLeader->IsImmobilizied() || aLeader->mIsEating)
        return true;

    for (int i = 0; i < 4; i++)
    {
        Zombie *aFollower = mBoard->ZombieTryToGet(aLeader->mFollowerZombieID[i]);
        if (aFollower != nullptr && (aFollower->IsImmobilizied() || aFollower->mIsEating))
            return true;
    }

    return false;
}

// ==========================================================================
// Zombie::GetDancerFrame(void)
// @001A9078  58 bytes
// ==========================================================================
int Zombie::GetDancerFrame()
{
    if (mFromWave == -3 || IsImmobilizied())
        return 0;

    int aFrameLength = 20;
    int aFramesCount = 23;
    if (mZombiePhase == PHASE_DANCER_DANCING_IN)
    {
        aFrameLength = 10;
        aFramesCount = 11;
    }
    return mApp->mAppCounter % (aFrameLength * aFramesCount) / aFrameLength;
}

// ==========================================================================
// Zombie::GetDancerPhase(void)
// @001A90B4  48 bytes
// ==========================================================================
int Zombie::GetDancerPhase()
{
    int aFrame = GetDancerFrame();

    if (aFrame <= 11)
        return PHASE_DANCER_DANCING_LEFT;
    if (aFrame == 12)
        return PHASE_DANCER_WALK_TO_RAISE;
    if (aFrame <= 15)
        return PHASE_DANCER_RAISE_RIGHT_1;
    if (aFrame <= 18)
        return PHASE_DANCER_RAISE_LEFT_1;
    if (aFrame <= 21)
        return PHASE_DANCER_RAISE_RIGHT_2;
    return PHASE_DANCER_RAISE_LEFT_2;
}

// ==========================================================================
// Zombie::DrawZombiePart(Sexy::Graphics *,Sexy::Image *,int,int,ZombieDrawPosition &)
// @001A90E4  734 bytes
// ==========================================================================
int Zombie::DrawZombiePart(Sexy::Graphics * aGraphics, Sexy::Image * aImage, int aCelCol, int aCelRow, ZombieDrawPosition & aDrawPos)
{
    ZombieDrawPosition &aPos = aDrawPos;

    int aCelWidth = aImage->GetCelWidth();
    int aCelHeight = aImage->GetCelHeight();

    float aPosX = aPos.mImageOffsetX;
    float aPosY = aPos.mBodyY + aPos.mImageOffsetY;
    if (mZombiePhase == PHASE_POLEVAULTER_IN_VAULT)
    {
        aPosX -= 120.0f;
        aPosY -= 120.0f;
    }
    else if (mZombiePhase == PHASE_DIGGER_TUNNELING)
    {
        aPosY += 50.0f;
    }

    float aClipHeight = aPos.mClipHeight;
    if (mZombieType == ZOMBIE_ZAMBONI)
        aPosY -= 19.0f;

    int aDrawHeight;
    if (aClipHeight > -100.0f)
    {
        float aHeight = (float)aCelHeight - aClipHeight;
        if (aHeight <= 0.0f)
            aDrawHeight = 0;
        else if (aHeight > (float)aCelHeight)
            aDrawHeight = aCelHeight;
        else
            aDrawHeight = (int)aHeight;
    }
    else
    {
        aDrawHeight = aCelHeight;
    }

    int aFadeAlpha = 255;
    if (mZombieFade >= 0)
    {
        aFadeAlpha = 255 * mZombieFade / 10;
        if (aFadeAlpha <= 0)
            aFadeAlpha = 0;
        else if (aFadeAlpha >= 255)
            aFadeAlpha = 255;

        aGraphics->SetColorizeImages(true);
        Sexy::Color aFadeColor(255, 255, 255, aFadeAlpha);
        aGraphics->SetColor(aFadeColor);
    }

    bool aMirror = false;
    if (mZombiePhase == PHASE_DANCER_DANCING_IN || mZombiePhase == PHASE_DANCER_DANCING_LEFT)
    {
        int aDancerFrame = GetDancerFrame();
        if (!mIsEating
            && ((aDancerFrame >= 12 && aDancerFrame <= 14) || (aDancerFrame >= 18 && aDancerFrame <= 20)))
        {
            aMirror = true;
            aPosX = 30.0f - aPosX;
        }
    }

    Sexy::Rect aSrcRect(aCelCol * aCelWidth, aCelRow * aCelHeight, aCelWidth, aDrawHeight);
    Sexy::Rect aDestRect((int)aPosX, (int)aPosY, aCelWidth, aDrawHeight);

    if (mZombiePhase == PHASE_ZOMBIE_BURNED)
    {
        if (mMindControlled)
            aMirror = true;

        aGraphics->SetColorizeImages(true);
        aGraphics->SetColor(Sexy::Color::Black);
        aGraphics->DrawImageMirror(aImage, aDestRect, aSrcRect, aMirror);
    }
    else if (mMindControlled)
    {
        aGraphics->SetColorizeImages(true);
        aMirror = true;
        Sexy::Color aColor(128, 64, 192, aFadeAlpha);
        aGraphics->SetColor(aColor);
        aGraphics->DrawImageMirror(aImage, aDestRect, aSrcRect, true);
        aGraphics->SetDrawMode(1);
        aGraphics->DrawImageMirror(aImage, aDestRect, aSrcRect, true);
        aGraphics->SetDrawMode(0);
    }
    else if (mChilledCounter > 0 || mIceTrapCounter > 0)
    {
        aGraphics->SetColorizeImages(true);
        Sexy::Color aColor(75, 75, 255, aFadeAlpha);
        aGraphics->SetColor(aColor);
        aGraphics->DrawImageMirror(aImage, aDestRect, aSrcRect, aMirror);
        aGraphics->SetDrawMode(1);
        aGraphics->DrawImageMirror(aImage, aDestRect, aSrcRect, aMirror);
        aGraphics->SetDrawMode(0);
    }
    else
    {
        aGraphics->DrawImageMirror(aImage, aDestRect, aSrcRect, aMirror);
    }

    if (mJustGotShotCounter > 0)
    {
        aGraphics->SetDrawMode(1);
        aGraphics->SetColorizeImages(true);
        int aGrayness = 10 * mJustGotShotCounter;
        Sexy::Color aColor(aGrayness, aGrayness, aGrayness, 255);
        aGraphics->SetColor(aColor);
        aGraphics->DrawImageMirror(aImage, aDestRect, aSrcRect, aMirror);
        aGraphics->SetDrawMode(0);
    }

    aGraphics->SetColorizeImages(false);
  return 0;
}

// ==========================================================================
// Zombie::IsMovingAtChilledSpeed(void)
// @001A93DC  94 bytes
// ==========================================================================
int Zombie::IsMovingAtChilledSpeed()
{
    if (mChilledCounter > 0)
        return 1;

    if (mZombieType != ZOMBIE_DANCER && mZombieType != ZOMBIE_BACKUP_DANCER)
        return 0;

    Zombie *aLeader;
    if (mZombieType == ZOMBIE_DANCER)
    {
        aLeader = this;
    }
    else
    {
        aLeader = mBoard->ZombieTryToGet(mRelatedZombieID);
        if (aLeader == nullptr)
            return 0;
        if (aLeader->mChilledCounter > 0)
            return 1;
    }

    for (int i = 0; i < 4; i++)
    {
        Zombie *aFollower = mBoard->ZombieTryToGet(aLeader->mFollowerZombieID[i]);
        if (aFollower != nullptr && aFollower->mChilledCounter > 0)
            return 1;
    }
    return 0;
}

// ==========================================================================
// Zombie::ApplyAnimRate(float)
// @001A943C  62 bytes
// ==========================================================================
// Sets the body reanimation's rate and, while the zombie moves at chilled
// speed, halves the rate it just stored (mAnimRate, +0x18). Callers ignore
// the leftover register.
void Zombie::ApplyAnimRate(float theAnimRate)
{
    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr)
        return;

    aBodyReanim->SetAnimRate(theAnimRate);
    if (!IsMovingAtChilledSpeed())
        return;

    aBodyReanim->SetAnimRate(aBodyReanim->mAnimRate * 0.5f);
}

// ==========================================================================
// Zombie::SetAnimRate(float)
// @001A947C  8 bytes
// ==========================================================================
void Zombie::SetAnimRate(float theAnimRate)
{
    mOriginalAnimRate = theAnimRate;
    ApplyAnimRate(theAnimRate);
}

// ==========================================================================
// Zombie::PoolSplash(bool)
// @001A9484  190 bytes
// ==========================================================================
void Zombie::PoolSplash(bool theIntoPool)
{
    float aOffsetX = -14.0f;
    float aOffsetY = 70.0f;
    if (mZombiePhase != PHASE_SNORKEL_WALKING_IN_POOL)
    {
        aOffsetX = 23.0f;
        aOffsetY = 78.0f;
    }

    // 32 is REANIM_SPLASH. AddReanimation already hands back the pointer.
    Reanimation *aReanim = mApp->AddReanimation(aOffsetX + (float)mX,
                                                aOffsetY + (float)mY,
                                                mRenderOrder + 1,
                                                REANIM_SPLASH);
    aReanim->OverrideScale(0.8f, 0.8f);
    mApp->AddTodParticle(((float)mX + 37.0f) + aOffsetX,
                         ((float)mY + 42.0f) + aOffsetY,
                         mRenderOrder + 1,
                         (ParticleEffect)23);

    if (theIntoPool)
        mApp->PlayFoley(FOLEY_ZOMBIESPLASH);

    mApp->PlayFoley(FOLEY_PLANT_WATER);
}

// ==========================================================================
// Zombie::IsOnHighGround(void)
// @001A9554  50 bytes
// ==========================================================================
bool Zombie::IsOnHighGround()
{
    if (!IsOnBoard())
        return false;

    return mBoard->mGridSquareType[mBoard->PixelToGridXKeepOnBoard(mX + 75, mY)][mRow] == GRIDSQUARE_HIGH_GROUND;
}

// ==========================================================================
// Zombie::UpdateZombieRiseFromGrave(void)
// @001A9588  240 bytes
// ==========================================================================
// The altitude curve runs from -150/-200 to -40/0 over 50 frames and is scaled
// by mScaleZombie for a zombie that rises out of the pool. Once the counter
// reaches zero the zombie picks its walking phase for its type.
int Zombie::UpdateZombieRiseFromGrave()
{
    if (mInPool)
        mAltitude = (float)TodAnimateCurve(50, 0, mPhaseCounter, -150, -40, CURVE_LINEAR) * mScaleZombie;
    else
        mAltitude = (float)TodAnimateCurve(50, 0, mPhaseCounter, -200, 0, CURVE_LINEAR);

    if (mPhaseCounter != 0)
        return 0;

    switch (mZombieType)
    {
        case ZOMBIE_POLEVAULTER:
            mZombiePhase = PHASE_POLEVAULTER_PRE_VAULT;
            break;
        case ZOMBIE_NEWSPAPER:
            mZombiePhase = PHASE_NEWSPAPER_READING;
            break;
        case ZOMBIE_DANCER:
            mZombiePhase = PHASE_DANCER_DANCING_IN;
            break;
        case ZOMBIE_POGO:
            mZombiePhase = PHASE_POGO_BOUNCING;
            break;
        case ZOMBIE_LADDER:
            mZombiePhase = PHASE_LADDER_CARRYING;
            break;
        default:
            mZombiePhase = PHASE_ZOMBIE_NORMAL;
            break;
    }

    if (IsOnHighGround())
        mAltitude = 30.0f;

    if (mInPool)
    {
        ReanimIgnoreClipRect("Zombie_duckytube", true);
        ReanimIgnoreClipRect("Zombie_whitewater", true);
        ReanimIgnoreClipRect("Zombie_outerarm_hand", true);
        ReanimIgnoreClipRect("Zombie_innerarm3", true);
    }

    return 0;
}

// ==========================================================================
// Zombie::UpdateZombieFalling(void)
// @001A9688  80 bytes
// ==========================================================================
bool Zombie::UpdateZombieFalling()
{
    mAltitude -= 1.0f;
    if (mZombiePhase == PHASE_POLEVAULTER_PRE_VAULT)
        mAltitude -= 1.0f;

    bool aOnHighGround = IsOnHighGround();
    float aGroundHeight = aOnHighGround ? 30.0f : 0.0f;
    if (mAltitude <= aGroundHeight)
    {
        mAltitude = aGroundHeight;
        mZombieHeight = HEIGHT_ZOMBIE_NORMAL;
    }
    return aOnHighGround;
}

// ==========================================================================
// Zombie::GetDrawPos(ZombieDrawPosition &)
// @001A96DC  1328 bytes
// ==========================================================================
// Fills the 28-byte draw position. Image offsets are mPosX-mX / mPosY-mY.
// Head X/Y come from mIsEating (47, 4) or from mFrame; mArmY is half of
// mHeadY. Type offsets, then the phase clip, follow. The return register is unused.
void Zombie::GetDrawPos(ZombieDrawPosition & aDrawPos)
{
    ZombieDrawPosition &aPos = aDrawPos;

    aPos.mImageOffsetX = mPosX - (float)mX;
    aPos.mImageOffsetY = mPosY - (float)mY;

    if (mIsEating)
    {
        aPos.mHeadX = 47;
        aPos.mHeadY = 4;
    }
    else
    {
        switch (mFrame)
        {
            case 0:
                aPos.mHeadX = 50;
                aPos.mHeadY = 2;
                break;
            case 1:
            case 7:
                aPos.mHeadX = 49;
                aPos.mHeadY = 1;
                break;
            case 2:
            case 8:
                aPos.mHeadX = 49;
                aPos.mHeadY = 2;
                break;
            case 3:
            case 5:
                aPos.mHeadX = 48;
                aPos.mHeadY = 4;
                break;
            case 4:
                aPos.mHeadX = 48;
                aPos.mHeadY = 5;
                break;
            case 6:
                aPos.mHeadX = 48;
                aPos.mHeadY = 2;
                break;
            case 10:
                aPos.mHeadX = 50;
                aPos.mHeadY = 5;
                break;
            default:
                aPos.mHeadX = 50;
                aPos.mHeadY = 4;
                break;
        }
    }

    aPos.mArmY = aPos.mHeadY / 2;

    switch (mZombieType)
    {
        case ZOMBIE_FOOTBALL:
            aPos.mImageOffsetY -= 16.0f;
            break;
        case ZOMBIE_YETI:
            aPos.mImageOffsetY -= 20.0f;
            break;
        case ZOMBIE_CATAPULT:
            aPos.mImageOffsetX -= 25.0f;
            aPos.mImageOffsetY -= 18.0f;
            break;
        case ZOMBIE_POGO:
            aPos.mImageOffsetY += 16.0f;
            break;
        case ZOMBIE_BALLOON:
            aPos.mImageOffsetY += 17.0f;
            break;
        case ZOMBIE_POLEVAULTER:
            aPos.mImageOffsetX -= 6.0f;
            aPos.mImageOffsetY -= 11.0f;
            break;
        case ZOMBIE_ZAMBONI:
            aPos.mImageOffsetX += 68.0f;
            aPos.mImageOffsetY -= 23.0f;
            break;
        case ZOMBIE_GARGANTUAR:
        case ZOMBIE_REDEYE_GARGANTUAR:
            aPos.mImageOffsetY -= 8.0f;
            break;
        case ZOMBIE_BOBSLED:
            aPos.mImageOffsetY -= 12.0f;
            break;
        default:
            break;
    }

    // Rising from a grave: the body starts below the ground and is clipped to the
    // part that has come up so far.
    if (mZombiePhase == PHASE_RISING_FROM_GRAVE)
    {
        aPos.mBodyY = -mAltitude;
        if (mInPool)
        {
            aPos.mClipHeight = aPos.mBodyY;
        }
        else
        {
            float aHeightLimit = (float)mPhaseCounter;
            if (aHeightLimit > 40.0f)
                aHeightLimit = 40.0f;
            aPos.mClipHeight = aPos.mBodyY + aHeightLimit;
        }

        if (IsOnHighGround())
            aPos.mBodyY -= 30.0f;
        return;
    }

    if (mZombieType == ZOMBIE_DOLPHIN_RIDER)
    {
        aPos.mBodyY = -mAltitude;
        aPos.mClipHeight = -200.0f;

        switch (mZombiePhase)
        {
            case PHASE_DOLPHIN_INTO_POOL:
            {
                Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
                if (aBodyReanim->mAnimTime >= 0.56f && aBodyReanim->mAnimTime <= 0.65f)
                {
                    aPos.mClipHeight = 0.0f;
                    return;
                }
                if (aBodyReanim->mAnimTime < 0.75f)
                    return;
                break;
            }
            case PHASE_DOLPHIN_RIDING:
                aPos.mImageOffsetX += 70.0f;
                aPos.mClipHeight = -mAltitude - (mZombieHeight == HEIGHT_DRAGGED_UNDER ? 15.0f : 10.0f);
                return;
            case PHASE_DOLPHIN_IN_JUMP:
            {
                aPos.mImageOffsetX = (mAltitude + aPos.mImageOffsetX) + 70.0f;

                Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
                if (aBodyReanim->mAnimTime > 0.06f)
                {
                    if (aBodyReanim->mAnimTime >= 0.5f && aBodyReanim->mAnimTime <= 0.76f)
                        aPos.mClipHeight = -13.0f;
                    return;
                }
                break;
            }
            default:
                if (mZombiePhase == PHASE_ZOMBIE_DYING || mZombiePhase == PHASE_DOLPHIN_WALKING_IN_POOL)
                {
                    aPos.mImageOffsetY += 50.0f;
                    if (mZombiePhase == PHASE_ZOMBIE_DYING)
                        aPos.mClipHeight = 44.0f - mAltitude;
                    else if (mZombieHeight == HEIGHT_DRAGGED_UNDER)
                        aPos.mClipHeight = 36.0f - mAltitude;
                }
                else if ((mZombiePhase == PHASE_DOLPHIN_WALKING
                          || mZombiePhase == PHASE_DOLPHIN_WALKING_WITHOUT_DOLPHIN)
                         && mZombieHeight == HEIGHT_OUT_OF_POOL)
                {
                    aPos.mClipHeight = -mAltitude;
                }
                return;
        }

        aPos.mClipHeight = -10.0f - mAltitude;
        return;
    }

    if (mZombieType == ZOMBIE_SNORKEL)
    {
        aPos.mBodyY = -mAltitude;
        aPos.mClipHeight = -200.0f;

        if (mZombiePhase == PHASE_SNORKEL_INTO_POOL)
        {
            Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
            if (aBodyReanim->mAnimTime >= 0.8f)
                aPos.mClipHeight = -10.0f;
        }
        else if (mInPool)
        {
            aPos.mClipHeight = (-5.0f - mAltitude) + (1.0f - mScaleZombie) * 20.0f;
        }
        return;
    }

    if (!mInPool)
    {
        if (mZombiePhase != PHASE_DANCER_RISING)
        {
            if (mZombiePhase == PHASE_DIGGER_RISING || mZombiePhase == PHASE_DIGGER_RISE_WITHOUT_AXE)
            {
                aPos.mBodyY = -mAltitude;
                if (mPhaseCounter > 20)
                {
                    aPos.mClipHeight = -mAltitude;
                    return;
                }
            }
            else if (mZombieType != ZOMBIE_BUNGEE)
            {
                aPos.mClipHeight = -200.0f;
                aPos.mBodyY = -mAltitude;
                return;
            }
            else
            {
                aPos.mImageOffsetX -= 18.0f;
                aPos.mBodyY = -mAltitude;
                if (IsOnHighGround())
                    aPos.mBodyY -= 30.0f;
            }

            aPos.mClipHeight = -200.0f;
            return;
        }

        aPos.mBodyY = -mAltitude;
        aPos.mClipHeight = -mAltitude;
        if (IsOnHighGround())
            aPos.mBodyY -= 30.0f;
        return;
    }

    float aClipHeight = (-7.0f - mAltitude) + (1.0f - mScaleZombie) * 10.0f;
    aPos.mBodyY = -mAltitude;
    aPos.mClipHeight = aClipHeight;
    if (mIsEating)
        aPos.mClipHeight = aClipHeight + 7.0f;

    return;
}

// ==========================================================================
// Zombie::UpdateReanim(void)
// @001A9C0C  694 bytes
// ==========================================================================
// A live body reanim is updated on the way out and returned as a pointer. The
// catapult pole id is the word at ReanimTrackId_zombie_catapult_pole. A dying
// zamboni/catapult shakes on CURVE_EASE_OUT (immediate 3), not linear.
Reanimation *Zombie::UpdateReanim()
{
    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr || aBodyReanim->mDead)
        return aBodyReanim;

    // Damage state 2 or dying: the pole is the damaged image, and keeps the
    // ball only while the current frame still shows one and a ball is loaded.
    // An unloaded pole (mSummonCounter == 0) is forced to the bare image.
    if (mZombieType == ZOMBIE_CATAPULT)
    {
        const char* aPoleTrack = ReanimTrackId_zombie_catapult_pole;
        bool aNoBall = mSummonCounter == 0;
        if (GetBodyDamageIndex() == 2 || mZombiePhase == PHASE_ZOMBIE_DYING)
        {
            Reanimation *aPoleReanim = mApp->ReanimationGet(mBodyReanimID);
            Sexy::Image *aPoleImage = IMAGE_REANIM_ZOMBIE_CATAPULT_POLE_DAMAGE;
            if (aPoleReanim->GetCurrentTrackImage(aPoleTrack)
                    == IMAGE_REANIM_ZOMBIE_CATAPULT_POLE_WITHBALL
                && !aNoBall)
            {
                aPoleImage = IMAGE_REANIM_ZOMBIE_CATAPULT_POLE_DAMAGE_WITHBALL;
            }
            aPoleReanim->SetImageOverride(aPoleTrack, aPoleImage);
        }
        else if (aNoBall)
        {
            aBodyReanim->SetImageOverride(aPoleTrack, IMAGE_REANIM_ZOMBIE_CATAPULT_POLE);
        }
    }

    ZombieDrawPosition aDrawPos;
    GetDrawPos(aDrawPos);
    ZombieDrawPosition &aPos = aDrawPos;

    float aPosX = aPos.mImageOffsetX + 15.0f;
    float aPosY = (aPos.mImageOffsetY + aPos.mBodyY) - 8.0f;

    // A dying zamboni or catapult shakes itself apart; a damaged one twitches.
    if (mZombieType == ZOMBIE_ZAMBONI || mZombieType == ZOMBIE_CATAPULT)
    {
        if (mZombiePhase != PHASE_ZOMBIE_BURNED)
        {
            if (mZombiePhase == PHASE_ZOMBIE_DYING)
            {
                float aShake = TodAnimateCurveFloatTime(0.7f, 1.0f, aBodyReanim->mAnimTime,
                                                        0.0f, 1.0f, CURVE_EASE_OUT);
                aPosX += RandRangeFloat(-aShake, aShake);
                aPosY += RandRangeFloat(-aShake, aShake);
            }
            else if (mBodyHealth <= 199)
            {
                aPosX += RandRangeFloat(-1.0f, 1.0f);
                aPosY += RandRangeFloat(-1.0f, 1.0f);
            }
        }
    }

    if (mZombieType == ZOMBIE_FOOTBALL && mScaleZombie < 1.0f)
        aPosY += (1.0f - mScaleZombie) * 20.0f;

    // A dancer facing the wrong way is mirrored, except while it is eating and
    // except when it has been mind-controlled.
    int aWalkingBackwards = IsWalkingBackwards();
    if (mZombieType == ZOMBIE_DANCER || mZombieType == ZOMBIE_BACKUP_DANCER)
    {
        if (mZombiePhase == PHASE_DANCER_DANCING_IN
            || mZombiePhase == PHASE_DANCER_RAISE_RIGHT_1
            || mZombiePhase == PHASE_DANCER_RAISE_RIGHT_2)
        {
            aWalkingBackwards = mIsEating ? 0 : 1;
        }
        else
        {
            aWalkingBackwards = 0;
        }

        if (mMindControlled)
            aWalkingBackwards = aWalkingBackwards ? 0 : 1;
    }

    if (aWalkingBackwards)
        aPosX += mScaleZombie * 90.0f;

    // The reanimation carries no transform of its own: the zombie writes the
    // overlay matrix directly.
    aBodyReanim->mOverlayMatrix.m10 = 0.0f;
    aBodyReanim->mOverlayMatrix.m20 = 0.0f;
    aBodyReanim->mOverlayMatrix.m21 = 0.0f;
    aBodyReanim->mOverlayMatrix.m22 = 1.0f;
    aBodyReanim->mOverlayMatrix.m00 = mScaleZombie;
    aBodyReanim->mOverlayMatrix.m11 = mScaleZombie;
    aBodyReanim->mOverlayMatrix.m02 = (aPosX + 30.0f) - (mScaleZombie * 30.0f);
    aBodyReanim->mOverlayMatrix.m12 = (aPosY + 120.0f) - (mScaleZombie * 120.0f);
    if (aWalkingBackwards)
        aBodyReanim->mOverlayMatrix.m00 = -mScaleZombie;

    Reanimation *aMoweredReanim = mApp->ReanimationTryToGet(mMoweredReanimID);
    if (aMoweredReanim != nullptr)
    {
        aMoweredReanim->Update();

        Sexy::SexyTransform2D aOverlayMatrix;
        aMoweredReanim->GetAttachmentOverlayMatrix(0, aOverlayMatrix);

        float aScaleX = aBodyReanim->mOverlayMatrix.m00;
        float aScaleY = aBodyReanim->mOverlayMatrix.m11;
        aOverlayMatrix.m00 *= aScaleX;
        aOverlayMatrix.m01 *= aScaleY;
        aOverlayMatrix.m02 = aScaleY + aScaleX * aOverlayMatrix.m02;
        aOverlayMatrix.m10 *= aScaleX;
        aOverlayMatrix.m11 *= aScaleY;
        aOverlayMatrix.m12 = aBodyReanim->mOverlayMatrix.m12 + aScaleY * aOverlayMatrix.m12;

        aBodyReanim->mOverlayMatrix = aOverlayMatrix;
    }

    aBodyReanim->Update();
    return aBodyReanim;
}

// ==========================================================================
// Zombie::DrawBungeeTarget(Sexy::Graphics *)
// @001A9EE4  250 bytes
// ==========================================================================
int Zombie::DrawBungeeTarget(Sexy::Graphics * aGraphics)
{
    int result = IsOnBoard();
    if (result != 0)
    {
        result = mApp->IsFinalBossLevel();
        if (result == 0
            && (unsigned int)(mZombiePhase - PHASE_BUNGEE_RISING) > 1
            && mTargetPlantID == PLANTID_NULL)
        {
            ZombieDrawPosition aDrawPos;
            GetDrawPos(aDrawPos);
            ZombieDrawPosition &aPos = aDrawPos;

            float aPosY = ((aPos.mImageOffsetY + aPos.mBodyY) + 60.0f) + (float)mY;
            float aPosX = (float)mX + 10.0f;
            if ((unsigned int)(mZombiePhase - PHASE_BUNGEE_DIVING) <= 1)
            {
                aPosX += TodAnimateCurveFloat(3000, 2600, (int)mAltitude, 30.0f, 0.0f, CURVE_LINEAR);
                aPosY += TodAnimateCurveFloat(3000, 2600, (int)mAltitude, -592.0f, 0.0f, CURVE_LINEAR);
            }

            aGraphics->DrawImageF(IMAGE_BUNGEETARGET, aPosX, aPosY + mAltitude);
  return 0;
        }
    }
    return result;
}

// ==========================================================================
// Zombie::CheckForHighGround(void)
// @001A9FEC  46 bytes
// ==========================================================================
// r0 is `this` when the height is not normal or the type is bungee. Otherwise
// it is IsOnHighGround's 0/1, and that same test writes height 4 (stepping up)
// or 5 (stepping off).
void Zombie::CheckForHighGround()
{
    if (mZombieHeight != HEIGHT_ZOMBIE_NORMAL || mZombieType == ZOMBIE_BUNGEE)
        return;

    bool aOnHighGround = IsOnHighGround();
    if (mOnHighGround)
    {
        if (!aOnHighGround)
            mZombieHeight = HEIGHT_DOWN_OFF_HIGH_GROUND;
    }
    else if (aOnHighGround)
    {
        mZombieHeight = HEIGHT_UP_TO_HIGH_GROUND;
        mOnHighGround = true;
    }
    return;
}

// ==========================================================================
// Zombie::StartMindControlled(void)
// @001AA01C  150 bytes
// ==========================================================================
void Zombie::StartMindControlled()
{
    // PlaySample returns void in this tree; the dump's r0 is a leftover.
    mApp->PlaySample(SOUND_MINDCONTROLLED, true);

    ZombieType aZombieType = mZombieType;
    mMindControlled = true;
    mLastPortalX = -1;

    if (aZombieType == ZOMBIE_DANCER)
    {
        mFollowerZombieID[0] = ZOMBIEID_NULL;
        mFollowerZombieID[1] = ZOMBIEID_NULL;
        mFollowerZombieID[2] = ZOMBIEID_NULL;
        mFollowerZombieID[3] = ZOMBIEID_NULL;
    }
    else
    {
        Zombie *aBackupDancer = mBoard->ZombieTryToGet(mRelatedZombieID);

        if (aZombieType == ZOMBIE_BACKUP_DANCER)
        {
            if (aBackupDancer != nullptr)
            {
                ZombieID aMyID = (ZombieID)mBoard->ZombieGetID(this);

                for (int i = 0; i < 4; i++)
                {
                    if (aBackupDancer->mFollowerZombieID[i] == aMyID)
                    {
                        aBackupDancer->mFollowerZombieID[i] = ZOMBIEID_NULL;
                        break;
                    }
                }

                mRelatedZombieID = ZOMBIEID_NULL;
            }
        }
        else
        {
            if (aBackupDancer != nullptr)
            {
                aBackupDancer->mRelatedZombieID = ZOMBIEID_NULL;
                mRelatedZombieID = ZOMBIEID_NULL;
            }
        }
    }

    return;
}

// ==========================================================================
// Zombie::BungeeDropPlant(void)
// @001AA0BC  86 bytes
// ==========================================================================
// r0 is whatever the last instruction left: `this` if it is not grabbing or
// the target id is 0, mMaxSize if the slot index is out of range, the slot
// address if the id word does not match, otherwise the plant (or Plant::Die).
// No caller reads it.
void Zombie::BungeeDropPlant()
{
    if (mZombiePhase != PHASE_BUNGEE_GRABBING)
        return;
    if (mTargetPlantID == PLANTID_NULL)
        return;

    unsigned short aPlantID = (unsigned short)mTargetPlantID;
    if (aPlantID >= mBoard->mPlants.mMaxSize)
        return;

    PlantSlot *aSlots = mBoard->mPlants.mBlock;
    PlantSlot *aSlot = &aSlots[aPlantID];
    if (mTargetPlantID != (PlantID)aSlot->mID)
        return;

    Plant *aPlant = &aSlot->mItem;
    if (aPlant->mOnBungeeState == GETTING_GRABBED_BY_BUNGEE)
        aPlant->mOnBungeeState = NOT_ON_BUNGEE;
    else if (aPlant->mOnBungeeState == RISING_WITH_BUNGEE)
        aPlant->Die();

    mTargetPlantID = PLANTID_NULL;
    return;
}

// ==========================================================================
// Zombie::PlayZombieAppearSound(void)
// @001AA114  40 bytes
// ==========================================================================
void Zombie::PlayZombieAppearSound()
{
    switch (mZombieType)
    {
        case ZOMBIE_DOLPHIN_RIDER:
            mApp->PlayFoley(FOLEY_DOLPHIN_APPEARS);
            break;
        case ZOMBIE_BALLOON:
            mApp->PlayFoley(FOLEY_BALLOONINFLATE);
            break;
        case ZOMBIE_ZAMBONI:
            mApp->PlayFoley(FOLEY_ZAMBONI);
            break;
        default:
            break;
    }
}

// ==========================================================================
// Zombie::StartZombieSound(void)
// @001AA13C  62 bytes
// ==========================================================================
void Zombie::StartZombieSound()
{
    if (!mPlayingSong)
    {
        if (mZombiePhase == PHASE_JACK_IN_THE_BOX_RUNNING)
        {
            if (mHasHead)
            {
                mApp->PlayFoley(FOLEY_JACKINTHEBOX);
                mPlayingSong = true;
            }
        }
        else if (mZombiePhase == PHASE_DIGGER_TUNNELING)
        {
            mApp->PlayFoley(FOLEY_DIGGER);
            mPlayingSong = true;
        }
    }

    return;
}

// ==========================================================================
// Zombie::SetRow(int)
// @001AA17C  24 bytes
// ==========================================================================
int Zombie::SetRow(int theRow)
{
    mRow = theRow;
    // 303000 is RENDER_LAYER_ZOMBIE; the fourth argument of the zombie layer is
    // the one a plain zombie sits in.
    int aRenderOrder = Board::MakeRenderOrder((RenderLayer)303000, mRow, 4);
    mRenderOrder = aRenderOrder;
    return aRenderOrder;
}

// ==========================================================================
// Zombie::GetPosYBasedOnRow(int)
// @001AA194  120 bytes
// ==========================================================================
float Zombie::GetPosYBasedOnRow(int theRow)
{
    if (!IsOnBoard())
        return 0.0f;

    if (IsOnHighGround())
    {
        // 4 is HEIGHT_UP_TO_HIGH_GROUND (Zombie.h has no ZombieHeight enum).
        if (mAltitude < 30.0f)
            mZombieHeight = 4;
        mOnHighGround = true;
    }

    float aPosY = mBoard->GetPosYBasedOnRow(mPosX + 40.0f, theRow);
    // A balloon rides 30 above the row line and a pogo 16, both on top of the
    // usual 30-pixel offset every airborne zombie takes.
    if (mZombieType == ZOMBIE_BALLOON)
        return (aPosY - 30.0f) - 30.0f;
    if (mZombieType == ZOMBIE_POGO)
        return (aPosY - 30.0f) - 16.0f;
    return aPosY - 30.0f;
}

// ==========================================================================
// Zombie::SummonBackupDancer(int,int)
// @001AA210  280 bytes
// ==========================================================================
int Zombie::SummonBackupDancer(int theRow, int thePosX)
{
    if (!mBoard->RowCanHaveZombieType(theRow, ZOMBIE_BACKUP_DANCER))
        return 0;
    if (thePosX < -80)
        return 0;

    Zombie *aZombie = mBoard->AddZombie(ZOMBIE_BACKUP_DANCER, mFromWave, false);
    if (aZombie == nullptr)
        return 0;

    aZombie->mPosX = (float)thePosX;
    aZombie->mPosY = GetPosYBasedOnRow(theRow);
    aZombie->SetRow(theRow);
    aZombie->mX = (int)aZombie->mPosX;
    aZombie->mY = (int)aZombie->mPosY;

    // 50 is PHASE_DANCER_RISING and -200 is the dancer's rise height; the
    // counter is 150 frames of rising before anything else happens.
    aZombie->mZombiePhase = (ZombiePhase)50;
    aZombie->mPhaseCounter = 150;
    aZombie->mAltitude = -200.0f;
    aZombie->mRelatedZombieID = (ZombieID)mBoard->ZombieGetID(this);

    aZombie->SetAnimRate(0.0f);
    aZombie->mMindControlled = mMindControlled;

    int aParticleX = (int)aZombie->mPosX + 60;
    int aParticleY = (int)aZombie->mPosY + 110;
    if (aZombie->IsOnHighGround())
        aParticleY -= 30;

    // 307000 is RENDER_LAYER_PARTICLE, 34 is PARTICLE_DANCER_RISE and
    // FOLEY_GRAVESTONE_RUMBLE is the gravestone the dancer claws out of.
    int aRenderOrder = Board::MakeRenderOrder((RenderLayer)307000, theRow, 0);
    mApp->AddTodParticle((float)aParticleX, (float)aParticleY, aRenderOrder,
                         (ParticleEffect)34);
    mApp->PlayFoley(FOLEY_GRAVESTONE_RUMBLE);

    return mBoard->ZombieGetID(aZombie);
}

// ==========================================================================
// Zombie::SummonBackupDancers(void)
// @001AA328  120 bytes
// ==========================================================================
int Zombie::SummonBackupDancers()
{
    // Only a dancer with its head on still summons; each of the four follower
    // slots is filled by one dancer standing beside the leader, and the row is
    // stepped one up for the second slot and one down for the first. The
    // return value is the last slot's zombie id, which no caller reads.
    int aResult = 0;
    if (mHasHead)
    {
        for (int i = 0; i < 4; i++)
        {
            aResult = mBoard->ZombieTryToGet(mFollowerZombieID[i]) != nullptr;
            if (aResult == 0)
            {
                int aRow = mRow;
                int aPosX = (int)mPosX;
                if (i == 2)
                    aPosX = (int)(mPosX - 100.0f);
                else if (i == 3)
                    aPosX = (int)(mPosX + 100.0f);
                else if (i == 1)
                    aRow++;
                else
                    aRow--;

                aResult = SummonBackupDancer(aRow, aPosX);
                mFollowerZombieID[i] = (ZombieID)aResult;
            }
        }
    }
    return aResult;
}

// ==========================================================================
// Zombie::UpdateZombieRect(bool)
// @001AA3EC  156 bytes
// ==========================================================================
void Zombie::UpdateZombieRect(bool theAttackRect)
{
    if (mCachedZombieRect.mWidth == 0 || theAttackRect)
    {
        mCachedZombieRect.mX = mZombieRect.mX;
        mCachedZombieRect.mY = mZombieRect.mY;
        mCachedZombieRect.mWidth = mZombieRect.mWidth;
        mCachedZombieRect.mHeight = mZombieRect.mHeight;
        if (IsWalkingBackwards())
            mCachedZombieRect.mX = mWidth - mCachedZombieRect.mX - mCachedZombieRect.mWidth;

        ZombieDrawPosition aDrawPos;
        GetDrawPos(aDrawPos);
        ZombieDrawPosition &aPos = aDrawPos;

        mCachedZombieRect.mX += mX;
        float aRectY = (float)mY + aPos.mBodyY;
        int aOldHeight = mCachedZombieRect.mHeight;
        mCachedZombieRect.mY += (int)aRectY;
        // A clip height of exactly -100 (or below) means "draw it whole", so
        // the cached height is left alone.
        if (aPos.mClipHeight > -100.0f)
            mCachedZombieRect.mHeight = (int)((float)aOldHeight - aPos.mClipHeight);
    }
}

// ==========================================================================
// Zombie::GetZombieRect(void)
// @001AA48C  36 bytes
// ==========================================================================
Sexy::Rect Zombie::GetZombieRect()
{
    UpdateZombieRect(false);
    return mCachedZombieRect;
}

// ==========================================================================
// Zombie::ZombieTargetLeadX(float)
// @001AA4B0  106 bytes
// ==========================================================================
float Zombie::ZombieTargetLeadX(float theTime)
{
    // A chilled zombie leads its target at 40% of its speed; a zombie that is
    // not walking does not lead it at all.
    float aLeadX = mVelX;
    if (mChilledCounter > 0)
        aLeadX *= 0.4f;
    if (IsWalkingBackwards())
        aLeadX = -aLeadX;

    aLeadX *= theTime;
    if (ZombieNotWalking())
        aLeadX = 0.0f;

    Sexy::Rect aZombieRect = GetZombieRect();
    return (float)(aZombieRect.mX + aZombieRect.mWidth / 2) - aLeadX;
}

// ==========================================================================
// Zombie::IsStandingOnSpikeweed(void)
// @001AA524  136 bytes
// ==========================================================================
Plant * Zombie::IsStandingOnSpikeweed()
{
    // A zamboni and a catapult roll straight over spikeweed.
    if (mZombieType == ZOMBIE_ZAMBONI || mZombieType == ZOMBIE_CATAPULT)
        return nullptr;

    Sexy::Rect aZombieRect = GetZombieRect();

    Plant *aPlant = nullptr;
    while (mBoard->IteratePlants(aPlant))
    {
        if (aPlant->mRow == mRow
            && aPlant->IsSpiky()
            && aPlant->NotOnGround() == 0
            && (!mOnHighGround || aPlant->IsOnHighGround()))
        {
            Sexy::Rect aAttackRect = aPlant->GetPlantAttackRect((PlantWeapon)0);
            if (GetRectOverlap(aAttackRect, aZombieRect) > 0)
                return aPlant;
        }
    }
    return nullptr;
}

// ==========================================================================
// Zombie::TrySpawnLevelAward(void)
// @001AA5AC  734 bytes
// ==========================================================================
bool Zombie::TrySpawnLevelAward()
{
    bool aOnBoard = IsOnBoard();
    if (!aOnBoard)
        return false;
    if (mBoard->HasLevelAwardDropped())
        return false;
    if (mBoard->mLevelComplete)
        return false;
    if (mDroppedLoot)
        return false;

    LawnApp *aApp = mApp;
    if (aApp->mGameMode == GAMEMODE_MP_VS)
        return false;

    // Only the last boss of a boss level, the completed pot of a Scary Potter
    // level and the last wave of anything else may drop the level award.
    if (aApp->IsFinalBossLevel())
    {
        if (mZombieType != ZOMBIE_BOSS)
            return false;
    }
    else if (aApp->IsScaryPotterLevel())
    {
        if (!mBoard->mChallenge->ScaryPotterIsCompleted())
            return false;
    }
    else
    {
        if (aApp->IsContinuousChallenge())
            return false;
        if (mBoard->mCurrentWave < mBoard->mNumWaves || mBoard->AreEnemyZombiesOnScreen())
            return false;
    }

    if (aApp->IsWhackAZombieLevel())
    {
        if (mBoard->mZombieCountDown > 0)
            return false;
    }

    mBoard->mLevelAwardSpawned = true;
    // The ARM sets R1 to 1 right here (`MOVS R1,#1` at 0x1AA616), so the level
    // is marked WON; the transcription dropped the argument.
    aApp->SetBoardResult(BOARDRESULT_WON);

    Sexy::Rect aZombieRect = GetZombieRect();
    int aCenterX = aZombieRect.mX + aZombieRect.mWidth / 2;
    int aCenterY = aZombieRect.mY + aZombieRect.mHeight / 2;

    if (!mBoard->IsSurvivalStageWithRepick())
        mBoard->RemoveAllZombies();

    // The award itself: a completed Scary Potter pot raises the puzzle flag, an
    // adventure level gets the fixed gift its level number asks for, a survival
    // stage repick and Last Stand fade the level out, and everything else falls
    // back to a trophy or the gold sunflower.
    int aAwardType;
    if (aApp->IsScaryPotterLevel() && !mBoard->IsFinalScaryPotterStage())
    {
        int aGridX = mBoard->PixelToGridXKeepOnBoard((int)(mPosX + 75.0f), (int)mPosY);
        mBoard->mChallenge->PuzzlePhaseComplete(aGridX, mRow);
        aAwardType = 0;
    }
    else if (aApp->IsAdventureMode() && mBoard->mLevel <= 50)
    {
        int aLevel = mBoard->mLevel;
        if (aLevel == 9 || aLevel == 19 || aLevel == 29 || aLevel == 39 || aLevel == 49)
            aAwardType = COIN_NOTE;
        else if (aLevel == 50)
            aAwardType = aApp->HasFinishedAdventure() ? COIN_AWARD_MONEY_BAG
                                                      : COIN_AWARD_SILVER_SUNFLOWER;
        else if (aApp->HasFinishedAdventure())
            aAwardType = COIN_AWARD_MONEY_BAG;
        else
        {
            switch (aLevel)
            {
            case 4:  aAwardType = COIN_SHOVEL; break;
            case 14: aAwardType = COIN_ALMANAC; break;
            case 24: aAwardType = COIN_CARKEYS; break;
            case 34: aAwardType = COIN_TACO; break;
            case 44: aAwardType = COIN_WATERING_CAN; break;
            default: aAwardType = COIN_FINAL_SEED_PACKET; break;
            }
        }
    }
    else if (mBoard->IsSurvivalStageWithRepick())
    {
        mBoard->FadeOutLevel();
        aAwardType = 0;
    }
    else if (mBoard->IsLastStandStageWithRepick())
    {
        mBoard->FadeOutLevel();
        aApp->PlayFoley(FOLEY_SPAWN_SUN);
        for (int aOffset = 0; aOffset != 50; aOffset += 5)
            mBoard->AddCoin(aCenterX + aOffset, aCenterY, COIN_SUN, (CoinMotion)3);
        aAwardType = 0;
    }
    else if (aApp->IsAdventureMode() || aApp->HasBeatenChallenge(aApp->mGameMode))
    {
        aAwardType = COIN_AWARD_MONEY_BAG;
    }
    else
    {
        aAwardType = (aApp->TrophiesNeedForGoldSunflower() == 1) ? COIN_AWARD_GOLD_SUNFLOWER
                                                                 : COIN_TROPHY;
    }

    // A boss drops its award as six coins in a ring, everything else as one.
    int aCoinMotion = (mZombieType == ZOMBIE_BOSS) ? 6 : 3;
    if (aAwardType != 0)
    {
        aApp->PlayFoley(FOLEY_SPAWN_SUN);
        if (aApp->mGameMode != GAMEMODE_CHALLENGE_HEAVY_WEAPON
            || aAwardType == COIN_AWARD_MONEY_BAG || aAwardType == COIN_TROPHY)
            mBoard->AddCoin(aCenterX, aCenterY, (CoinType)aAwardType, (CoinMotion)aCoinMotion);
        else
            mBoard->AddCoinHeavyWeapon(aCenterX, aCenterY, (CoinType)aAwardType);
    }

    mDroppedLoot = true;
    if (mBoard->mGamepadControls[1]->mGamepadIndex == -1
        || mBoard->mGamepadControls[0]->mGamepadIndex == -1)
        return aOnBoard;

    // `+1816` on the player record is unkMems6[2], the low half of a 64-bit set
    // of finished levels keyed by Board::mLevel.
    int *aFinishedLevels = &mApp->mPlayerInfo->mProgress[2];
    int aAwardLevel = mBoard->mLevel;
    if (aAwardLevel < 32)
        aFinishedLevels[0] |= 1 << aAwardLevel;
    else
        aFinishedLevels[1] |= 1 << (aAwardLevel - 32);
    return aOnBoard;
}

// ==========================================================================
// Zombie::DropLoot(void)
// @001AA890  324 bytes
// ==========================================================================
void Zombie::DropLoot()
{
    int result = IsOnBoard();
    if (result != 0)
    {
        AlmanacPlayerDefeatedZombie(mZombieType);
        // Only a yeti counts as the yeti kill.
        if (mZombieType == ZOMBIE_YETI)
            mBoard->mKilledYeti = true;

        result = TrySpawnLevelAward();
        if (!mDroppedLoot)
        {
            result = mBoard->HasLevelAwardDropped();
            if (result == 0)
            {
                result = mBoard->CanDropLoot();
                if (result != 0)
                {
                    mDroppedLoot = true;
                    // The definition's +8 field is the loot this zombie drops.
                    int aLootType = GetZombieDefinition(mZombieType)->mZombieValue;
                    if (!mApp->IsLittleTroubleLevel() || Rand(4) == 0)
                    {
                        if (mApp->mGameMode != 24 && !mApp->IsIZombieLevel())
                        {
                            Sexy::Rect aZombieRect = GetZombieRect();
                            int aX = aZombieRect.mX + aZombieRect.mWidth / 2;
                            int aY = aZombieRect.mY + aZombieRect.mHeight / 4;

                            if (mZombieType == ZOMBIE_YETI)
                            {
                                mApp->PlayFoley(FOLEY_SPAWN_SUN);
                                if (mApp->mGameMode == GAMEMODE_CHALLENGE_HEAVY_WEAPON)
                                {
                                    // Four diamonds in a diamond, no motion.
                                    mBoard->AddCoinHeavyWeapon(aX, aY, COIN_DIAMOND);
                                    mBoard->AddCoinHeavyWeapon(aX + 20, aY, COIN_DIAMOND);
                                    mBoard->AddCoinHeavyWeapon(aX - 20, aY, COIN_DIAMOND);
                                    {
                                        mBoard->AddCoinHeavyWeapon(aX, aY + 30, COIN_DIAMOND);
                                        return;
                                    }
                                }
                                else
                                {
                                    // Four diamonds thrown to the left.
                                    mBoard->AddCoin(aX - 20, aY, COIN_DIAMOND, (CoinMotion)3);
                                    mBoard->AddCoin(aX - 30, aY, COIN_DIAMOND, (CoinMotion)3);
                                    mBoard->AddCoin(aX - 40, aY, COIN_DIAMOND, (CoinMotion)3);
                                    {
                                        mBoard->AddCoin(aX - 50, aY, COIN_DIAMOND, (CoinMotion)3);
                                        return;
                                    }
                                }
                            }
                            else
                            {
                                {
                                    mBoard->DropLootPiece(aX, aY, aLootType);
                                    return;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    return;
}

// ==========================================================================
// Zombie::GetZombieAttackRect(void)
// @001AA9D4  168 bytes
// ==========================================================================
Sexy::Rect Zombie::GetZombieAttackRect()
{
    // A zombie in mid-vault or mid-dolphin-jump has a fixed attack box instead
    // of its own.
    Sexy::Rect aAttackRect = mZombieAttackRect;
    if (mZombiePhase == PHASE_POLEVAULTER_IN_VAULT || mZombiePhase == PHASE_DOLPHIN_IN_JUMP)
        aAttackRect = Sexy::Rect(-40, 0, 100, 115);

    if (IsWalkingBackwards())
        aAttackRect.mX = mWidth - aAttackRect.mX - aAttackRect.mWidth;

    ZombieDrawPosition aDrawPos;
    GetDrawPos(aDrawPos);
    ZombieDrawPosition &aPos = aDrawPos;

    aAttackRect.mX += mX;
    aAttackRect.mY += (int)((float)mY + aPos.mBodyY);
    // -100 (or below) is "draw it whole", so the height is left alone.
    if (aPos.mClipHeight > -100.0f)
        aAttackRect.mHeight = (int)((float)aAttackRect.mHeight - aPos.mClipHeight);
    return aAttackRect;
}

// ==========================================================================
// Zombie::FindPlantTarget(ZombieAttackType)
// @001AAA80  92 bytes
// ==========================================================================
// r0 is the plant IteratePlants last produced, or 0 when the walk ends.
Plant * Zombie::FindPlantTarget(ZombieAttackType theAttackType)
{
    Sexy::Rect aAttackRect = GetZombieAttackRect();

    Plant *aPlant = nullptr;
    while (mBoard->IteratePlants(aPlant))
    {
        if (aPlant->mRow == mRow)
        {
            Sexy::Rect aPlantRect = aPlant->GetPlantRect();
            // Twenty pixels of overlap is the smallest bite worth taking.
            if (GetRectOverlap(aAttackRect, aPlantRect) > 19 && CanTargetPlant(aPlant, theAttackType) != 0)
                return aPlant;
        }
    }
    return nullptr;
}

// ==========================================================================
// Zombie::AnimateChewEffect(void)
// @001AAADC  260 bytes
// ==========================================================================
// r0 is `this` while a snorkel is still rising, the brain when an IZombie
// level has one, 0 when nothing is being chewed, AddTodParticle's id when a
// wallnut or tallnut spurts, and the plant otherwise. MakeRenderOrder's layer
// is the immediate 305000 (IDA prints it as a string).
void Zombie::AnimateChewEffect()
{
    if (mZombiePhase == PHASE_SNORKEL_UP_TO_EAT)
        return;

    if (mApp->IsIZombieLevel())
    {
        GridItem *aBrainTarget = mBoard->mChallenge->IZombieGetBrainTarget(this);
        if (aBrainTarget != nullptr)
        {
            if (aBrainTarget->mTransparentCounter < 25)
                aBrainTarget->mTransparentCounter = 25;
            return;
        }
    }

    Plant *aPlant = FindPlantTarget((ZombieAttackType)0);
    if (aPlant == nullptr)
        return;

    // Only a wallnut or a tallnut spurts the chew particles. The particle
    // call is what r0 holds on the way out of that path.
    if (aPlant->mSeedType == SEED_WALLNUT || aPlant->mSeedType == SEED_TALLNUT)
    {
        // 305000 is RENDER_LAYER_PROJECTILE, 36 the chew particle.
        int aRenderOrder = Board::MakeRenderOrder((RenderLayer)305000, mRow, 0);

        ZombieDrawPosition aDrawPos;
        GetDrawPos(aDrawPos);
        ZombieDrawPosition &aPos = aDrawPos;

        float aPosX = mPosX + 37.0f;
        float aPosY = (mPosY + aPos.mBodyY) + 40.0f;
        if (mZombieType == ZOMBIE_SNORKEL || mZombieType == ZOMBIE_DOLPHIN_RIDER)
        {
            aPosX -= 7.0f;
            aPosY += 70.0f;
        }
        else if (IsWalkingBackwards())
        {
            aPosX += 47.0f;
        }
        else if (mZombieType == ZOMBIE_BALLOON)
        {
            aPosY += 47.0f;
        }
        else if (mZombieType == ZOMBIE_IMP)
        {
            aPosY += 40.0f;
            aPosX += 24.0f;
        }

        mApp->AddTodParticle(aPosX, aPosY, aRenderOrder, (ParticleEffect)36);
    }

    if (aPlant->mEatenFlashCountdown < 25)
        aPlant->mEatenFlashCountdown = 25;
    return;
}

// ==========================================================================
// Zombie::CheckSquish(ZombieAttackType)
// @001AABF0  160 bytes
// ==========================================================================
GridItem * Zombie::CheckSquish(ZombieAttackType theAttackType)
{
    Sexy::Rect aZombieAttackRect = GetZombieAttackRect();

    Plant *aPlant = nullptr;
    while (mBoard->IteratePlants(aPlant) != 0)
    {
        if (mRow != aPlant->mRow)
            continue;

        Sexy::Rect aPlantRect = aPlant->GetPlantRect();
        if (GetRectOverlap(aZombieAttackRect, aPlantRect) > 19
            && CanTargetPlant(aPlant, theAttackType) != 0
            && !aPlant->IsSpiky())
        {
            SquishAllInSquare(aPlant->mPlantCol, aPlant->mRow, theAttackType);
            break;
        }
    }

    // IZombieSquishBrain returns void, so the brain target the dump shows coming
    // back in r0 is the argument it was called with.
    GridItem *aBrainTarget = nullptr;
    if (mApp->IsIZombieLevel())
    {
        aBrainTarget = mBoard->mChallenge->IZombieGetBrainTarget(this);
        if (aBrainTarget != nullptr)
            mBoard->mChallenge->IZombieSquishBrain(aBrainTarget);
    }
    return aBrainTarget;
}

// ==========================================================================
// Zombie::CheckForZombieStep(void)
// @001AAC90  24 bytes
// ==========================================================================
// A zamboni or catapult that still has tires tail-calls CheckSquish(1). Every
// other path returns `this`. 1 is ATTACKTYPE_DRIVE_OVER; ZombieAttackType is
// still `typedef int`.
void Zombie::CheckForZombieStep()
{
    if ((mZombieType == ZOMBIE_ZAMBONI || mZombieType == ZOMBIE_CATAPULT) && !mFlatTires)
        {
            CheckSquish((ZombieAttackType)1);
            return;
        }
    return;
}

// ==========================================================================
// Zombie::AddAttachedParticle(int,int,ParticleEffect)
// @001AACA8  128 bytes
// ==========================================================================
void Zombie::AddAttachedParticle(int thePosX, int thePosY, ParticleEffect theEffect)
{
    if (mDead)
        return;
    if (IsFullOfAttachments(mAttachmentID))
        return;

    TodParticleSystem* aParticle = mApp->AddTodParticle((float)(mX + thePosX), (float)(mY + thePosY), 0, theEffect);
    if (aParticle != nullptr)
        AttachParticle(mAttachmentID, aParticle, (float)thePosX, (float)thePosY);
}

// ==========================================================================
// Zombie::AddAttachedReanim(int,int,ReanimationType)
// @001AAD28  110 bytes
// ==========================================================================
Reanimation * Zombie::AddAttachedReanim(int thePosX, int thePosY, ReanimationType theReanimType)
{
    if (mDead)
        return nullptr;

    Reanimation *aReanim = mApp->AddReanimation((float)(mX + thePosX), (float)(mY + thePosY), 0, theReanimType);
    if (aReanim != nullptr)
        AttachReanim(mAttachmentID, aReanim, (float)thePosX, (float)thePosY);
    return aReanim;
}

// ==========================================================================
// Zombie::IsTangleKelpTarget(void)
// @001AAD98  70 bytes
// ==========================================================================
// Dragged-under is an immediate 1. Otherwise one of the tangle kelps is grabbing
// this zombie. Unlike IsTanglekelpTarget this walk does not test mDead.
int Zombie::IsTangleKelpTarget()
{
    if (mZombieHeight == HEIGHT_DRAGGED_UNDER)
        return 1;

    for (Plant *aPlant : mBoard->mTangleKelpTree)
    {
        if (aPlant->mState == STATE_TANGLEKELP_GRABBING
            && aPlant->mTargetZombieID == mBoard->ZombieGetID(this))
            return 1;
    }
    return 0;
}

// ==========================================================================
// Zombie::BalloonPropellerHatSpin(bool)
// @001AADE0  58 bytes
// ==========================================================================
// GetTrackInstanceByName returns the hat track; +0x44 of that instance is the
// AttachmentID FindReanimAttachment takes by address. A missing hat does
// nothing. Spinning uses the definition FPS; stopping freezes the hat.
void Zombie::BalloonPropellerHatSpin(bool theSpin)
{
    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
    ReanimatorTrackInstance *aHatTrack = aBodyReanim->GetTrackInstanceByName("hat");
    Reanimation *aHatReanim = FindReanimAttachment(aHatTrack->mAttachmentID);
    if (aHatReanim == nullptr)
        return;
    if (!theSpin)
    {
        aHatReanim->SetAnimRate(0.0f);
        return;
    }
    aHatReanim->SetAnimRate(aHatReanim->mDefinition->mFPS);
}

// ==========================================================================
// Zombie::ReanimShowPrefix(char const*,int)
// @001AAE20  34 bytes
// ==========================================================================
// A missing body reanim does nothing. Otherwise the prefix takes the group.
void Zombie::ReanimShowPrefix(char const* theTrackPrefix, int theRenderGroup)
{
    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr)
        return;
    aBodyReanim->AssignRenderGroupToPrefix(theTrackPrefix, theRenderGroup);
}

// ==========================================================================
// Zombie::ShowDoorArms(bool)
