// ==========================================================================
// Zombie::AttachShield(void)
// @001AAED0  154 bytes
// ==========================================================================
void Zombie::AttachShield()
{
    const char *aTrackName = nullptr;
    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);

    switch (mShieldType)
    {
        case SHIELDTYPE_DOOR:
            ShowDoorArms(true);
            ReanimShowPrefix("Zombie_outerarm_screendoor", 3);
            aTrackName = "anim_screendoor";
            break;
        case SHIELDTYPE_TRASHCAN:
            ShowDoorArms(true);
            ReanimShowPrefix("Zombie_outerarm_screendoor", 3);
            aTrackName = "anim_screendoor";
            aBodyReanim->SetImageOverride("anim_screendoor", IMAGE_REANIM_ZOMBIE_TRASHCAN1);
            break;
        case SHIELDTYPE_NEWSPAPER:
            ReanimShowPrefix("Zombie_paper_hands", 3);
            aTrackName = "Zombie_paper_paper";
            break;
        case SHIELDTYPE_LADDER:
            ReanimShowPrefix("Zombie_outerarm", 3);
            aTrackName = "Zombie_ladder_1";
            break;
        default:
            return;
    }
    aBodyReanim->AssignRenderGroupToTrack(aTrackName, 1);
}

