// ==========================================================================
// Zombie::DoDaisies(void)
// @001AAFB8  200 bytes
// ==========================================================================
void Zombie::DoDaisies()
{
    if (IsWalkingBackwards())
        return;

    // 2 is PLANTROW_POOL: no daisies grow on the pool rows. PlantRowType lives
    // only in the TV build's ConstEnums.h, which this tree cannot include.
    if (mBoard->mPlantRow[mRow] == 2)
        return;

    if (mZombieType == ZOMBIE_ZAMBONI
        || mZombieType == ZOMBIE_BOBSLED
        || mZombieType == ZOMBIE_CATAPULT)
        return;

    if (mBoard->StageHasRoof())
        return;

    float aDaisyOffsetX;
    float aDaisyOffsetY;
    if ((unsigned int)(mZombieType - ZOMBIE_FOOTBALL) <= 2)
    {
        aDaisyOffsetX = 180.0f;
        aDaisyOffsetY = 100.0f;
    }
    else if (mZombieType == ZOMBIE_POGO)
    {
        aDaisyOffsetX = 20.0f;
        aDaisyOffsetY = 120.0f;
    }
    else if (mZombieType == ZOMBIE_BALLOON)
    {
        aDaisyOffsetX = 130.0f;
        aDaisyOffsetY = 130.0f;
    }
    else
    {
        aDaisyOffsetX = 20.0f;
        aDaisyOffsetY = 100.0f;
    }

    if (mBoard->StageHasGraveStones() != 0)
        aDaisyOffsetY += 15.0f;

    // 301000 is RENDER_LAYER_GRAVE_STONE, which this tree's RenderLayer does not
    // enumerate; the daisies belong with the gravestones. Likewise 100 is
    // PARTICLE_ZOMBIE_DAISIES, an enumerator this tree's ParticleEffect lacks.
    int aRenderOrder = Board::MakeRenderOrder((RenderLayer)301000, mRow, 5);
    mApp->AddTodParticle(aDaisyOffsetX + (float)mX,
                                aDaisyOffsetY + (float)mY,
                                aRenderOrder,
                                (ParticleEffect)100);
}

// ==========================================================================
// Zombie::HasShadow(void)
// @001AB090  136 bytes
// ==========================================================================
bool Zombie::HasShadow()
{
    // Underground, mid-vault, entering the pool, boarding the bobsled or already
    // dying: no shadow at all.
    if (mZombiePhase == PHASE_ZOMBIE_DYING
        || (unsigned int)(mZombiePhase - PHASE_DIGGER_TUNNELING) <= 3
        || mZombiePhase == PHASE_BOBSLED_BOARDING
        || mZombiePhase == PHASE_DANCER_RISING
        || mZombiePhase == PHASE_POLEVAULTER_IN_VAULT
        || mZombiePhase == PHASE_RISING_FROM_GRAVE
        || mZombiePhase == PHASE_DOLPHIN_INTO_POOL
        || mZombiePhase == PHASE_SNORKEL_INTO_POOL)
        return false;

    if (mZombieType == ZOMBIE_ZAMBONI
        || mZombieType == ZOMBIE_CATAPULT
        || mZombieType == ZOMBIE_BOSS
        || (mZombieType == ZOMBIE_BUNGEE && (!IsOnBoard() || mHitUmbrella)))
        return false;

    if (mZombieHeight == HEIGHT_DRAGGED_UNDER
        || mZombieHeight == HEIGHT_IN_TO_CHIMNEY
        || mZombieHeight == HEIGHT_GETTING_BUNGEE_DROPPED)
        return false;

    if (mInPool)
        return false;

    if (IsOnBoard() && mApp->mGameMode == GAMEMODE_CHALLENGE_ZOMBIQUARIUM)
        return false;

    // The invisible ghoul keeps its shadow only when it has been dropped from a
    // bungee (mFromWave -3); the zombiquarium has none at all.
    if (mApp->mGameMode == GAMEMODE_CHALLENGE_INVISIGHOUL && mFromWave != -3)
        return false;

    return mVisible;
}

// ==========================================================================
// Zombie::SetupDrawZombieWon(Sexy::Graphics *)
// @001AB118  124 bytes
// ==========================================================================
int Zombie::SetupDrawZombieWon(Sexy::Graphics * g)
{
    if (mFromWave != -4)
        return 1;

    // mBackground is a BackgroundType: 0/1 are day and night, 2/3 the pool and
    // the fog, 4/5 the roof and the boss arena. Each pair clips to its own band.
    int aBackground = mBoard->mBackground;
    if (aBackground <= 1)
    {
        g->ClipRect(-123 - mX, -mY, 800, 600);
        return 1;
    }
    if ((unsigned int)(aBackground - 2) <= 1)
    {
        g->ClipRect(-172 - mX, -mY, 800, 600);
        return 1;
    }
    if ((unsigned int)(aBackground - 4) <= 1)
        g->ClipRect(-220 - mX, -60 - mY, 800, 247);
    return 1;
}

// ==========================================================================
// Zombie::GetTrackPosition(char const*,float &,float &)
// @001AB194  106 bytes
// ==========================================================================
Reanimation * Zombie::GetTrackPosition(char const* theTrackName, float & thePosX, float & thePosY)
{
    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim != nullptr)
    {
        int aTrackIndex = aBodyReanim->FindTrackIndex(theTrackName);
        Sexy::SexyTransform2D aTransform;
        aBodyReanim->GetTrackMatrix(aTrackIndex, aTransform);
        thePosX = mPosX + aTransform.m02;
        thePosY = mPosY + aTransform.m12;
    }
    else
    {
        thePosX = mPosX;
        thePosY = mPosY;
    }
    return aBodyReanim;
}

// ==========================================================================
// Zombie::DropFlag(void)
// @001AB200  160 bytes
// ==========================================================================
void Zombie::DropFlag()
{
    if (mZombieType == ZOMBIE_FLAG && mHasObject)
    {
        mApp->RemoveReanimation(mSpecialHeadReanimID);
        ReanimShowPrefix("anim_innerarm", 0);
        ReanimShowTrack("Zombie_flaghand", -1);
        ReanimShowTrack("Zombie_innerarm_screendoor", -1);
        mHasObject = false;

        float aFlagX = 0.0f;
        float aFlagY = 0.0f;
        GetTrackPosition("Zombie_flaghand", aFlagX, aFlagY);
        // 11 is PARTICLE_ZOMBIE_FLAG, an enumerator this tree's ParticleEffect
        // (a one-int struct) does not carry.
        TodParticleSystem *aParticle = (TodParticleSystem *)mApp->AddTodParticle(aFlagX + 6.0f,
                                                                                          aFlagY - 45.0f,
                                                                                          mRenderOrder + 1,
                                                                                          (ParticleEffect)11);
        OverrideParticleColor(aParticle);
        {
            OverrideParticleScale(aParticle);
            return;
        }
    }
    return;
}

// ==========================================================================
// Zombie::DrawButter(Sexy::Graphics *,ZombieDrawPosition &)
// @001AB2B0  436 bytes
// ==========================================================================
int Zombie::DrawButter(Sexy::Graphics * g, ZombieDrawPosition & theDrawPos)
{
    ZombieDrawPosition &aPos = theDrawPos;

    float aPosX = mPosX + aPos.mImageOffsetX + 11.0f + (float)aPos.mHeadX;
    float aPosY = mPosY + aPos.mImageOffsetY + 21.0f + aPos.mBodyY + (float)aPos.mHeadY;

    const char *aTrackName = nullptr;
    if (mZombiePhase == PHASE_NEWSPAPER_MADDENING)
        aTrackName = "anim_head_look";
    else if (mZombieType == ZOMBIE_CATAPULT)
        aTrackName = "Zombie_catapult_driver_head";
    else if (mBodyReanimID != 0)
        aTrackName = "anim_head1";

    if (aTrackName != nullptr)
        GetTrackPosition(aTrackName, aPosX, aPosY);

    aPosX = (aPosX - mPosX) - 29.0f;
    aPosY = (aPosY - mPosY) - 36.0f;

    float aScale = 1.0f;
    if (mZombieType == ZOMBIE_POGO)
    {
        aPosY = aPosY - 5.0f;
    }
    else if (mZombieType == ZOMBIE_GARGANTUAR || mZombieType == ZOMBIE_REDEYE_GARGANTUAR)
    {
        aPosX = aPosX - 5.0f;
        aPosY = aPosY - 15.0f;
        aScale = 1.2f;
    }
    else
    {
        switch (mZombieType)
        {
            case ZOMBIE_BUNGEE:
                aScale = 1.2f;
                break;
            case ZOMBIE_SQUASH_HEAD:
                aPosX = aPosX + 6.0f;
                aPosY = aPosY - 9.0f;
                break;
            case ZOMBIE_WALLNUT_HEAD:
                aPosX = aPosX - 6.0f;
                aPosY = aPosY - 1.0f;
                break;
            case ZOMBIE_TALLNUT_HEAD:
                aPosX = aPosX - 24.0f;
                aPosY = aPosY - 39.0f;
                break;
            default:
                break;
        }
    }

    TodDrawImageScaledF(g, IMAGE_REANIM_CORNPULT_BUTTER_SPLAT, aPosX, aPosY, aScale, aScale);
    return 0;
}

// ==========================================================================
// Zombie::DrawBungeeCord(Sexy::Graphics *,int,int)
// @001AB484  410 bytes
// ==========================================================================
int Zombie::DrawBungeeCord(Sexy::Graphics * g, int theCordEndX, int theCordEndY)
{
    int aCordCelHeight = (int)((float)(IMAGE_BUNGEECORD)->GetCelHeight() * mScaleZombie);

    float aPosX = 0.0f;
    float aPosY = 0.0f;
    GetTrackPosition("Zombie_bungi_body", aPosX, aPosY);

    bool aSetClip = false;
    if (IsOnBoard() && mApp->IsFinalBossLevel())
    {
        Zombie *aBossZombie = mBoard->GetBossZombie();
        int aClipAmount = 55;
        if (aBossZombie->mZombiePhase == PHASE_BOSS_BUNGEES_LEAVE)
        {
            Reanimation *aBossReanim = mApp->ReanimationGet(aBossZombie->mBodyReanimID);
            aClipAmount = (int)TodAnimateCurveFloatTime(0.0f, 0.2f, aBossReanim->mAnimTime, 55.0f, 0.0f, CURVE_LINEAR);
        }

        if (mTargetCol > aBossZombie->mTargetCol)
        {
            g->SetClipRect(Sexy::Rect(-(int)g->mTransX, aClipAmount - (int)g->mTransY, 800, 600));
            aSetClip = true;
        }
    }

    for (float aY = aPosY - (float)aCordCelHeight;
         aY > (float)(LawnApp::FULLSCREEN_RECT.mY - aCordCelHeight);
         aY -= (float)aCordCelHeight)
    {
        TodDrawImageScaledF(g,
                            IMAGE_BUNGEECORD,
                            theCordEndX + 61.0f - 4.0f / mScaleZombie,
                            aY - mPosY,
                            mScaleZombie,
                            mScaleZombie);
    }

    if (aSetClip)
        g->ClearClipRect();
  return 0;
    return 0;
}

// ==========================================================================
// Zombie::IsFlying(void)
// @001AB634  14 bytes
// ==========================================================================
bool Zombie::IsFlying()
{
    return (unsigned int)(mZombiePhase - PHASE_BALLOON_FLYING) <= 1;
}

// ==========================================================================
// Zombie::DrawShadow(Sexy::Graphics *)
// @001AB644  916 bytes
// ==========================================================================
int Zombie::DrawShadow(Sexy::Graphics * g)
{
    // The shadow uses the same body and image offsets as the zombie.
    ZombieDrawPosition aDrawPos;
    GetDrawPos(aDrawPos);

    if (mApp->mGameScene == SCENE_ZOMBIES_WON && SetupDrawZombieWon(g) == 0)
        return 0;

    float aScale = mScaleZombie;
    float aShadowY = aDrawPos.mBodyY + aDrawPos.mImageOffsetY;
    float aShadowX = (mScaleZombie * 20.0f - 20.0f) + aDrawPos.mImageOffsetX;
    float aOffsetX = aShadowX;

    bool aNightShadow = IsOnBoard() && mBoard->StageIsNight() != 0;

    if (mZombieType == ZOMBIE_FOOTBALL)
    {
        if (IsWalkingBackwards())
            aOffsetX = aShadowX + (mScaleZombie * -11.0f);
        else
            aOffsetX = ((mScaleZombie * 21.0f) + 20.0f) + aShadowX;
        aShadowY += 16.0f;
    }
    else
    {
        switch (mZombieType)
        {
            case ZOMBIE_NEWSPAPER:
                if (IsWalkingBackwards())
                    aOffsetX = aShadowX + 5.0f;
                else
                    aOffsetX = aShadowX + 29.0f;
                break;

            case ZOMBIE_POLEVAULTER:
                if (IsWalkingBackwards())
                    aOffsetX = aShadowX - 5.0f;
                else
                    aOffsetX = aShadowX + 36.0f;
                aShadowY += 11.0f;
                break;

            case ZOMBIE_BOBSLED:
                if (IsWalkingBackwards())
                    aOffsetX = aShadowX + 13.0f;
                else
                    aOffsetX = aShadowX + 20.0f;
                aShadowY += 13.0f;
                break;

            default:
                switch (mZombieType)
                {
                    case ZOMBIE_IMP:
                        aShadowY += 7.0f;
                        aScale = mScaleZombie * 0.6f;
                        if (IsWalkingBackwards())
                            aOffsetX = aShadowX + 13.0f;
                        else
                            aOffsetX = aShadowX + 25.0f;
                        break;

                    case ZOMBIE_DIGGER:
                        aShadowY += 5.0f;
                        if (IsWalkingBackwards())
                            aOffsetX = aShadowX + 14.0f;
                        else
                            aOffsetX = aShadowX + 17.0f;
                        break;

                    case ZOMBIE_SNORKEL:
                        aShadowY += 5.0f;
                        if (IsWalkingBackwards())
                            aOffsetX = aShadowX - 2.0f;
                        else
                            aOffsetX = aShadowX + 35.0f;
                        break;

                    case ZOMBIE_DOLPHIN_RIDER:
                        aShadowY += 11.0f;
                        if (IsWalkingBackwards())
                            aOffsetX = aShadowX + 15.0f;
                        else
                            aOffsetX = aShadowX + 19.0f;
                        break;

                    case ZOMBIE_YETI:
                        aShadowY += 20.0f;
                        if (IsWalkingBackwards())
                            aOffsetX = aShadowX + 20.0f;
                        else
                            aOffsetX = aShadowX + 3.0f;
                        break;

                    default:
                        if (mZombieType == ZOMBIE_GARGANTUAR || mZombieType == ZOMBIE_REDEYE_GARGANTUAR)
                        {
                            aScale = mScaleZombie * 1.5f;
                            aOffsetX = aShadowX + 27.0f;
                            aShadowY += 7.0f;
                        }
                        else if (mApp->ReanimationTryToGet(mBodyReanimID) != nullptr)
                        {
                            if (IsWalkingBackwards())
                                aOffsetX = aShadowX + 11.0f;
                            else
                                aOffsetX = aShadowX + 23.0f;
                        }
                        else
                        {
                            if (IsWalkingBackwards())
                                aOffsetX = aShadowX - 2.0f;
                            else
                                aOffsetX = aShadowX + 35.0f;
                        }
                        break;
                }
                break;
        }
    }

    if (mZombieType == ZOMBIE_NEWSPAPER)
    {
        aShadowY += 4.0f;
    }
    else if (mZombieType == ZOMBIE_BALLOON)
    {
        aShadowY += 13.0f;
    }
    else if (mZombieType == ZOMBIE_BUNGEE)
    {
        aOffsetX -= 12.0f;
        aScale = TodAnimateCurveFloat(2000, 100, (int)mAltitude, 0.1f, 1.5f, CURVE_LINEAR);
    }

    if (mZombieHeight == HEIGHT_UP_LADDER || mZombieHeight == HEIGHT_FALLING
        || mZombiePhase == PHASE_IMP_GETTING_THROWN
        || mZombieType == ZOMBIE_BUNGEE
        || IsBouncingPogo() || IsFlying())
    {
        aShadowY += mAltitude;
        if (mOnHighGround)
            aShadowY -= 30.0f;
    }

    if (mInPool)
    {
        TodDrawImageCenterScaledF(g,
                                  IMAGE_WHITEWATER_SHADOW,
                                  aOffsetX,
                                  aShadowY + 67.0f,
                                  aScale,
                                  aScale);
    }
    else if (aNightShadow)
    {
        TodDrawImageCelCenterScaledF(g,
                                     IMAGE_ZOMBIESHADOW2,
                                     aOffsetX,
                                     aShadowY + 92.0f,
                                     mInPool,
                                     aScale,
                                     aScale);
    }
    else
    {
        TodDrawImageCelCenterScaledF(g,
                                     IMAGE_ZOMBIESHADOW,
                                     aOffsetX,
                                     aShadowY + 92.0f,
                                     0,
                                     aScale,
                                     aScale);
    }
    g->ClearClipRect();
  return 0;
}

// ==========================================================================
// Zombie::GetBobsledPosition(void)
// @001AB9FC  98 bytes
// ==========================================================================
int Zombie::GetBobsledPosition()
{
    if (mZombieType != ZOMBIE_BOBSLED)
        return -1;

    if (mRelatedZombieID != 0)
    {
        int aID = mBoard->ZombieGetID(this);
        Zombie *aLeaderZombie = mBoard->ZombieGet(mRelatedZombieID);
        if (aID == aLeaderZombie->mFollowerZombieID[0])
            return 1;
        if (aID == aLeaderZombie->mFollowerZombieID[1])
            return 2;
        if (aID == aLeaderZombie->mFollowerZombieID[2])
            return 3;

        // The ARM leaves the leader's address in r0 on the way out of the chain;
        // the original tail is void and no caller reads this value.
        return -1;
    }
    else if (mFollowerZombieID[0] != 0)
    {
        return 0;
    }
    else
    {
        return -1;
    }
}

// ==========================================================================
// Zombie::DrawBobsledReanim(Sexy::Graphics *,ZombieDrawPosition &,bool)
// @001ABA60  874 bytes
// ==========================================================================
int Zombie::DrawBobsledReanim(Sexy::Graphics * g, ZombieDrawPosition & theDrawPos, bool theClip)
{
    ZombieDrawPosition &aPos = theDrawPos;

    int aBobsledPosition = GetBobsledPosition();
    Zombie *aLeaderZombie = this;
    bool aDrawInside = false;
    bool aDrawSled = false;
    bool aCrashed = false;
    float aDrawY = 0.0f;
    Sexy::Image *aImage = nullptr;

    if (mFromWave == -2)
    {
        aDrawSled = theClip;
        aDrawInside = !theClip;
        aCrashed = (mZombiePhase == PHASE_BOBSLED_CRASHING);
    }
    else
    {
        if (aBobsledPosition == -1)
            return -1;

        if (aBobsledPosition != 0)
            aLeaderZombie = mBoard->ZombieGet(mRelatedZombieID);

        if (mZombiePhase == PHASE_BOBSLED_CRASHING)
        {
            aDrawInside = (aBobsledPosition == 0) ? !theClip : false;
            aCrashed = true;
        }
        else if (mZombiePhase == PHASE_BOBSLED_SLIDING || mZombiePhase == PHASE_ZOMBIE_BURNED)
        {
            aDrawInside = (aBobsledPosition == 2) ? theClip : false;
            aDrawSled = aDrawInside;
        }
        else if (mZombiePhase == PHASE_BOBSLED_BOARDING)
        {
            Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
            if (aBodyReanim->mAnimTime >= 0.5f)
            {
                if ((aBobsledPosition == 0) ? !theClip : false)
                {
                    aDrawSled = false;
                    aDrawInside = true;
                }
                else
                {
                    aDrawSled = (aBobsledPosition == 3) ? theClip : false;
                    aDrawInside = false;
                }
            }
            else
            {
                aDrawSled = true;
                aDrawInside = true;
                if (!((aBobsledPosition == 2) ? theClip : false))
                {
                    aDrawSled = false;
                    aDrawInside = false;
                }
            }
        }
    }

    float aDrawX = (aPos.mImageOffsetX + aLeaderZombie->mPosX - 76.0f) - mPosX;

    if (aCrashed)
    {
        int aAlpha = TodAnimateCurve(30, 0, mPhaseCounter, 255, 0, CURVE_LINEAR);
        int aPhaseCounter = mPhaseCounter;
        float aCrashX = aDrawX + (mVelX * 0.5f) * (float)(150 - aPhaseCounter);
        aDrawX = aCrashX - TodAnimateCurveFloat(150, 0, aPhaseCounter, 0.0f, 50.0f, CURVE_EASE_OUT);
        aDrawY = TodAnimateCurveFloat(150, 75, mPhaseCounter, 5.0f, 10.0f, CURVE_LINEAR) + 15.0f;
        if (aAlpha != 255)
        {
            g->SetColorizeImages(true);
            Sexy::Color aColor(255, 255, 255, aAlpha);
            g->SetColor(aColor);
        }
        aDrawSled = false;
        aImage = IMAGE_ZOMBIE_BOBSLED4;
    }
    else
    {
        switch (aLeaderZombie->GetHelmDamageIndex())
        {
            case 0:
                aDrawY = 15.0f;
                aImage = IMAGE_ZOMBIE_BOBSLED1;
                break;
            case 1:
                aDrawY = 15.0f;
                aImage = IMAGE_ZOMBIE_BOBSLED2;
                break;
            case 2:
                aDrawY = 15.0f;
                aImage = IMAGE_ZOMBIE_BOBSLED3;
                break;
            case 3:
                aDrawSled = false;
                // falls through to the undamaged sled
            default:
                aDrawY = 15.0f;
                aImage = IMAGE_ZOMBIE_BOBSLED4;
                break;
        }

        if (mZombiePhase == PHASE_ZOMBIE_BURNED)
        {
            g->SetColorizeImages(true);
            g->SetColor(Sexy::Color::Black);
        }
    }

    if (aDrawSled)
    {
        g->DrawImageF(IMAGE_ZOMBIE_BOBSLED_INSIDE, aDrawX, aDrawY);
        if (aDrawInside)
            g->DrawImageF(aImage, aDrawX, aDrawY);
    }
    else if (aDrawInside)
    {
        g->DrawImageF(aImage, aDrawX, aDrawY);
    }

    if (aLeaderZombie->mJustGotShotCounter > 0)
    {
        int aFlash = 10 * aLeaderZombie->mJustGotShotCounter;
        g->SetDrawMode(1);
        g->SetColorizeImages(true);
        Sexy::Color aColor(aFlash, aFlash, aFlash, 255);
        g->SetColor(aColor);

        if (aDrawSled)
        {
            g->DrawImageF(IMAGE_ZOMBIE_BOBSLED_INSIDE, aDrawX, aDrawY);
            if (aDrawInside)
                g->DrawImageF(aImage, aDrawX, aDrawY);
        }
        else if (aDrawInside)
        {
            g->DrawImageF(aImage, aDrawX, aDrawY);
        }

        g->SetDrawMode(0);
        g->SetColorizeImages(false);
  return 0;
    }
    g->SetColorizeImages(false);
  return 0;
}

// ==========================================================================
// Zombie::IsBobsledTeamWithSled(void)
// @001ABDEC  14 bytes
// ==========================================================================
bool Zombie::IsBobsledTeamWithSled()
{
  return GetBobsledPosition() != -1;
}

// ==========================================================================
// Zombie::CanLoseBodyParts(void)
// @001ABDFC  60 bytes
// ==========================================================================
bool Zombie::CanLoseBodyParts()
{
    // The types with no arm to lose: the zamboni, the bungee, the catapult, both
    // gargantuaurs and the boss. A zombiquarium zombie keeps its arm as well.
    return mZombieType != ZOMBIE_ZAMBONI
        && mZombieType != ZOMBIE_BUNGEE
        && mZombieType != ZOMBIE_CATAPULT
        && mZombieType != ZOMBIE_GARGANTUAR
        && mZombieType != ZOMBIE_BOSS
        && mZombieType != ZOMBIE_REDEYE_GARGANTUAR
        && mZombieHeight != HEIGHT_ZOMBIQUARIUM
        && !IsFlying()
        && !IsBobsledTeamWithSled();
}

// ==========================================================================
// Zombie::DropArm(unsigned int)
// @001ABE38  1476 bytes
// ==========================================================================
void Zombie::DropArm(unsigned int theDamageFlags)
{
    if (!CanLoseBodyParts())
        return;

    // A door, a newspaper or a trash can is held in front of the arm.
    if (mShieldType == SHIELDTYPE_DOOR
        || mShieldType == SHIELDTYPE_NEWSPAPER
        || mShieldType == SHIELDTYPE_TRASHCAN)
        return;

    // The dolphin and snorkel phases and the newspaper-reading phase need both
    // arms, and so does a zombie that has already lost the one.
    if (mZombiePhase == PHASE_NEWSPAPER_READING
        || mZombiePhase == PHASE_DOLPHIN_WALKING
        || mZombiePhase == PHASE_DOLPHIN_INTO_POOL
        || mZombiePhase == PHASE_DOLPHIN_RIDING
        || mZombiePhase == PHASE_DOLPHIN_IN_JUMP
        || mZombiePhase == PHASE_SNORKEL_INTO_POOL
        || !mHasArm)
        return;

    mHasArm = false;
    switch (mZombieType)
    {
        case ZOMBIE_FLAG:
            ReanimShowPrefix("Zombie_outerarm_lower", -1);
            ReanimShowPrefix("Zombie_outerarm_hand", -1);
            break;
        case ZOMBIE_POLEVAULTER:
            ReanimShowTrack("Zombie_polevaulter_outerarm_lower", -1);
            ReanimShowTrack("Zombie_outerarm_hand", -1);
            break;
        case ZOMBIE_NEWSPAPER:
            ReanimShowTrack("Zombie_paper_hands", -1);
            ReanimShowTrack("Zombie_paper_leftarm_lower", -1);
            break;
        case ZOMBIE_FOOTBALL:
            ReanimShowPrefix("Zombie_football_leftarm_lower", -1);
            ReanimShowPrefix("Zombie_football_leftarm_hand", -1);
            break;
        case ZOMBIE_DANCER:
            ReanimShowTrack("Zombie_disco_outerarm_lower", -1);
            ReanimShowTrack("Zombie_disco_outerhand_point", -1);
            ReanimShowTrack("Zombie_disco_outerhand", -1);
            break;
        case ZOMBIE_BACKUP_DANCER:
            ReanimShowTrack("Zombie_disco_outerarm_lower", -1);
            ReanimShowTrack("Zombie_disco_outerhand", -1);
            break;
        default:
            ReanimShowPrefix("Zombie_outerarm_lower", -1);
            ReanimShowPrefix("Zombie_outerarm_hand", -1);
            break;
    }

    // The stump that replaces the arm is put where the hand was.
    ZombieDrawPosition aPos;
    GetDrawPos(aPos);

    float aStumpX = (mPosX + aPos.mImageOffsetX) + 45.0f;
    float aStumpY = ((mPosY + aPos.mImageOffsetY) + 78.0f) + aPos.mBodyY;
    if (IsWalkingBackwards())
        aStumpX += 36.0f;

    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim != nullptr)
    {
        switch (mZombieType)
        {
            case ZOMBIE_FLAG:
            {
                GetTrackPosition("zombie_outerarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_OUTERARM_UPPER2);
                // The flag holder carries a second reanimation on top of the arm.
                Reanimation *aFlagReanim = mApp->ReanimationTryToGet(mSpecialHeadReanimID);
                if (aFlagReanim != nullptr)
                    aFlagReanim->SetImageOverride("Zombie_flag", IMAGE_REANIM_ZOMBIE_FLAG3);
                break;
            }
            case ZOMBIE_POLEVAULTER:
                GetTrackPosition("Zombie_polevaulter_outerarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_polevaulter_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_POLEVAULTER_OUTERARM_UPPER2);
                break;
            case ZOMBIE_NEWSPAPER:
                GetTrackPosition("Zombie_paper_leftarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_paper_leftarm_upper",
                                              IMAGE_REANIM_ZOMBIE_PAPER_LEFTARM_UPPER2);
                break;
            case ZOMBIE_FOOTBALL:
                GetTrackPosition("zombie_football_leftarm_hand", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("zombie_football_leftarm_upper",
                                              IMAGE_REANIM_ZOMBIE_FOOTBALL_LEFTARM_UPPER2);
                break;
            case ZOMBIE_DANCER:
                GetTrackPosition("Zombie_disco_outerarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_disco_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_DISCO_OUTERARM_UPPER2);
                break;
            case ZOMBIE_BACKUP_DANCER:
                GetTrackPosition("Zombie_disco_outerarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_disco_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_BACKUP_OUTERARM_UPPER2);
                break;
            case ZOMBIE_SNORKEL:
                GetTrackPosition("Zombie_outerarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_snorkle_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_SNORKLE_OUTERARM_UPPER2);
                break;
            case ZOMBIE_BOBSLED:
                GetTrackPosition("zombie_outerarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_dolphinrider_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_BOBSLED_OUTERARM_UPPER2);
                break;
            case ZOMBIE_DOLPHIN_RIDER:
                GetTrackPosition("zombie_outerarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_dolphinrider_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_DOLPHINRIDER_OUTERARM_UPPER2);
                break;
            case ZOMBIE_JACK_IN_THE_BOX:
                GetTrackPosition("Zombie_jackbox_outerarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_jackbox_outerarm_lower",
                                              IMAGE_REANIM_ZOMBIE_JACKBOX_OUTERARM_LOWER2);
                break;
            case ZOMBIE_BALLOON:
                GetTrackPosition("zombie_outerarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_BALLOON_OUTERARM_UPPER2);
                break;
            case ZOMBIE_DIGGER:
                GetTrackPosition("zombie_outerarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_digger_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_DIGGER_OUTERARM_UPPER2);
                break;
            case ZOMBIE_POGO:
                GetTrackPosition("zombie_outerarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_POGO_OUTERARM_UPPER2);
                aBodyReanim->SetImageOverride("Zombie_pogo_stickhands",
                                              IMAGE_REANIM_ZOMBIE_POGO_STICKHANDS2);
                aBodyReanim->SetImageOverride("Zombie_pogo_stick",
                                              IMAGE_REANIM_ZOMBIE_POGO_STICKDAMAGE2);
                aBodyReanim->SetImageOverride("Zombie_pogo_stick2",
                                              IMAGE_REANIM_ZOMBIE_POGO_STICK2DAMAGE2);
                break;
            case ZOMBIE_YETI:
                GetTrackPosition("Zombie_outerarm_hand", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_yeti_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_YETI_OUTERARM_UPPER2);
                break;
            case ZOMBIE_LADDER:
                GetTrackPosition("Zombie_outerarm_hand", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_ladder_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_LADDER_OUTERARM_UPPER2);
                break;
            case ZOMBIE_IMP:
                GetTrackPosition("zombie_outerarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_imp_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_IMP_ARM1_BONE);
                break;
            default:
                GetTrackPosition("zombie_outerarm_lower", aStumpX, aStumpY);
                aBodyReanim->SetImageOverride("Zombie_outerarm_upper",
                                              IMAGE_REANIM_ZOMBIE_OUTERARM_UPPER2);
                break;
        }
    }

    if (!mInPool && (theDamageFlags & 0x10) == 0)
    {
        // A zombie that is being mowed down throws the vault dust (74), every
        // other one the plain puff (7); 99 is PARTICLE_... the arm debris.
        TodParticleSystem *aParticles = (TodParticleSystem *)mApp->AddTodParticle(
            aStumpX,
            aStumpY,
            mRenderOrder + 1,
            mZombiePhase == PHASE_ZOMBIE_MOWERED ? (ParticleEffect)74 : (ParticleEffect)7);
        OverrideParticleColor(aParticles);
        OverrideParticleScale(aParticles);

        if (aParticles != nullptr)
        {
            // Each of these types overrides the debris with its own hand image.
            // Those IMAGE_* symbols are not declared in this tree, so the call
            // still passes a null image.
            switch (mZombieType)
            {
                case ZOMBIE_POLEVAULTER:
                case ZOMBIE_NEWSPAPER:
                case ZOMBIE_FOOTBALL:
                case ZOMBIE_DANCER:
                case ZOMBIE_BACKUP_DANCER:
                case ZOMBIE_BOBSLED:
                case ZOMBIE_DOLPHIN_RIDER:
                case ZOMBIE_JACK_IN_THE_BOX:
                case ZOMBIE_BALLOON:
                case ZOMBIE_POGO:
                case ZOMBIE_YETI:
                case ZOMBIE_DIGGER:
                case ZOMBIE_LADDER:
                case ZOMBIE_IMP:
                    aParticles->OverrideImage(nullptr, 0);
                    break;
                default:
                    break;
            }
        }
    }

    mApp->PlayFoley(FOLEY_LIMBS_POP);
}

// ==========================================================================
// Zombie::UpdateZombieWalking(void)
// @001AC4B4  666 bytes
// ==========================================================================
void Zombie::UpdateZombieWalking()
{
    if (ZombieNotWalking())
        return;

    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim != nullptr)
    {
        // A floating zombie -- the balloon, the riding dolphin, the snorkel
        // swimming, the pogo mid-bounce -- keeps its own speed, chilled. The
        // bobsled, the zamboni, the vaulting polevaulter and the digging
        // zombie slide at mVelX unchilled; everything else takes the walk
        // track's own velocity.
        float aWalkSpeed;
        bool aChilled = false;
        if (IsBouncingPogo()
            || mZombiePhase == PHASE_BALLOON_FLYING
            || mZombiePhase == PHASE_DOLPHIN_RIDING
            || mZombiePhase == PHASE_SNORKEL_WALKING_IN_POOL
            || mZombieType == ZOMBIE_CATAPULT)
        {
            aWalkSpeed = mVelX;
            aChilled = true;
        }
        else if (mZombieType == ZOMBIE_ZAMBONI
                 || mZombiePhase == PHASE_DIGGER_TUNNELING
                 || mZombiePhase == PHASE_DOLPHIN_IN_JUMP
                 || IsBobsledTeamWithSled()
                 || mZombiePhase == PHASE_POLEVAULTER_IN_VAULT
                 || mZombiePhase == PHASE_SNORKEL_INTO_POOL)
        {
            aWalkSpeed = mVelX;
        }
        else if (aBodyReanim->FindTrackIndexById(ReanimTrackId__ground) < 0)
        {
            aWalkSpeed = mVelX;
            aChilled = true;
        }
        else
        {
            aWalkSpeed = aBodyReanim->GetTrackVelocity("_ground") * mScaleZombie;
        }

        if (aChilled && IsMovingAtChilledSpeed())
            aWalkSpeed *= 0.4f;

        // A trash can zombie in a versus game crawls.
        if (mApp->mGameMode == GAMEMODE_MP_VS && mZombieType == ZOMBIE_TRASHCAN)
            aWalkSpeed *= 0.2f;

        float aPosX = mPosX;
        if (IsWalkingBackwards() || mZombiePhase == PHASE_DANCER_DANCING_IN)
            mPosX = aPosX + aWalkSpeed;
        else
            mPosX = aPosX - aWalkSpeed;

        // The football zombie kicks up dirt off its feet as it walks; -4 is the
        // "not on a wave" sentinel mFromWave carries for a summoned zombie.
        if (mZombieType == ZOMBIE_FOOTBALL && mFromWave != -4)
        {
            if (aBodyReanim->ShouldTriggerTimedEvent(0.03f))
                mApp->AddTodParticle((float)(mX + 81), (float)(mY + 106), mRenderOrder - 1, PARTICLE_FOOTBALL_RUNNING);

            if (aBodyReanim->ShouldTriggerTimedEvent(0.61f))
                mApp->AddTodParticle((float)(mX + 87), (float)(mY + 110), mRenderOrder - 1, PARTICLE_FOOTBALL_RUNNING);
        }

        if (mZombiePhase == PHASE_POLEVAULTER_PRE_VAULT)
        {
            if (aBodyReanim->ShouldTriggerTimedEvent(0.16f))
                mApp->AddTodParticle((float)(mX + 81), (float)(mY + 106), mRenderOrder - 1, PARTICLE_FOOTBALL_RUNNING);

            if (aBodyReanim->ShouldTriggerTimedEvent(0.67f))
                mApp->AddTodParticle((float)(mX + 87), (float)(mY + 110), mRenderOrder - 1, PARTICLE_FOOTBALL_RUNNING);
        }

        return;
    }

    // No body animation at all: only the types that slide along on their own --
    // and only on a frame with the legs down -- still move.
    if (mZombiePhase != PHASE_POLEVAULTER_IN_VAULT
        && mZombiePhase != PHASE_DIGGER_TUNNELING
        && mZombieType != ZOMBIE_DANCER
        && mZombieType != ZOMBIE_BACKUP_DANCER
        && mZombieType != ZOMBIE_BOBSLED
        && mZombieType != ZOMBIE_DOLPHIN_RIDER
        && mZombieType != ZOMBIE_BALLOON
        && mZombieType != ZOMBIE_POGO
        && !(mZombieType == ZOMBIE_SNORKEL && mInPool)
        && (unsigned int)mFrame > 2
        && (unsigned int)(mFrame - 6) > 2)
    {
        return;
    }

    float aWalkSpeed = mVelX;
    if (IsMovingAtChilledSpeed())
        aWalkSpeed *= 0.4f;

    float aPosX = mPosX;
    if (IsWalkingBackwards())
        mPosX = aPosX + aWalkSpeed;
    else
        mPosX = aPosX - aWalkSpeed;

    return;
}

// ==========================================================================
// Zombie::UpdateZombieWalkingIntoHouse(void)
// @001AC760  272 bytes
// ==========================================================================
void Zombie::UpdateZombieWalkingIntoHouse()
{
    // The bungee and the boss leave by their own route, a zombie rising out of
    // a grave is not walking yet, and a zombiquarium one has no house to reach.
    if (mZombieType == ZOMBIE_BUNGEE
        || mZombieType == ZOMBIE_BOSS
        || mZombiePhase == PHASE_RISING_FROM_GRAVE
        || mZombieHeight == HEIGHT_ZOMBIQUARIUM)
    {
        return;
    }

    UpdateZombieWalking();
    if (mZombieHeight != HEIGHT_ZOMBIE_NORMAL)
        return;

    // Where mPosY eases to, and how far it may close in one frame. A football
    // zombie on row 0 or 1 uses a step of 2; every other case uses 1.
    float aTargetX;
    float aStep;
    if (mZombieType == ZOMBIE_GARGANTUAR || mZombieType == ZOMBIE_REDEYE_GARGANTUAR)
    {
        aTargetX = 320.0f;
        aStep = 1.0f;
    }
    else if (mZombiePhase == PHASE_POLEVAULTER_PRE_VAULT)
    {
        aTargetX = 325.0f;
        aStep = 1.0f;
    }
    else if (mZombieType == ZOMBIE_ZAMBONI)
    {
        aTargetX = 305.0f;
        aStep = 1.0f;
    }
    else if (mZombieType != ZOMBIE_FOOTBALL)
    {
        aTargetX = 290.0f;
        aStep = 1.0f;
    }
    else if (mRow > 1)
    {
        aTargetX = 305.0f;
        aStep = 1.0f;
    }
    else
    {
        aTargetX = 305.0f;
        aStep = 2.0f;
    }

    // The word this eases is mPosY (+0x40, VLDR S15,[R4,#0x40]); the settled
    // case is the only one that touches mPosX, and then by half a pixel a frame
    // until the zombie is just off the left edge of the lawn.
    float aPosY = mPosY;
    if (aTargetX <= aPosY)
    {
        if (aTargetX >= aPosY)
        {
            if (mPosX > -160.0f)
                mPosX -= 0.5f;
        }
        else
        {
            float aStepIn = aPosY - aTargetX;
            if (aStepIn > 1.0f)
                aStepIn = 1.0f;

            float aNearY = aPosY - aStepIn;
            float aExtra = aNearY - aTargetX;
            if (aExtra > aStep)
                aExtra = aStep;

            mPosY = aNearY - aExtra;
        }
    }
    else
    {
        float aStepIn = aTargetX - aPosY;
        if (aStepIn > 1.0f)
            aStepIn = 1.0f;

        float aNearY = aStepIn + aPosY;
        float aExtra = aTargetX - aNearY;
        if (aExtra > aStep)
            aExtra = aStep;

        mPosY = aExtra + aNearY;
    }

    return;
}

// ==========================================================================
// Zombie::DrawReanim(Sexy::Graphics *,ZombieDrawPosition &,int)
// @001AC884  1314 bytes
// ==========================================================================
int Zombie::DrawReanim(Sexy::Graphics * aGraphics, ZombieDrawPosition & aDrawPos, int aBaseRenderGroup)
{
    ZombieDrawPosition &aPos = aDrawPos;

    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr)
        return 0;

    // A zombie the reanimation clips (the boss, the gargantuars) gets a clip
    // rectangle that starts at its own left edge and runs 191 pixels down.
    if (aPos.mClipHeight > -100.0f)
    {
        aGraphics->SetClipRect((int)(aPos.mImageOffsetX - 200.0f),
                               (int)((aPos.mImageOffsetY + aPos.mBodyY) - 78.0f),
                               520,
                               (int)(191.0f - aPos.mClipHeight));
    }

    // mZombieFade is a counter that runs down from 10; anything below zero
    // means "not fading at all" and leaves the zombie opaque.
    int aFadeAlpha = 255;
    if (mZombieFade >= 0)
    {
        aFadeAlpha = 255 * mZombieFade / 10;
        if (aFadeAlpha > 0)
        {
            if (aFadeAlpha >= 255)
                aFadeAlpha = 255;
        }
        else
        {
            aFadeAlpha = 0;
        }
    }

    Sexy::Color aColorOverride(255, 255, 255, aFadeAlpha);
    Sexy::Color aExtraAdditiveColor = Sexy::Color::Black;
    bool aEnableExtraAdditiveDraw = false;
    bool aColorChanged = false;

    if (mZombiePhase == PHASE_ZOMBIE_BURNED)
    {
        aColorOverride = Sexy::Color(0, 0, 0, aFadeAlpha);
        aExtraAdditiveColor = Sexy::Color::Black;
        aEnableExtraAdditiveDraw = false;
    }
    else if (mZombieType != ZOMBIE_BOSS
             || mZombiePhase == PHASE_ZOMBIE_DYING
             || mBodyHealth >= mBodyMaxHealth / 10)
    {
        if (mMindControlled)
        {
            // The mind-controlled tint is the three globals the static
            // constructor fills in, plus the fade alpha.
            aColorOverride = Sexy::Color(gZombieTintRed, gZombieTintGreen, gZombieTintBlue, aFadeAlpha);
            aExtraAdditiveColor = aColorOverride;
            aEnableExtraAdditiveDraw = true;
        }
        else if (mChilledCounter > 0 || mIceTrapCounter > 0)
        {
            aColorOverride = Sexy::Color(75, 75, 255, aFadeAlpha);
            aExtraAdditiveColor = aColorOverride;
            aEnableExtraAdditiveDraw = true;
        }
        else if (mZombieHeight == HEIGHT_ZOMBIQUARIUM && mBodyHealth < 100)
        {
            aColorOverride = Sexy::Color(100, 150, 25, aFadeAlpha);
            aExtraAdditiveColor = aColorOverride;
            aEnableExtraAdditiveDraw = true;
        }
        else
        {
            aEnableExtraAdditiveDraw = mMindControlled;
        }
    }
    else
    {
        // A boss below a tenth of its health flickers, and flickers blue-white
        // while it is also chilled or frozen.
        int aGrayness = TodAnimateCurve(0, 39, mBoard->mMainCounter % 40, 155, 255, CURVE_BOUNCE);
        if (mChilledCounter <= 0 && mIceTrapCounter <= 0)
        {
            aColorOverride = Sexy::Color(aGrayness, aGrayness, aGrayness, aFadeAlpha);
        }
        else
        {
            int aCold = TodAnimateCurve(0, 39, mBoard->mMainCounter % 40, 65, 75, CURVE_BOUNCE);
            aColorOverride = Sexy::Color(aCold, aCold, aGrayness, aFadeAlpha);
        }

        aExtraAdditiveColor = Sexy::Color::Black;
        aEnableExtraAdditiveDraw = false;
    }

    // A zombie that has just been shot flashes. ColorAdd writes its sum into
    // the destination it is handed first and clamps every channel at 255.
    if (mJustGotShotCounter > 0 && !IsBobsledTeamWithSled())
    {
        aEnableExtraAdditiveDraw = true;
        Sexy::Color aFlash(10 * mJustGotShotCounter, 10 * mJustGotShotCounter, 10 * mJustGotShotCounter, 255);
        Sexy::Color aSum;
        ColorAdd(&aSum, &aFlash, &aExtraAdditiveColor);
        aExtraAdditiveColor = aSum;
    }

    if (aColorOverride != aBodyReanim->mColorOverride
        || aExtraAdditiveColor != aBodyReanim->mExtraAdditiveColor
        || aEnableExtraAdditiveDraw != aBodyReanim->mEnableExtraAdditiveDraw)
    {
        aColorChanged = true;
        aBodyReanim->mColorOverride = aColorOverride;
        aBodyReanim->mExtraAdditiveColor = aExtraAdditiveColor;
        aBodyReanim->mEnableExtraAdditiveDraw = aEnableExtraAdditiveDraw;
    }
    else
    {
        aColorChanged = false;
    }

    // The body is drawn in the render group the caller asked for; the bobsled
    // sandwich is drawn around it and the dancer and the bungee have their own
    // whole-zombie routines.
    switch (mZombieType)
    {
        case ZOMBIE_BOBSLED:
            DrawBobsledReanim(aGraphics, aDrawPos, true);
            aBodyReanim->DrawRenderGroup(aGraphics, aBaseRenderGroup);
            DrawBobsledReanim(aGraphics, aDrawPos, false);
            break;
        case ZOMBIE_BUNGEE:
            DrawBungeeReanim(aGraphics, aDrawPos);
            break;
        case ZOMBIE_DANCER:
            DrawDancerReanim(aGraphics, aDrawPos);
            break;
        default:
            aBodyReanim->DrawRenderGroup(aGraphics, aBaseRenderGroup);
            break;
    }

    // The shield is its own render group, drawn between the body and the group
    // that goes in front of a held shield. A burned shield is black, a shield
    // that was just hit flashes, and every other shield is drawn white. The
    // body's colour is put back only for that front group.
    if (mShieldType != SHIELDTYPE_NONE)
    {
        if (mZombiePhase == PHASE_ZOMBIE_BURNED)
        {
            aColorChanged = true;
            aBodyReanim->mColorOverride = Sexy::Color(0, 0, 0, aFadeAlpha);
            aBodyReanim->mExtraAdditiveColor = Sexy::Color::Black;
            aBodyReanim->mEnableExtraAdditiveDraw = false;
        }
        else if (mShieldJustGotShotCounter > 0)
        {
            int aGrayness = 10 * mShieldJustGotShotCounter;
            aBodyReanim->mColorOverride = Sexy::Color(255, 255, 255, aFadeAlpha);
            aBodyReanim->mExtraAdditiveColor = Sexy::Color(aGrayness, aGrayness, aGrayness, 255);
            aBodyReanim->mEnableExtraAdditiveDraw = true;
            aColorChanged = true;
        }
        else
        {
            if (!aColorChanged)
                aColorChanged = aBodyReanim->mEnableExtraAdditiveDraw
                             || aBodyReanim->mColorOverride.mRed != 255;

            aBodyReanim->mColorOverride = Sexy::Color(255, 255, 255, aFadeAlpha);
            aBodyReanim->mExtraAdditiveColor = Sexy::Color::Black;
            aBodyReanim->mEnableExtraAdditiveDraw = false;
        }

        // A shield that has just been hit recoils to the right.
        float aShieldHitOffset = 0.0f;
        if (mShieldRecoilCounter > 0)
            aShieldHitOffset = TodAnimateCurveFloat(12, 0, mShieldRecoilCounter, 3.0f, 0.0f, CURVE_LINEAR);

        aGraphics->mTransX = aGraphics->mTransX + aShieldHitOffset;
        aBodyReanim->DrawRenderGroup(aGraphics, 1);
        aGraphics->mTransX = aGraphics->mTransX - aShieldHitOffset;

        // Only the held shields get the group that draws in front of them.
        if (mShieldType == SHIELDTYPE_DOOR
            || mShieldType == SHIELDTYPE_NEWSPAPER
            || mShieldType == SHIELDTYPE_LADDER
            || mShieldType == SHIELDTYPE_TRASHCAN)
        {
            aBodyReanim->mColorOverride = aColorOverride;
            aBodyReanim->mExtraAdditiveColor = aExtraAdditiveColor;
            aBodyReanim->mEnableExtraAdditiveDraw = aEnableExtraAdditiveDraw;
            aBodyReanim->DrawRenderGroup(aGraphics, 3);
        }
    }

    if (aColorChanged)
        aBodyReanim->PropogateColorToAttachments();

    aGraphics->ClearClipRect();
  return 0;
}

// ==========================================================================
// Zombie::DrawBungeeReanim(Sexy::Graphics *,ZombieDrawPosition &)
// @001ACDA8  446 bytes
// ==========================================================================
void Zombie::DrawBungeeReanim(Sexy::Graphics * aGraphics, ZombieDrawPosition & aDrawPos)
{
    ZombieDrawPosition &aPos = aDrawPos;

    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);

    // The cord hangs from the head down to the target, 22 pixels above it.
    DrawBungeeCord(aGraphics, -22, (int)((aPos.mBodyY + aPos.mImageOffsetY) + 14.0f));
    aBodyReanim->DrawRenderGroup(aGraphics, 0);

    // mRelatedZombieID (+0x100) is the held zombie's slot id. The index is the
    // low 16 bits, bounded by the array capacity, and a mismatched id falls
    // through to the held plant. The graphics transform is saved around the draw.
    Zombie *aTarget = nullptr;
    if (mRelatedZombieID != ZOMBIEID_NULL
        && (unsigned int)(unsigned __int16)mRelatedZombieID < mBoard->mZombies.mMaxSize)
    {
        ZombieSlot *aSlots = mBoard->mZombies.mBlock;
        ZombieSlot *aTargetSlot = aSlots + (unsigned __int16)mRelatedZombieID;
        if (mRelatedZombieID == aTargetSlot->mID)
            aTarget = &aTargetSlot->mItem;
    }

    if (aTarget != nullptr)
    {
        float aSavedTransX = aGraphics->mTransX;
        float aSavedTransY = aGraphics->mTransY;
        Sexy::Color aSavedColor = aGraphics->GetColor();
        bool aSavedColorize = aGraphics->GetColorizeImages() != 0;

        float aTargetTransX = (aTarget->mPosX + aGraphics->mTransX) - mPosX;
        aGraphics->mTransY = aGraphics->mTransY - mAltitude;
        aGraphics->mTransX = aTargetTransX;

        ZombieDrawPosition aTargetDrawPos;
        aTarget->GetDrawPos(aTargetDrawPos);
        aTarget->DrawReanim(aGraphics, aTargetDrawPos, 0);

        aGraphics->mTransX = aSavedTransX;
        aGraphics->mTransY = aSavedTransY;
        aGraphics->SetColor(aSavedColor);
        aGraphics->SetColorizeImages(aSavedColorize);
    }
    else if (mTargetPlantID != PLANTID_NULL
             && (unsigned int)(unsigned __int16)mTargetPlantID < mBoard->mPlants.mMaxSize)
    {
        PlantSlot *aSlots = mBoard->mPlants.mBlock;
        PlantSlot *aPlantSlot = aSlots + (unsigned __int16)mTargetPlantID;
        if (mTargetPlantID == aPlantSlot->mID)
        {
            Plant *aPlant = &aPlantSlot->mItem;

            float aSavedTransX = aGraphics->mTransX;
            float aSavedTransY = aGraphics->mTransY;
            Sexy::Color aSavedColor = aGraphics->GetColor();
            bool aSavedColorize = aGraphics->GetColorizeImages() != 0;

            float aPlantTransY = (aGraphics->mTransY + 30.0f) - mAltitude;
            aGraphics->mTransY = aPlantTransY;
            // While the bungee is rising, a spikeweed or a spikerock is drawn
            // 34 pixels lower. The test is the phase word (+0x38), not the type.
            if (mZombiePhase == PHASE_BUNGEE_RISING)
            {
                if (aPlant->mSeedType == SEED_SPIKEWEED || aPlant->mSeedType == SEED_SPIKEROCK)
                    aGraphics->mTransY = aPlantTransY - 34.0f;
            }

            // A plant in the left-hand columns of a roof stage is lifted ten
            // pixels, to follow the slope.
            if (aPlant->mPlantCol <= 4 && mBoard->StageHasRoof())
                aGraphics->mTransY = aGraphics->mTransY + 10.0f;

            aPlant->Draw(aGraphics);
            aGraphics->mTransX = aSavedTransX;
            aGraphics->mTransY = aSavedTransY;
            aGraphics->SetColor(aSavedColor);
            aGraphics->SetColorizeImages(aSavedColorize);
        }
    }

    aBodyReanim->DrawRenderGroup(aGraphics, 2);
}

// ==========================================================================
// Zombie::Draw(Sexy::Graphics *)
// @001ACF6C  328 bytes
// ==========================================================================
void Zombie::Draw(Sexy::Graphics * aGraphics)
{
    // A zombiquarium zombie is drawn by the aquarium itself.
    if (mZombieType == ZOMBIE_ZOMBLOB)
        return;

    ZombieDrawPosition aDrawPos;
    GetDrawPos(aDrawPos);

    // Outside the playing scene the zombie only draws through the
    // "zombies won" setup; a zombiquarium game mode keeps the aquarium's own
    // zombies out of the lawn's draw, except the one the mode spawns.
    if (mApp->mGameScene != SCENE_PLAYING && SetupDrawZombieWon(aGraphics) == 0)
        return;

    // The ice trap goes both behind and in front of the body, the butter only
    // in front.
    if (mIceTrapCounter > 0)
        DrawIceTrap(aGraphics, aDrawPos, 0);

    if ((mApp->mGameMode != GAMEMODE_CHALLENGE_INVISIGHOUL || mFromWave == -3) && mVisible)
    {
        if (mBodyReanimID != 0)
            DrawReanim(aGraphics, aDrawPos, 0);
        else
            DrawZombie(aGraphics, aDrawPos);
    }

    if (mIceTrapCounter > 0)
        DrawIceTrap(aGraphics, aDrawPos, 1);

    if (mButteredCounter > 0)
        DrawButter(aGraphics, aDrawPos);

    // An attachment is drawn through the Graphics, so its transform is saved
    // and restored and the attachment is clipped to its own frame.
    if (mAttachmentID != 0)
    {
        float aSavedTransX = aGraphics->mTransX;
        float aSavedTransY = aGraphics->mTransY;
        ZombieDrawPosition &aPos = aDrawPos;
        // Slot 4 of GameObject's vtable -- the frame the attachment draws in.
        MakeParentGraphicsFrame(aGraphics);
        aGraphics->mTransY = aGraphics->mTransY + aPos.mBodyY;
        if (aPos.mClipHeight > -100.0f)
        {
            aGraphics->ClipRect((int)((aPos.mImageOffsetX - 400.0f) + (float)mX),
                                (int)((aPos.mImageOffsetY - 28.0f) + (float)mY),
                                920,
                                (int)(141.0f - aPos.mClipHeight));
        }

        AttachmentDraw(mAttachmentID, aGraphics, 0);
        aGraphics->mTransX = aSavedTransX;
        aGraphics->mTransY = aSavedTransY;
    }

    aGraphics->ClearClipRect();
  return;
}

// ==========================================================================
// Zombie::IsDeadOrDying(void)
// @001AD0C0  34 bytes
// ==========================================================================
int Zombie::IsDeadOrDying()
{
    return mDead
        || mZombiePhase == PHASE_ZOMBIE_DYING
        || mZombiePhase == PHASE_ZOMBIE_BURNED
        || mZombiePhase == PHASE_ZOMBIE_MOWERED;
}

// ==========================================================================
// Zombie::CountBungeesTargetingSunFlowers(void)
// @001AD0E4  94 bytes
// ==========================================================================
int Zombie::CountBungeesTargetingSunFlowers()
{
    int aCount = 0;
    Zombie *aZombie = nullptr;
    while (mBoard->IterateZombies(aZombie))
    {
        if (aZombie->IsDeadOrDying())
            continue;

        if (aZombie->mZombieType != ZOMBIE_BUNGEE)
            continue;

        if (aZombie->mTargetCol == -1)
            continue;

        Plant *aPlant = mBoard->GetTopPlantAt(aZombie->mTargetCol, aZombie->mRow, (PlantPriority)2);
        if (aPlant == nullptr || !aPlant->MakesSun())
            continue;

        aCount++;
    }
    return aCount;
}

// ==========================================================================
// Zombie::UpdateAnimSpeed(void)
// @001AD144  338 bytes
// ==========================================================================
// Every path either returns early or applies a rate. Callers ignore the
// leftover register.
void Zombie::UpdateAnimSpeed()
{
    if (!IsOnBoard())
        return;

    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr)
        return;

    if (IsImmobilizied() || (mYuckyFace && mYuckyFaceCounter <= 169))
    {
        ApplyAnimRate(0.0f);
        return;
    }

    // Both snorkel eating phases (60 and 62, the `BIC #2` against 0x3C) and a
    // dying zombie hold whatever rate the animation was started with.
    if (mZombiePhase == PHASE_SNORKEL_UP_TO_EAT
        || mZombiePhase == PHASE_SNORKEL_DOWN_FROM_EAT
        || IsDeadOrDying())
    {
        ApplyAnimRate(mOriginalAnimRate);
        return;
    }

    // A chewing zombie eats slowly. The 20.0 group is types 3 and 11 (the
    // `BIC #8` against 3), 24, the run 15..17, and 19.
    if (mIsEating)
    {
        if (mZombieType == ZOMBIE_POLEVAULTER
            || mZombieType == ZOMBIE_SNORKEL
            || mZombieType == ZOMBIE_IMP
            || mZombieType == ZOMBIE_JACK_IN_THE_BOX
            || mZombieType == ZOMBIE_BALLOON
            || mZombieType == ZOMBIE_DIGGER
            || mZombieType == ZOMBIE_YETI)
        {
            ApplyAnimRate(20.0f);
            return;
        }
        ApplyAnimRate(36.0f);
        return;
    }

    // The ones that slide or float keep their own rate rather than the walk
    // track's.
    if (ZombieNotWalking()
        || IsBobsledTeamWithSled()
        || mZombieType == ZOMBIE_CATAPULT
        || mZombiePhase == PHASE_DOLPHIN_RIDING
        || mZombiePhase == PHASE_SNORKEL_WALKING_IN_POOL)
    {
        ApplyAnimRate(mOriginalAnimRate);
        return;
    }

    // Otherwise the rate is the walking speed over the distance the body
    // animation's _ground track covers in one cycle of the current play range.
    // The track is the 20-byte record, its transforms the 0x30-byte ones, so
    // the two reads are mTransX of frame (start + count - 1) and of frame start.
    if (aBodyReanim->TrackExistsById(ReanimTrackId__ground) != 0)
    {
        int aTrackIndex = aBodyReanim->FindTrackIndexById(ReanimTrackId__ground);
        ReanimatorTrack *aTrack = &aBodyReanim->mDefinition->mTracks[aTrackIndex];
        int aFrameStart = aBodyReanim->mFrameStart;
        int aFrameCount = aBodyReanim->mFrameCount;
        float aDistance = aTrack->mTransforms[aFrameStart + aFrameCount - 1].mTransX
                        - aTrack->mTransforms[aFrameStart].mTransX;
        if (aDistance >= 0.000001f)
            ApplyAnimRate(mVelX * 47.0f * ((float)aFrameCount / aDistance) / mScaleZombie);
    }
}
// ==========================================================================
// Zombie::PickRandomSpeed(void)
// @001AD2A8  342 bytes
// ==========================================================================
Reanimation * Zombie::PickRandomSpeed()
{
    // A snorkel that is walking through the pool has a fixed 0.3 speed.
    if (mZombiePhase == PHASE_SNORKEL_WALKING_IN_POOL)
    {
        mVelX = 0.3f;
    }
    else if (mZombiePhase == PHASE_DIGGER_WALKING)
    {
        mVelX = mApp->IsIZombieLevel() ? 0.23f : 0.12f;
        UpdateAnimSpeed();
        return nullptr;
    }
    else if (mZombieType == ZOMBIE_IMP && mApp->IsIZombieLevel())
    {
        mVelX = 0.9f;
        UpdateAnimSpeed();
        return nullptr;
    }
    else if (mZombiePhase == PHASE_YETI_RUNNING)
    {
        mVelX = 0.8f;
    }
    else if (mZombieType == ZOMBIE_YETI)
    {
        mVelX = 0.4f;
    }
    else if (mZombieType == ZOMBIE_POGO
             || mZombieType == ZOMBIE_DANCER
             || mZombieType == ZOMBIE_BACKUP_DANCER
             || mZombieType == ZOMBIE_FLAG)
    {
        mVelX = 0.45f;
        UpdateAnimSpeed();
        return nullptr;
    }
    else if (mZombiePhase == PHASE_POLEVAULTER_PRE_VAULT
             || mZombiePhase == PHASE_DIGGER_TUNNELING
             || mZombieType == ZOMBIE_FOOTBALL
             || mZombieType == ZOMBIE_JACK_IN_THE_BOX
             || mZombieType == ZOMBIE_SNORKEL)
    {
        mVelX = RandRangeFloat(0.66f, 0.68f);
        UpdateAnimSpeed();
        return nullptr;
    }
    else if (mZombiePhase == PHASE_LADDER_CARRYING || mZombieType == ZOMBIE_SQUASH_HEAD)
    {
        mVelX = RandRangeFloat(0.79f, 0.81f);
    }
    else if (mZombiePhase == PHASE_DOLPHIN_WALKING
             || mZombiePhase == PHASE_NEWSPAPER_MAD
             || mZombiePhase == PHASE_DOLPHIN_WALKING_WITHOUT_DOLPHIN)
    {
        mVelX = RandRangeFloat(0.89f, 0.91f);
    }
    else
    {
        // A plain zombie gets a random speed; a slow one also animates slower.
        mVelX = RandRangeFloat(0.23f, 0.37f);
        mAnimTicksPerFrame = (mVelX < 0.3f) ? 12 : 15;
    }

    UpdateAnimSpeed();
    return nullptr;
}
// ==========================================================================
// Zombie::PlayZombieReanim(char const*,ReanimLoopType,int,float)
// @001AD408  84 bytes
// ==========================================================================
Reanimation * Zombie::PlayZombieReanim(char const* theTrackName, ReanimLoopType theLoopType, int theBlendTime, float theAnimRate)
{
    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr)
        return nullptr;

    aBodyReanim->PlayReanim(theTrackName, theLoopType, theBlendTime, theAnimRate);
    if (theAnimRate != 0.0f)
        mOriginalAnimRate = theAnimRate;

    UpdateAnimSpeed();
    return aBodyReanim;
}

// ==========================================================================
// Zombie::BungeeDropZombie(Zombie*,int,int)
// @001AD45C  154 bytes
// ==========================================================================
Reanimation * Zombie::BungeeDropZombie(Zombie *theZombie, int theCol, int theRow)
{
    mTargetCol = theCol;
    SetRow(theRow);

    // The bungee carries the zombie 15 pixels to its left.
    int aPixelX = mBoard->GridToPixelX(mTargetCol, mRow);
    mPosX = (float)aPixelX;
    mPosY = GetPosYBasedOnRow(mRow);

    PlayZombieReanim("anim_raise", REANIM_PLAY_ONCE_AND_HOLD, 0, 36.0f);

    mRelatedZombieID = (ZombieID)mBoard->ZombieGetID(theZombie);
    float aZombieX = mPosX;
    theZombie->mPosX = aZombieX - 15.0f;
    theZombie->SetRow(theRow);
    theZombie->mPosY = GetPosYBasedOnRow(theRow);
    theZombie->mZombieHeight = HEIGHT_GETTING_BUNGEE_DROPPED;

    Reanimation *aResult = theZombie->PlayZombieReanim("anim_idle", REANIM_LOOP, 0, 0.0f);
    theZombie->mRenderOrder = mRenderOrder + 1;
    return aResult;
}

// ==========================================================================
// Zombie::UpdateZombieCatapult(void)
// @001AD500  362 bytes
// ==========================================================================
void Zombie::UpdateZombieCatapult()
{
    if (mZombiePhase == PHASE_ZOMBIE_NORMAL)
    {
        // Lob once inside x = 650, with a target and the summon counter still
        // running. 300 is mPhaseCounter (+0x78), and this shoot blends over 0.
        if (mPosX <= 650.0f && FindCatapultTarget() != nullptr && mSummonCounter > 0)
        {
            mPhaseCounter = 300;
            mZombiePhase = PHASE_CATAPULT_LAUNCHING;
            PlayZombieReanim("anim_shoot", REANIM_PLAY_ONCE_AND_HOLD, 0, 24.0f);
            return;
        }
        return;
    }

    if (mZombiePhase == PHASE_CATAPULT_RELOADING)
    {
        if (mPhaseCounter != 0)
            return;

        if (FindCatapultTarget() != nullptr)
        {
            mZombiePhase = PHASE_CATAPULT_LAUNCHING;
            mPhaseCounter = 300;
            PlayZombieReanim("anim_shoot", REANIM_PLAY_ONCE_AND_HOLD, 20, 24.0f);
            return;
        }

        // Nothing left to lob. Phase is cleared after the reanim so
        // UpdateAnimSpeed still sees reloading.
        PlayZombieReanim("anim_walk", REANIM_LOOP, 20, 6.0f);
        mZombiePhase = PHASE_ZOMBIE_NORMAL;
        return;
    }

    if (mZombiePhase != PHASE_CATAPULT_LAUNCHING)
        return;

    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
    // A miss leaves ShouldTrigger's 0 in r0; a hit leaves ZombieCatapultFire's r0.
    // Either is the return when the shoot animation has not looped yet.
    if (aBodyReanim->ShouldTriggerTimedEvent(0.545f))
        ZombieCatapultFire(FindCatapultTarget());

    if (aBodyReanim->mLoopCount <= 0)
        return;

    // The four basketballs disappear one per loop, then the zombie reloads.
    mSummonCounter--;
    switch (mSummonCounter)
    {
        case 4:
            ReanimShowTrack("Zombie_catapult_basketball", -1);
            break;
        case 3:
            ReanimShowTrack("Zombie_catapult_basketball2", -1);
            break;
        case 2:
            ReanimShowTrack("Zombie_catapult_basketball3", -1);
            break;
        case 1:
            ReanimShowTrack("Zombie_catapult_basketball4", -1);
            break;
        default:
            break;
    }

    if (mSummonCounter != 0)
    {
        PlayZombieReanim("anim_idle", REANIM_LOOP, 20, 12.0f);
        mZombiePhase = PHASE_CATAPULT_RELOADING;
        return;
    }

    PlayZombieReanim("anim_walk", REANIM_LOOP, 20, 6.0f);
    mZombiePhase = PHASE_ZOMBIE_NORMAL;
    return;
}

// ==========================================================================
// Zombie::UpdateZombieBackupDancer(void)
// @001AD694  206 bytes
// r0 is this, TodAnimateCurve, GetDancerPhase, PlayZombieReanim, or
// ReanimationGet. The only caller ignores it.
// ==========================================================================
void Zombie::UpdateZombieBackupDancer()
{
    if (mIsEating)
        return;

    // The dancer rises out of the ground on a linear curve. A still-running
    // rise returns TodAnimateCurve's r0. High ground then pins the altitude
    // at 30 before the phase switch.
    if (mZombiePhase == PHASE_DANCER_RISING)
    {
        int aRise = TodAnimateCurve(150, 0, mPhaseCounter, -200, 0, CURVE_LINEAR);
        mAltitude = (float)aRise;
        if (mPhaseCounter != 0)
            return;

        if (IsOnHighGround())
            mAltitude = 30.0f;
    }

    int aDancerPhase = GetDancerPhase();
    if (aDancerPhase == mZombiePhase)
        return;

    // 0x2C. Unmatched phases leave GetDancerPhase in r0.
    if (aDancerPhase == PHASE_DANCER_DANCING_LEFT)
    {
        mZombiePhase = (ZombiePhase)aDancerPhase;
        PlayZombieReanim("anim_walk", REANIM_LOOP, 10, 0.0f);
        return;
    }
    // 0x2D. The walk-to-raise path sets the body animation time after starting
    // the raise. The caller ignores the leftover register.
    if (aDancerPhase == PHASE_DANCER_WALK_TO_RAISE)
    {
        mZombiePhase = (ZombiePhase)aDancerPhase;
        PlayZombieReanim("anim_armraise", REANIM_LOOP, 10, 18.0f);
        Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
        aBodyReanim->mAnimTime = 0.6f;
        return;
    }
    // 0x2E..0x31: RAISE_LEFT_1, RAISE_RIGHT_1, RAISE_LEFT_2, RAISE_RIGHT_2.
    if ((unsigned)(aDancerPhase - PHASE_DANCER_RAISE_LEFT_1) <= 3)
    {
        mZombiePhase = (ZombiePhase)aDancerPhase;
        PlayZombieReanim("anim_armraise", REANIM_LOOP, 10, 18.0f);
        return;
    }
    return;
}

// ==========================================================================
// Zombie::UpdateZombieDancer(void)
// @001AD770  426 bytes
// r0 is this, GetDancerFrame, ReanimationGet, SummonBackupDancers,
// PickRandomSpeed, GetDancerPhase, PlayZombieReanim, or NeedsMoreBackupDancers.
// The only caller ignores it.
// ==========================================================================
void Zombie::UpdateZombieDancer()
{
    if (mIsEating)
        return;

    // A failed beat leaves GetDancerFrame in r0. That value is what the
    // dancing-in and hold early-outs return; every other path overwrites it.
    bool aCheckedDancingIn = false;
    if (mSummonCounter > 0 && --mSummonCounter == 0)
    {
        int aFrame = GetDancerFrame();
        if (aFrame == 12 && mHasHead && mPosX < 700.0f)
        {
            mZombiePhase = PHASE_DANCER_SNAPPING_FINGERS_WITH_LIGHT;
            PlayZombieReanim("anim_point", REANIM_PLAY_ONCE_AND_HOLD, 20, 24.0f);
        }
        else
        {
            mSummonCounter = 1;
            aCheckedDancingIn = mZombiePhase != PHASE_DANCER_DANCING_IN;
        }
    }

    if (!aCheckedDancingIn && mZombiePhase == PHASE_DANCER_DANCING_IN)
    {
        if (mHasHead && mPhaseCounter == 0)
        {
            mZombiePhase = PHASE_DANCER_SNAPPING_FINGERS;
            PlayZombieReanim("anim_point", REANIM_PLAY_ONCE_AND_HOLD, 20, 24.0f);
            PickRandomSpeed();
            return;
        }
        return;
    }

    // 0x29 and 0x2A. A still-playing point returns ReanimationGet.
    if ((unsigned)(mZombiePhase - PHASE_DANCER_SNAPPING_FINGERS) <= 1)
    {
        Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
        if (aBodyReanim->mLoopCount <= 0)
            return;

        if (mZombiePhase == PHASE_DANCER_SNAPPING_FINGERS && mBoard->CountZombiesOnScreen() <= 15)
            mApp->PlayFoley(FOLEY_DANCER);

        SummonBackupDancers();
        mZombiePhase = PHASE_DANCER_SNAPPING_FINGERS_HOLD;
        mPhaseCounter = 200;
        return;
    }

    if (mZombiePhase == PHASE_DANCER_SNAPPING_FINGERS_HOLD)
    {
        if (mPhaseCounter != 0)
            return;

        mZombiePhase = PHASE_DANCER_DANCING_LEFT;
        PlayZombieReanim("anim_walk", REANIM_LOOP, 20, 0.0f);
    }

    int aDancerPhase = GetDancerPhase();
    if (aDancerPhase != mZombiePhase)
    {
        if (aDancerPhase == PHASE_DANCER_DANCING_LEFT)
        {
            mZombiePhase = PHASE_DANCER_DANCING_LEFT;
            PlayZombieReanim("anim_walk", REANIM_LOOP, 10, 0.0f);
        }
        else if (aDancerPhase == PHASE_DANCER_WALK_TO_RAISE)
        {
            mZombiePhase = PHASE_DANCER_WALK_TO_RAISE;
            PlayZombieReanim("anim_armraise", REANIM_LOOP, 10, 18.0f);
            Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
            aBodyReanim->mAnimTime = 0.6f;
        }
        else if ((unsigned)(aDancerPhase - PHASE_DANCER_RAISE_LEFT_1) <= 3)
        {
            mZombiePhase = (ZombiePhase)aDancerPhase;
            PlayZombieReanim("anim_armraise", REANIM_LOOP, 10, 18.0f);
        }
    }

    if (!mHasHead || mSummonCounter != 0)
        return;

    if (NeedsMoreBackupDancers())
        mSummonCounter = 100;
    return;
}

// ==========================================================================
// Zombie::StartEating(void)
// @001AD938  114 bytes
// EatZombie keeps r0, so the signature stays Zombie *. PlayZombieReanim and
// ShowDoorArms are recovered with (Zombie *).
// ==========================================================================
Zombie * Zombie::StartEating()
{
    if (mIsEating)
        return this;

    ZombiePhase aPhase = mZombiePhase;
    mIsEating = true;
    // 0x20 is PHASE_DIGGER_TUNNELING, not PHASE_ZOMBIE_DYING.
    if (aPhase == PHASE_DIGGER_TUNNELING)
        return this;

    if (aPhase == PHASE_LADDER_CARRYING)
    {
        PlayZombieReanim("anim_laddereat", REANIM_LOOP, 20, 0.0f);
        return this;
    }

    if (aPhase == PHASE_NEWSPAPER_MAD)
    {
        PlayZombieReanim("anim_eat_nopaper", REANIM_LOOP, 20, 0.0f);
        return this;
    }

    if (mZombieType != ZOMBIE_SNORKEL)
        PlayZombieReanim("anim_eat", REANIM_LOOP, 20, 0.0f);

    // A door or a trash can is held out of the way while the zombie eats.
    if (mShieldType == SHIELDTYPE_DOOR || mShieldType == SHIELDTYPE_TRASHCAN)
        ShowDoorArms(false);

    return this;
}

// ==========================================================================
// Zombie::StartWalkAnim(int)
// @001AD9B8  268 bytes
// ==========================================================================
Reanimation * Zombie::StartWalkAnim(int theBlendTime)
{
    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr)
        return nullptr;

    PickRandomSpeed();

    if (mZombiePhase == PHASE_LADDER_CARRYING)
        return PlayZombieReanim("anim_ladderwalk", REANIM_LOOP, theBlendTime, 0.0f);

    if (mZombiePhase == PHASE_NEWSPAPER_MAD)
        return PlayZombieReanim("anim_walk_nopaper", REANIM_LOOP, theBlendTime, 0.0f);

    // A swimming zombie takes the swim cycle unless it is on its way in or out
    // of the water (height 1 or 2). Height 0 still swims.
    if (mInPool
        && (unsigned int)(mZombieHeight - HEIGHT_IN_TO_POOL) > 1
        && aBodyReanim->TrackExistsById(ReanimTrackId_anim_swim) != 0)
    {
        return PlayZombieReanim("anim_swim", REANIM_LOOP, theBlendTime, 0.0f);
    }

    // A plain zombie dances while the board is in dance mode. Rand is not
    // consumed on that path; every other path calls it before the walk2 test.
    if ((mZombieType == ZOMBIE_NORMAL || mZombieType == ZOMBIE_TRAFFIC_CONE || mZombieType == ZOMBIE_PAIL)
        && mBoard->mDanceMode)
    {
        return PlayZombieReanim("anim_dance", REANIM_LOOP, theBlendTime, 0.0f);
    }

    int aRand = Rand(2);
    if ((mZombieType == ZOMBIE_PEA_HEAD || mZombieType == ZOMBIE_FLAG || aRand == 0)
        && aBodyReanim->TrackExistsById(ReanimTrackId_anim_walk2) != 0)
    {
        return PlayZombieReanim("anim_walk2", REANIM_LOOP, theBlendTime, 0.0f);
    }

    if (aBodyReanim->TrackExistsById(ReanimTrackId_anim_walk) != 0)
        return PlayZombieReanim("anim_walk", REANIM_LOOP, theBlendTime, 0.0f);

    return nullptr;
}

// ==========================================================================
// Zombie::UpdateZombieNewspaper(void)
// @001ADAEC  90 bytes
// A newspaper that is not yet mad, or whose mad animation has not looped,
// does nothing. Once it has, the head image becomes the mad head.
// ==========================================================================
void Zombie::UpdateZombieNewspaper()
{
    // 0x1E. Reading is the idle phase; this function runs once the paper is mad.
    if (mZombiePhase != PHASE_NEWSPAPER_MADDENING)
        return;

    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
    if (aBodyReanim->mLoopCount <= 0)
        return;

    mZombiePhase = PHASE_NEWSPAPER_MAD;
    if (mBoard->CountZombiesOnScreen() <= 10 && mHasHead)
        mApp->PlayFoley(FOLEY_NEWSPAPER_RARRGH);

    StartWalkAnim(20);
    aBodyReanim->SetImageOverride("anim_head1", IMAGE_REANIM_ZOMBIE_PAPER_MADHEAD);
}

// ==========================================================================
// Zombie::UpdateZombiePool(void)
// @001ADB54  148 bytes
// ==========================================================================
void Zombie::UpdateZombiePool()
{
    switch (mZombieHeight)
    {
        case HEIGHT_OUT_OF_POOL:
            mAltitude += 1.0f;
            // The snorkel comes up a pixel a frame faster than the rest.
            if (mZombieType == ZOMBIE_SNORKEL)
                mAltitude += 1.0f;

            if (mAltitude >= 0.0f)
            {
                mAltitude = 0.0f;
                mZombieHeight = HEIGHT_ZOMBIE_NORMAL;
                mInPool = false;
            }
            break;
        case HEIGHT_IN_TO_POOL:
        {
            mAltitude -= 1.0f;
            // VCVT.S32.F32 truncates the scaled depth before the compare.
            float aDepth = (float)(int)(-40.0f * mScaleZombie);
            if (mAltitude <= aDepth)
            {
                mAltitude = aDepth;
                mZombieHeight = HEIGHT_ZOMBIE_NORMAL;
                StartWalkAnim(0);
            }
            break;
        }
        case HEIGHT_DRAGGED_UNDER:
            mAltitude -= 1.0f;
            break;
        default:
            break;
    }
}

// ==========================================================================
// Zombie::RiseFromGrave(int,int)
// @001ADBEC  578 bytes
// ==========================================================================
void Zombie::RiseFromGrave(int theCol, int theRow)
{
    mPosX = (float)(mBoard->GridToPixelX(theCol, mRow) - 25);
    mPosY = GetPosYBasedOnRow(theRow);
    SetRow(theRow);

    float aPosX = mPosX;
    float aPosY = mPosY;
    mZombiePhase = PHASE_RISING_FROM_GRAVE;
    mPhaseCounter = 150;
    mAltitude = -200.0f;
    mX = (int)aPosX;
    mY = (int)aPosY;

    if (mBoard->StageHasPool())
    {
        mPhaseCounter = 50;
        mInPool = true;
        mAltitude = -150.0f;
        mZombieHeight = HEIGHT_ZOMBIE_NORMAL;
        StartWalkAnim(0);
        ReanimIgnoreClipRect("Zombie_duckytube", false);
        ReanimIgnoreClipRect("Zombie_whitewater", false);
        ReanimIgnoreClipRect("Zombie_outerarm_hand", false);
        ReanimIgnoreClipRect("Zombie_innerarm3", false);

        // The seaweed clings to the cone, the pail or the head, and to the
        // raised arm and the ducky tube. AddTodParticle returns the system id.
        Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
        TodParticleSystem *aParticle =
            (TodParticleSystem *)mApp->AddTodParticle(0, 0, 0, (ParticleEffect)94);
        OverrideParticleScale(aParticle);
        if (mZombieType == ZOMBIE_TRAFFIC_CONE)
        {
            if (aParticle != nullptr)
                aBodyReanim->AttachParticleToTrack("anim_cone", aParticle, 37.0f, 20.0f);
        }
        else if (mZombieType == ZOMBIE_PAIL)
        {
            if (aParticle != nullptr)
                aBodyReanim->AttachParticleToTrack("anim_bucket", aParticle, 37.0f, 20.0f);
        }
        else if (aParticle != nullptr)
        {
            aBodyReanim->AttachParticleToTrack("anim_head1", aParticle, 30.0f, 20.0f);
        }

        TodParticleSystem *aParticle2 =
            (TodParticleSystem *)mApp->AddTodParticle(0, 0, 0, (ParticleEffect)94);
        OverrideParticleScale(aParticle2);
        if (aParticle2 != nullptr)
            aBodyReanim->AttachParticleToTrack("Zombie_outerarm_upper", aParticle2, 5.0f, 5.0f);

        TodParticleSystem *aParticle3 =
            (TodParticleSystem *)mApp->AddTodParticle(0, 0, 0, (ParticleEffect)94);
        OverrideParticleScale(aParticle3);
        if (aParticle3 != nullptr)
            aBodyReanim->AttachParticleToTrack("Zombie_duckytube", aParticle3, 77.0f, 20.0f);

        PoolSplash(false);
        return;
    }

    // A zombie rising on dry land throws dirt, 30 pixels lower on a roof.
    // The two coordinates are (int)mPosX + 60 and (int)mPosY (+80 on high ground, else +110).
    int aParticleX = (int)mPosX + 60;
    int aParticleY = (int)mPosY + 110;
    if (IsOnHighGround())
        aParticleY = (int)mPosY + 80;

    // MOVW/MOVT loads 0x4AF38 (RENDER_LAYER_PARTICLE). Hex-Rays prints that as "VER_MASKE".
    int aRenderOrder = Board::MakeRenderOrder(RenderLayer::RENDER_LAYER_PARTICLE, theRow, 0);
    if (mApp->IsWhackAZombieLevel())
    {
        mApp->PlayFoley(FOLEY_DIRT_RISE);
        mApp->AddTodParticle((float)aParticleX, (float)aParticleY, aRenderOrder, (ParticleEffect)54);
    }

    mApp->PlayFoley(FOLEY_GRAVESTONE_RUMBLE);
    mApp->AddTodParticle((float)aParticleX, (float)aParticleY, aRenderOrder, (ParticleEffect)24);
}

// ==========================================================================
// Zombie::BobsledCrash(void)
// @001ADE54  176 bytes
// ==========================================================================
void Zombie::BobsledCrash()
{
    mZombieRect = Sexy::Rect(36, 0, 42, 115);
    mZombiePhase = PHASE_BOBSLED_CRASHING;
    mPhaseCounter = 150;
    mAltitude = 0.0f;
    // +0x17C is the cached rect's width, not the ice/butter/anim counters.
    mCachedZombieRect.mWidth = 0;

    StartWalkAnim(0);

    // The cursor walks this, this+4, this+8 and stops at this+0xC, so only
    // the first three follower ids are crashed. Each follower matches the
    // leader's animation rate.
    Reanimation *aLeaderReanim = mApp->ReanimationGet(mBodyReanimID);
    for (int i = 0; i < 3; i++)
    {
        Zombie *aFollower = mBoard->ZombieGet(mFollowerZombieID[i]);
        aFollower->mZombiePhase = PHASE_BOBSLED_CRASHING;
        aFollower->mPhaseCounter = 150;
        aFollower->mPosY = GetPosYBasedOnRow(mRow);
        aFollower->mAltitude = 0.0f;
        aFollower->StartWalkAnim(0);

        Reanimation *aFollowerReanim = mApp->ReanimationGet(aFollower->mBodyReanimID);
        aFollower->mVelX = mVelX;
        aFollowerReanim->mAnimTime = Rand(1.0f);
        aFollowerReanim->SetAnimRate(aLeaderReanim->mAnimRate);
    }
}

// ==========================================================================
// Zombie::DropHelm(unsigned int)
// @001ADF08  342 bytes
// ==========================================================================
Zombie * Zombie::DropHelm(unsigned int theDamageFlags)
{
    if (mHelmType == HELMTYPE_NONE)
        return this;

    ZombieDrawPosition aPos;
    GetDrawPos(aPos);

    float aPosX = ((mPosX + aPos.mImageOffsetX) + (float)aPos.mHeadX) + 14.0f;
    float aPosY = ((((mPosY + aPos.mImageOffsetY) + (float)aPos.mHeadY) + aPos.mBodyY) + 18.0f);

    // Which particle the lost helm throws, and which track it comes off.
    int aEffect = 0;
    switch (mHelmType)
    {
        case HELMTYPE_TRAFFIC_CONE:
            GetTrackPosition("anim_cone", aPosX, aPosY);
            ReanimShowPrefix("anim_cone", -1);
            ReanimShowPrefix("anim_hair", 0);
            aEffect = 8;
            break;
        case HELMTYPE_PAIL:
            GetTrackPosition("anim_bucket", aPosX, aPosY);
            ReanimShowPrefix("anim_bucket", -1);
            ReanimShowPrefix("anim_hair", 0);
            aEffect = 9;
            break;
        case HELMTYPE_FOOTBALL:
            GetTrackPosition("zombie_football_helmet", aPosX, aPosY);
            ReanimShowPrefix("zombie_football_helmet", -1);
            ReanimShowPrefix("anim_hair", 0);
            aEffect = 10;
            break;
        case HELMTYPE_DIGGER:
            GetTrackPosition("Zombie_digger_hardhat", aPosX, aPosY);
            ReanimShowTrack("Zombie_digger_hardhat", -1);
            aEffect = 15;
            break;
        default:
            // The bobsled helmet is the sled itself: losing it crashes the sled.
            if (mHelmType == HELMTYPE_BOBSLED && (theDamageFlags & 0x10) == 0)
                BobsledCrash();
            mHelmType = HELMTYPE_NONE;
            return this;
    }

    if ((theDamageFlags & 0x10) == 0)
    {
        TodParticleSystem *aParticle = (TodParticleSystem *)mApp->AddTodParticle(aPosX,
                                                                                  aPosY,
                                                                                  mRenderOrder + 1,
                                                                                  (ParticleEffect)aEffect);
        OverrideParticleScale(aParticle);
    }

    mHelmType = HELMTYPE_NONE;
    return this;
}

// ==========================================================================
// Zombie::PogoBreak(unsigned int)
// @001AE07C  160 bytes
// ==========================================================================
void Zombie::PogoBreak(unsigned int theDamageFlags)
{
    if (!mHasObject)
        return;

    if ((theDamageFlags & 0x10) == 0)
    {
        ZombieDrawPosition aPos;
        GetDrawPos(aPos);

        int aRenderOrder = mRenderOrder;
        float aStickX = 0.0f;
        float aStickY = 0.0f;
        GetTrackPosition("Zombie_pogo_stick", aStickX, aStickY);

        TodParticleSystem *aParticle = mApp->AddTodParticle(aStickX,
                                                                                 aStickY + 30.0f,
                                                                                 aRenderOrder + 1,
                                                                                 (ParticleEffect)17);
        OverrideParticleScale(aParticle);
    }

    // Losing the pogo stick changes the walking rectangles, not body health.
    mZombieHeight = HEIGHT_FALLING;
    mZombiePhase = PHASE_ZOMBIE_NORMAL;
    StartWalkAnim(0);
    mCachedZombieRect.mWidth = 0;
    mShieldHealth = 0;
    mHasObject = false;
    mZombieRect = Sexy::Rect(36, 17, 42, 115);
    mZombieAttackRect = Sexy::Rect(20, 17, 50, 115);
    mShieldType = SHIELDTYPE_NONE;
    return;
}

// ==========================================================================
// Zombie::LoadReanim(ReanimationType)
// @001AE120  204 bytes
// ==========================================================================
void Zombie::LoadReanim(ReanimationType theReanimationType)
{
    Reanimation *aReanim = mApp->AddReanimation(0.0f, 0.0f, 0, theReanimationType);
    mBodyReanimID = mApp->ReanimationGetID(aReanim);
    aReanim->mIsAttachment = true;
    aReanim->mLoopType = REANIM_LOOP;

    if (IsOnBoard())
    {
        StartWalkAnim(0);
        return;
    }

    // An off-board zombie idles instead of walking, and starts the idle cycle
    // at a random point.
    if ((int)Rand(4) > 0 && aReanim->TrackExistsById(ReanimTrackId_anim_idle2) != 0)
        PlayZombieReanim("anim_idle2", REANIM_LOOP, 0, RandRangeFloat(12.0f, 24.0f));
    else if (aReanim->TrackExistsById(ReanimTrackId_anim_idle) != 0)
        PlayZombieReanim("anim_idle", REANIM_LOOP, 0, RandRangeFloat(12.0f, 18.0f));

    aReanim->mAnimTime = Rand(0.99f);
    return;
}

// ==========================================================================
// Zombie::UpdateZombieImp(void)
// @001AE200  178 bytes
// ==========================================================================
float Zombie::UpdateZombieImp()
{
    if (mZombiePhase == PHASE_IMP_GETTING_THROWN)
    {
        mVelZ -= 0.05f;
        mPosX -= mVelX;
        mAltitude += mVelZ;

        // The thrown imp is pulled back onto its own row as it falls.
        float aRowY = GetPosYBasedOnRow(mRow);
        float aPosY = mPosY;
        mPosY = (aRowY - aPosY) + aPosY;
        mAltitude = (aRowY - aPosY) + mAltitude;
        if (mAltitude <= 0.0f)
        {
            mAltitude = 0.0f;
            mZombiePhase = PHASE_IMP_LANDING;
            PlayZombieReanim("anim_land", REANIM_PLAY_ONCE_AND_HOLD, 0, 24.0f);
            return mAltitude;
        }
    }
    else if (mZombiePhase == PHASE_IMP_LANDING)
    {
        Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
        if (aBodyReanim->mLoopCount > 0)
        {
            mZombiePhase = PHASE_ZOMBIE_NORMAL;
            StartWalkAnim(0);
            return mAltitude;
        }
    }
    return mAltitude;
}

// ==========================================================================
// Zombie::DetachShield(void)
// @001AE2BC  142 bytes
// ==========================================================================
Zombie * Zombie::DetachShield()
{
    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr)
    {
        mShieldType = SHIELDTYPE_NONE;
        mShieldHealth = 0;
        return nullptr;
    }

    switch (mShieldType)
    {
        case SHIELDTYPE_DOOR:
        case SHIELDTYPE_TRASHCAN:
            ShowDoorArms(false);
            break;
        case SHIELDTYPE_NEWSPAPER:
            ReanimShowPrefix("Zombie_paper_hands", 0);
            break;
        case SHIELDTYPE_LADDER:
            ReanimShowPrefix("Zombie_outerarm", 0);
            mZombiePhase = PHASE_ZOMBIE_NORMAL;
            if (mIsEating)
                PlayZombieReanim("anim_eat", REANIM_LOOP, 20, 0.0f);
            else
                StartWalkAnim(0);
            break;
        default:
            break;
    }

    mShieldType = SHIELDTYPE_NONE;
    mShieldHealth = 0;
    return this;
}

// ==========================================================================
// Zombie::BungeeStealTarget(void)
// @001AE358  92 bytes
// ==========================================================================
void Zombie::BungeeStealTarget()
{
    PlayZombieReanim("anim_grab", REANIM_PLAY_ONCE_AND_HOLD, 20, 24.0f);

    Plant *aPlant = mBoard->GetTopPlantAt(mTargetCol, mRow, TOPPLANT_PUMPKIN_ORDER);
    if (aPlant == nullptr)
        return;
    if (aPlant->NotOnGround() || aPlant->mSeedType == SEED_COBCANNON)
        return;

    // The bungee marks the plant as being carried off and takes its slot id.
    mTargetPlantID = static_cast<PlantID>(mBoard->mPlants.DataArrayGetID(aPlant));
    aPlant->mOnBungeeState = GETTING_GRABBED_BY_BUNGEE;
    mRenderOrder = Board::MakeRenderOrder(RENDER_LAYER_PROJECTILE, mRow, 0);
}

// ==========================================================================
// Zombie::BungeeLiftTarget(void)
// @001AE3B8  182 bytes
// ==========================================================================
void Zombie::BungeeLiftTarget()
{
    PlayZombieReanim("anim_raise", REANIM_PLAY_ONCE_AND_HOLD, 0, 36.0f);
    Plant *aPlant = mBoard->mPlants.DataArrayTryToGet(mTargetPlantID);
    if (aPlant == nullptr)
        return;
    aPlant->mOnBungeeState = RISING_WITH_BUNGEE;
    mApp->PlayFoley(FOLEY_FLOOP);
    Reanimation *aPlantReanim = mApp->ReanimationTryToGet(aPlant->mBodyReanimID);
    if (aPlantReanim != nullptr)
        aPlantReanim->SetAnimRate(0.1f);

    // Keep the pumpkin supported when its cattail is carried away.
    if (aPlant->mSeedType == SEED_CATTAIL
        && mBoard->GetTopPlantAt(mTargetCol, mRow, TOPPLANT_ONLY_PUMPKIN) != nullptr)
    {
        mBoard->NewPlant(mTargetCol, mRow, SEED_LILYPAD, SEED_NONE, -1);
    }

    if (mApp->IsIZombieLevel())
    {
        mBoard->mChallenge->IZombiePlantDropRemainingSun(aPlant);
    }
}

// ==========================================================================
// Zombie::BungeeLanding(void)
// @001AE474  330 bytes
// ==========================================================================
void Zombie::BungeeLanding()
{
    if (mZombiePhase == PHASE_BUNGEE_DIVING && mAltitude < 1500.0f && !mApp->IsFinalBossLevel())
    {
        mApp->PlayFoley(FOLEY_BUNGEE_SCREAM);
        mZombiePhase = PHASE_BUNGEE_DIVING_SCREAMING;
    }

    if (mAltitude > 40.0f)
        return;

    Plant *aPlant = mBoard->FindUmbrellaPlant(mTargetCol, mRow);
    if (aPlant != nullptr)
    {
        // The umbrella bounces the bungee back up. PlaySample(int,bool) hides
        // the one-argument base overload, so the loop flag is spelled out.
        mApp->PlaySample(SOUND_BOING, false);
        mApp->PlayFoley(FOLEY_UMBRELLA);
        aPlant->DoSpecial();
        mZombiePhase = PHASE_BUNGEE_RISING;
        mRenderOrder = Board::MakeRenderOrder((RenderLayer)400000, 0, 1);
        mHitUmbrella = true;
        return;
    }

    mBoard->GetTopPlantAt(mTargetCol, mRow, (PlantPriority)2);
    if (mAltitude > 0.0f)
        return;

    mAltitude = 0.0f;

    // A bungee carrying a zombie drops it and leaves; an empty one grabs.
    Zombie *aZombie = mBoard->ZombieTryToGet(mRelatedZombieID);
    if (aZombie != nullptr)
    {
        aZombie->mZombieHeight = HEIGHT_ZOMBIE_NORMAL;
        aZombie->StartWalkAnim(0);
        mZombiePhase = PHASE_BUNGEE_RISING;
        mRelatedZombieID = ZOMBIEID_NULL;
        PlayZombieReanim("anim_raise", REANIM_PLAY_ONCE_AND_HOLD, 0, 36.0f);
        return;
    }

    mZombiePhase = PHASE_BUNGEE_AT_BOTTOM;
    mPhaseCounter = 300;
    PlayZombieReanim("anim_idle", REANIM_LOOP, 5, 24.0f);
    mApp->ReanimationGet(mBodyReanimID)->mAnimTime = 0.5f;
}

// ==========================================================================
// Zombie::ZombiquariumFindClosestBrain(void)
// @001AE5D8  388 bytes
// ==========================================================================
bool Zombie::ZombiquariumFindClosestBrain()
{
    if (mBoard->HasLevelAwardDropped() || mBodyHealth > 150)
        return false;

    GridItem *aClosest = nullptr;
    float aClosestDistance = 0.0f;
    GridItem *aGridItem = nullptr;
    while (mBoard->IterateGridItems(aGridItem))
    {
        // Give a newly dropped brain 15 ticks before it can be eaten.
        if (aGridItem->mGridItemType != GRIDITEM_BRAIN || aGridItem->mGridItemCounter <= 14)
            continue;

        float aDistance = sqrtf(((mPosX + 35.0f) - aGridItem->mPosX) * ((mPosX + 35.0f) - aGridItem->mPosX)
                                + (mPosY + 25.0f - aGridItem->mPosY) * (mPosY + 25.0f - aGridItem->mPosY));
        if (aClosest == nullptr || aClosestDistance > aDistance)
        {
            aClosest = aGridItem;
            aClosestDistance = aDistance;
        }
    }

    if (aClosest == nullptr)
        return false;

    if (aClosestDistance < 50.0f)
    {
        aClosest->GridItemDie();
        mApp->PlayFoley(FOLEY_SLURP);
        int aFedHealth = mBodyHealth + 200;
        mBodyHealth = aFedHealth < mBodyMaxHealth ? aFedHealth : mBodyMaxHealth;
        PlayZombieReanim("anim_aquarium_bite", REANIM_PLAY_ONCE_AND_HOLD, 10, 24.0f);
        mZombiePhase = PHASE_ZOMBIQUARIUM_BITE;
        mPhaseCounter = 200;
        return false;
    }

    float aHeading = atan2f(aClosest->mPosY - 25.0f - mPosY,
                           aClosest->mPosX - 35.0f - mPosX);
    if (aHeading < 0.0f)
        aHeading += 6.2832f;
    mVelZ = aHeading;
    mZombiePhase = PHASE_ZOMBIQUARIUM_ACCEL;
    return true;
}

// ==========================================================================
// Zombie::UpdateZombiePolevaulter(void)
// @001AE774  624 bytes
// ==========================================================================
float Zombie::UpdateZombiePolevaulter()
{
    if (mZombiePhase == PHASE_POLEVAULTER_IN_VAULT)
    {
        Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
        float aAnimTime = aBodyReanim->mAnimTime;
        bool aLanded = false;

        // The vault lands on the first plant it passes over between 0.6 and
        // 0.7 of the animation.
        if (aAnimTime > 0.6f && aAnimTime <= 0.7f)
        {
            Plant *aTarget = FindPlantTarget((ZombieAttackType)2);
            if (aTarget != nullptr && aTarget->mSeedType == SEED_TALLNUT)
            {
                mApp->PlayFoley(FOLEY_BONK);
                aLanded = true;
                mApp->AddTodParticle((float)(aTarget->mX + 60),
                                     (float)(aTarget->mY - 20),
                                     mRenderOrder + 1,
                                     (ParticleEffect)30);
                int aTargetX = aTarget->mX;
                float aPosY = mPosY;
                mZombieHeight = HEIGHT_FALLING;
                mPosX = (float)aTargetX;
                mPosY = aPosY - 30.0f;
            }
        }

        // The vault always ends with the zombie 150 pixels further left.
        if (aBodyReanim->mLoopCount > 0)
        {
            aLanded = true;
            mPosX = mPosX - 150.0f;
        }

        if (aBodyReanim->ShouldTriggerTimedEvent(0.2f))
            mApp->PlayFoley(FOLEY_GRASSSTEP);
        if (aBodyReanim->ShouldTriggerTimedEvent(0.4f))
            mApp->PlayFoley(FOLEY_POLEVAULT);

        if (!aLanded)
        {
            // Still in the air: the zombie slides along at the animation's own
            // progress times 150, and rides the row's own line.
            float aStartX = mPosX;
            float aRowY = GetPosYBasedOnRow(mRow);
            mPosX = aStartX - (aBodyReanim->mAnimTime * 150.0f);
            mPosX = aStartX;
            mPosY = aRowY;
            return aRowY;
        }

        float aPosX = mPosX;
        mZombiePhase = PHASE_POLEVAULTER_POST_VAULT;
        mZombieAttackRect = Sexy::Rect(50, 0, 20, 115);
        mX = (int)aPosX;
        StartWalkAnim(0);
        return mPosY;
    }

    if (mZombiePhase != PHASE_POLEVAULTER_PRE_VAULT)
        return mPosY;

    if (!mHasHead || mZombieHeight != HEIGHT_ZOMBIE_NORMAL)
        return mPosY;

    Plant *aTarget = FindPlantTarget((ZombieAttackType)2);
    if (aTarget != nullptr)
    {
        // A ladder in the way stops the vault: the zombie walks to the ladder
        // column instead.
        if (mBoard->GetLadderAt(aTarget->mPlantCol, aTarget->mRow) != nullptr)
        {
            int aLadderX = mBoard->GridToPixelX(aTarget->mPlantCol, aTarget->mRow) + 40;
            if ((float)aLadderX > mPosX && mZombieHeight == HEIGHT_ZOMBIE_NORMAL)
            {
                int aCol = aTarget->mPlantCol;
                if (mUseLadderCol != aCol)
                {
                    mUseLadderCol = aCol;
                    mZombieHeight = HEIGHT_UP_LADDER;
                }
            }
            return mPosY;
        }

        mZombiePhase = PHASE_POLEVAULTER_IN_VAULT;
        PlayZombieReanim("anim_jump", REANIM_PLAY_ONCE_AND_HOLD, 20, 24.0f);

        // The horizontal speed is the plant's distance over the animation's
        // own duration in frames.
        Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
        int aTargetX = aTarget->mX;
        int aStartX = mX;
        float aFrames = ((float)aBodyReanim->mFrameCount / aBodyReanim->mAnimRate) * 100.0f;
        float aDistance;
        if (mApp->IsWallnutBowlingLevel())
            aDistance = 0.0f;
        else
            aDistance = (float)(aStartX - aTargetX - 80);

        mHasObject = false;
        mVelX = aDistance / aFrames;
    }

    if (mApp->IsIZombieLevel())
    {
        if (mBoard->mChallenge->IZombieGetBrainTarget(this) != nullptr)
        {
            mZombiePhase = PHASE_POLEVAULTER_POST_VAULT;
            StartWalkAnim(0);
            return mPosY;
        }
    }

    return mPosY;
}

// ==========================================================================
// Zombie::UpdateZombieDolphinRider(void)
// @001AE9FC  956 bytes
// ==========================================================================
void Zombie::UpdateZombieDolphinRider()
{
    // A dolphin rider caught by tangle kelp is not riding any more.
    if (IsTangleKelpTarget())
        return;

    int aWalkingBackwards = IsWalkingBackwards();
    switch (mZombiePhase)
    {
        case PHASE_DOLPHIN_WALKING:
            // At the pool edge the rider dives in.
            if (!aWalkingBackwards && (unsigned int)(mX - 701) <= 0x13)
            {
                mZombiePhase = PHASE_DOLPHIN_INTO_POOL;
                PlayZombieReanim("anim_jumpinpool", REANIM_PLAY_ONCE_AND_HOLD, 20, 16.0f);
                return;
            }
            break;
        case PHASE_DOLPHIN_INTO_POOL:
        {
            Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
            if (aBodyReanim->ShouldTriggerTimedEvent(0.56f))
            {
                // The splash is a reanimation and a particle, both just ahead
                // of the zombie.
                Reanimation *aSplash = mApp->AddReanimation((float)(mX - 83),
                                                                           (float)(mY + 73),
                                                                           mRenderOrder + 1,
                                                                           REANIM_SPLASH);
                aSplash->OverrideScale(1.2f, 0.8f);
                mApp->AddTodParticle((float)(mX - 46),
                                     (float)(mY + 115),
                                     mRenderOrder + 1,
                                     (ParticleEffect)23);
                mApp->PlayFoley(FOLEY_ZOMBIE_ENTERING_WATER);
            }

            if (aBodyReanim->mLoopCount > 0)
            {
                float aPosX = mPosX;
                mZombiePhase = PHASE_DOLPHIN_RIDING;
                mZombieAttackRect = Sexy::Rect(-29, 0, 70, 115);
                mInPool = true;
                mPosX = aPosX - 70.0f;
                PlayZombieReanim("anim_ride", REANIM_LOOP_FULL_LAST_FRAME, 0, 12.0f);
                return;
            }
            break;
        }
        case PHASE_DOLPHIN_RIDING:
            // The rider slides to the left edge of the pool and then walks.
            if (mX <= 10)
            {
                mZombieHeight = HEIGHT_OUT_OF_POOL;
                mZombiePhase = PHASE_DOLPHIN_WALKING_IN_POOL;
                mAltitude = -25.0f;
                PoolSplash(false);
                PlayZombieReanim("anim_walkdolphin", REANIM_LOOP, 0, 0.0f);
                PickRandomSpeed();
                return;
            }
            if (mHasHead)
            {
                if (!IsTanglekelpTarget() && FindPlantTarget((ZombieAttackType)2) != nullptr)
                {
                    mApp->PlayFoley(FOLEY_DOLPHIN_BEFORE_JUMPING);
                    mApp->PlayFoley(FOLEY_PLANT_WATER);
                    mVelZ = 0.5f;
                    mPhaseCounter = 120;
                    mZombiePhase = PHASE_DOLPHIN_IN_JUMP;
                    PlayZombieReanim("anim_dolphinjump", REANIM_PLAY_ONCE_AND_HOLD, 0, 10.0f);
                    return;
                }
            }
            break;
        case PHASE_DOLPHIN_IN_JUMP:
        {
            Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
            mAltitude = TodAnimateCurveFloat(120, 0, mPhaseCounter, 0.0f, 5.0f, CURVE_LINEAR);

            if (aBodyReanim->ShouldTriggerTimedEvent(0.3f))
            {
                Plant *aTarget = FindPlantTarget((ZombieAttackType)2);
                if (aTarget == nullptr || aTarget->mSeedType != SEED_TALLNUT)
                    return;

                mApp->PlayFoley(FOLEY_BONK);
                mApp->AddTodParticle((float)(aTarget->mX + 60),
                                     (float)(aTarget->mY - 20),
                                     mRenderOrder + 1,
                                     (ParticleEffect)30);
                int aTargetX = aTarget->mX;
                mZombieHeight = HEIGHT_FALLING;
                mAltitude = 30.0f;
                mPosX = (float)aTargetX + 25.0f;
                {
                    UpdateDolphinJumpLanding();
                    return;
                }
            }

            if (aBodyReanim->ShouldTriggerTimedEvent(0.49f))
            {
                Reanimation *aSplash = mApp->AddReanimation((float)(mX - 63),
                                                                           (float)(mY + 73),
                                                                           mRenderOrder + 1,
                                                                           REANIM_SPLASH);
                aSplash->OverrideScale(1.2f, 0.8f);
                mApp->AddTodParticle((float)(mX - 26),
                                     (float)(mY + 115),
                                     mRenderOrder + 1,
                                     (ParticleEffect)23);
                mApp->PlayFoley(FOLEY_ZOMBIE_ENTERING_WATER);
                mVelZ = 0.0f;
                return;
            }

            if (aBodyReanim->mLoopCount > 0)
            {
                float aPosX = mPosX;
                mAltitude = 0.0f;
                mPosX = aPosX - 94.0f;
                {
                    UpdateDolphinJumpLanding();
                    return;
                }
            }
            break;
        }
        case PHASE_DOLPHIN_WALKING_IN_POOL:
            // The rider keeps walking in the pool until it is out of the
            // water, then switches to the plain walk.
            if (mX > 10)
            {
                if (mX <= 680 || aWalkingBackwards)
                    return;
            }
            else if (aWalkingBackwards)
            {
                return;
            }
            mZombieHeight = HEIGHT_OUT_OF_POOL;
            mZombiePhase = PHASE_DOLPHIN_WALKING_WITHOUT_DOLPHIN;
            mAltitude = -25.0f;
            PoolSplash(false);
            PlayZombieReanim("anim_walk", REANIM_LOOP, 0, 0.0f);
            PickRandomSpeed();
            return;
        default:
            return;
    }
    return;
}

// The landing half of the dolphin jump: the rider loses the dolphin and its
// rectangle shrinks to a walking zombie's.
void Zombie::UpdateDolphinJumpLanding()
{
    mZombiePhase = PHASE_DOLPHIN_WALKING_WITHOUT_DOLPHIN;
    mZombieAttackRect = Sexy::Rect(30, 0, 30, 115);
    mZombieRect = Sexy::Rect(20, 0, 42, 115);
    mCachedZombieRect.mWidth = 0;
    mX = (int)mPosX;
    {
        StartWalkAnim(0);
        return;
    }
}

// ==========================================================================
// Zombie::StopEating(void)
// @001AEDD4  82 bytes
// ==========================================================================
Zombie * Zombie::StopEating()
{
    if (!mIsEating)
        return this;

    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    mIsEating = false;
    if (mZombiePhase == PHASE_NEWSPAPER_MADDENING)
        return this;

    if (aBodyReanim != nullptr && mZombieType != ZOMBIE_SNORKEL)
        StartWalkAnim(20);

    if (mShieldType == SHIELDTYPE_DOOR || mShieldType == SHIELDTYPE_TRASHCAN)
        ShowDoorArms(true);

    // 0x1AEDD4 tail-calls UpdateAnimSpeed. That function returns an int the
    // caller never reads; this function's own value is the zombie.
    UpdateAnimSpeed();
    return this;
}

// ==========================================================================
// Zombie::UpdateYuckyFace(void)
// @001AEE28  368 bytes
// ==========================================================================
void Zombie::UpdateYuckyFace()
{
    ++mYuckyFaceCounter;

    if (mYuckyFaceCounter > 20 && mYuckyFaceCounter < 170 && !HasYuckyFaceImage())
    {
        StopEating();
        mYuckyFaceCounter = 170;
        if ((mBoard->CountZombiesOnScreen() <= 5 && mHasHead)
            || (mBoard->CountZombiesOnScreen() <= 10 && mHasHead && Rand(2) == 0))
        {
            mApp->PlayFoley(FOLEY_YUCK);
        }
    }

    if (mYuckyFaceCounter > 270)
    {
        ShowYuckyFace(false);
        mYuckyFace = false;
        mYuckyFaceCounter = 0;
        return;
    }

    if (mYuckyFaceCounter == 70)
    {
        StopEating();
        ShowYuckyFace(true);
        if ((mBoard->CountZombiesOnScreen() <= 5 && mHasHead)
            || (mBoard->CountZombiesOnScreen() <= 10 && mHasHead && Rand(2) == 0))
        {
            mApp->PlayFoley(FOLEY_YUCK);
        }
    }

    if (mYuckyFaceCounter != 170)
        return;

    StartWalkAnim(20);

    // TV 0x1AEE28 only crosses into an adjacent row of the same terrain type.
    bool aIsPool = mBoard->mPlantRow[mRow] == PLANTROW_POOL;
    bool aCanStepUp = mBoard->RowCanHaveZombies(mRow - 1)
                  && (mBoard->mPlantRow[mRow - 1] == PLANTROW_POOL) == aIsPool;
    bool aCanStepDown = mBoard->RowCanHaveZombies(mRow + 1)
                    && (mBoard->mPlantRow[mRow + 1] == PLANTROW_POOL) == aIsPool;

    if (aCanStepUp && aCanStepDown)
        SetRow(Rand(2) == 0 ? mRow + 1 : mRow - 1);
    else if (aCanStepUp)
        SetRow(mRow - 1);
    else if (aCanStepDown)
        SetRow(mRow + 1);
}

// ==========================================================================
// Zombie::DragUnder(void)
// @001AEF98  22 bytes
// ==========================================================================
int Zombie::DragUnder()
{
    mZombieHeight = HEIGHT_DRAGGED_UNDER;
    StopEating();
    return ReanimReenableClipping();
}

// ==========================================================================
// Zombie::DropShield(unsigned int)
// @001AEFB0  336 bytes
// ==========================================================================
void Zombie::DropShield(unsigned int theDamageFlags)
{
    if (mShieldType == SHIELDTYPE_NONE)
        return;

    ZombieDrawPosition aPos;
    GetDrawPos(aPos);

    // The shield falls where it was, and the particle it throws depends on
    // which shield it was. The paper throws nothing when the damage does not
    // leave the body.
    TodParticleSystem *aParticle = nullptr;
    float aPosX = 0.0f;
    float aPosY = 0.0f;

    switch (mShieldType)
    {
        case SHIELDTYPE_DOOR:
        case SHIELDTYPE_TRASHCAN:
            DetachShield();
            if ((theDamageFlags & 0x10) == 0)
            {
                GetTrackPosition("anim_screendoor", aPosX, aPosY);
                aParticle = (TodParticleSystem *)mApp->AddTodParticle(aPosX,
                                                                      aPosY,
                                                                      mRenderOrder + 1,
                                                                      mShieldType == SHIELDTYPE_DOOR ? (ParticleEffect)12 : (ParticleEffect)13);
            }
            break;
        case SHIELDTYPE_NEWSPAPER:
            StopEating();
            if (mYuckyFace)
            {
                ShowYuckyFace(false);
                mYuckyFace = false;
                mYuckyFaceCounter = 0;
            }

            mZombiePhase = PHASE_NEWSPAPER_MADDENING;
            PlayZombieReanim("anim_gasp", REANIM_PLAY_ONCE_AND_HOLD, 10, 8.0f);
            DetachShield();
            if ((theDamageFlags & 0x10) == 0)
            {
                GetTrackPosition("Zombie_paper_paper", aPosX, aPosY);
                aParticle = (TodParticleSystem *)mApp->AddTodParticle(aPosX, aPosY, mRenderOrder + 1, (ParticleEffect)14);
            }

            // The torn paper itself is an attached reanimation.
            if ((theDamageFlags & 0x11) == 0)
            {
                mApp->PlayFoley(FOLEY_NEWSPAPER_RIP);
                AddAttachedReanim(-11, 0, REANIM_ZOMBIE_SURPRISE);
            }
            break;
        case SHIELDTYPE_LADDER:
            DetachShield();
            if ((theDamageFlags & 0x10) == 0)
                aParticle = (TodParticleSystem *)mApp->AddTodParticle(mPosX + 31.0f, mPosY + 80.0f, mRenderOrder + 1, (ParticleEffect)55);
            break;
        default:
            break;
    }

    OverrideParticleScale(aParticle);
    mShieldType = SHIELDTYPE_NONE;
    return;
}

// ==========================================================================
// Zombie::TakeShieldDamage(int,unsigned int)
// @001AF114  318 bytes
// ==========================================================================
int Zombie::TakeShieldDamage(int theDamage, unsigned int theDamageFlags)
{
    // A hit that leaves the body alone still stops the zombie for a moment
    // and shakes the shield.
    if ((theDamageFlags & 8) == 0)
    {
        if (mJustGotShotCounter < 0)
            mJustGotShotCounter = 0;
        mShieldJustGotShotCounter = 25;
    }

    if ((theDamageFlags & 0xA) == 0)
    {
        mShieldRecoilCounter = 12;
        if (mShieldType == SHIELDTYPE_DOOR
            || mShieldType == SHIELDTYPE_LADDER
            || mShieldType == SHIELDTYPE_TRASHCAN)
        {
            mApp->PlayFoley(FOLEY_SHIELD_HIT);
        }
    }

    int aOldDamageIndex = GetShieldDamageIndex();
    int aAbsorbed = mShieldHealth >= theDamage ? theDamage : mShieldHealth;
    int aRemaining = theDamage - aAbsorbed;
    mShieldHealth -= aAbsorbed;

    if (mShieldHealth == 0)
    {
        // The shield is gone: it falls off and the rest of the damage goes on.
        DropShield(theDamageFlags);
        return aRemaining;
    }

    // The shield took the hit but is still on: redraw it at its new damage.
    int aNewDamageIndex = GetShieldDamageIndex();
    if (aOldDamageIndex != aNewDamageIndex)
    {
        Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
        switch (mShieldType)
        {
            case SHIELDTYPE_DOOR:
                if (aNewDamageIndex == 1)
                    aBodyReanim->SetImageOverride("anim_screendoor", IMAGE_REANIM_ZOMBIE_SCREENDOOR2);
                else if (aNewDamageIndex == 2)
                    aBodyReanim->SetImageOverride("anim_screendoor", IMAGE_REANIM_ZOMBIE_SCREENDOOR3);
                break;
            case SHIELDTYPE_TRASHCAN:
                if (aNewDamageIndex == 1)
                    aBodyReanim->SetImageOverride("anim_screendoor", IMAGE_REANIM_ZOMBIE_TRASHCAN2);
                else if (aNewDamageIndex == 2)
                    aBodyReanim->SetImageOverride("anim_screendoor", IMAGE_REANIM_ZOMBIE_TRASHCAN3);
                break;
            case SHIELDTYPE_NEWSPAPER:
                if (aNewDamageIndex == 1)
                    aBodyReanim->SetImageOverride("Zombie_paper_paper", IMAGE_REANIM_ZOMBIE_PAPER_PAPER2);
                else if (aNewDamageIndex == 2)
                    aBodyReanim->SetImageOverride("Zombie_paper_paper", IMAGE_REANIM_ZOMBIE_PAPER_PAPER3);
                break;
            case SHIELDTYPE_LADDER:
                if (aNewDamageIndex == 1)
                    aBodyReanim->SetImageOverride("Zombie_ladder_1", IMAGE_REANIM_ZOMBIE_LADDER_1_DAMAGE1);
                else if (aNewDamageIndex == 2)
                    aBodyReanim->SetImageOverride("Zombie_ladder_1", IMAGE_REANIM_ZOMBIE_LADDER_1_DAMAGE2);
                break;
            default:
                break;
        }
    }

    return aRemaining;
}

// ==========================================================================
// Zombie::EatPlant(Plant *)
// @001AF298  498 bytes
// ==========================================================================
void Zombie::EatPlant(Plant * thePlant)
{
    // A dancer that is raising its arms is not eating yet.
    if (mZombiePhase == PHASE_DANCER_DANCING_IN)
    {
        mPhaseCounter = 1;
        return;
    }

    if (mYuckyFace)
        return;

    // A ladder in front of the plant stops the meal: the zombie walks to the
    // ladder column instead, unless it is a digger.
    if (mBoard->GetLadderAt(thePlant->mPlantCol, thePlant->mRow) != nullptr
        && mZombieType != ZOMBIE_DIGGER)
    {
        StopEating();
        if (mZombieHeight == HEIGHT_ZOMBIE_NORMAL)
        {
            int aCol = thePlant->mPlantCol;
            if (mUseLadderCol != aCol)
            {
                mUseLadderCol = aCol;
                mZombieHeight = HEIGHT_UP_LADDER;
            }
        }
        return;
    }

    StartEating();

    // A plant that is about to go off -- a cherry bomb, a jalapeno, an
    // ice-shroom, a doom-shroom, an armed potato mine or a squashed squash --
    // is not chewed: the zombie dies with it. The tests are on mSeedType for
    // the bombs and on mState for the armed plants.
    PlantState aState = thePlant->mState;
    SeedType aSeedType = thePlant->mSeedType;
    bool aExplosive = aSeedType == SEED_CHERRYBOMB
                   || aSeedType == SEED_JALAPENO
                   || (unsigned int)(aSeedType - SEED_ICESHROOM) <= 1
                   || aSeedType == SEED_HYPNOSHROOM
                   || (unsigned int)(aState - STATE_FLOWERPOT_INVULNERABLE) <= 1
                   || (unsigned int)(aState - STATE_SQUASH_LOOK) <= 1;

    if (!aExplosive || thePlant->mGloveGrabbed)
    {
        // An armed potato mine goes off; a blover blows; an ice-shroom that is
        // not being held freezes.
        if (aSeedType == SEED_POTATOMINE)
        {
            if (aState != STATE_NOTREADY)
                return;
        }
        else if (aSeedType == SEED_BLOVER
                 || (aSeedType == SEED_ICESHROOM && !thePlant->mGloveGrabbed))
        {
            thePlant->DoSpecial();
            return;
        }

        // A chilled zombie does not take a bite every other frame.
        if (mChilledCounter <= 0 || mZombieAge % 2 != 1)
        {
            // A zombie eating a wall-nut in I, Zombie spits out a sun.
            if (mApp->IsIZombieLevel() && thePlant->mState == STATE_READY)
            {
                int aHealth = thePlant->mPlantHealth;
                int aNewHealth = aHealth - 8;
                if (aHealth / 40 > aNewHealth / 40 || aHealth <= 8)
                {
                    mBoard->AddCoin(thePlant->mX, thePlant->mY, COIN_SUN, CoinMotion(2));
                }
                else
                {
                    aNewHealth = thePlant->mPlantHealth - 8;
                }

                thePlant->mPlantHealth = aNewHealth;
                thePlant->mRecentlyEatenCountdown = 50;
            }
            else
            {
                thePlant->mPlantHealth = thePlant->mPlantHealth - 8;
                thePlant->mRecentlyEatenCountdown = 50;
            }

            // A hypnotised zombie eats a wall-nut, a tall-nut or a pumpkin
            // twice as fast.
            if (mApp->IsIZombieLevel() && mZombieAge < -500)
            {
                if (aSeedType == SEED_WALLNUT
                    || aSeedType == SEED_TALLNUT
                    || aSeedType == SEED_PUMPKINSHELL)
                {
                    thePlant->mPlantHealth -= 8;
                }
            }

            if (thePlant->mPlantHealth <= 0)
            {
                mApp->PlaySample(SOUND_GULP, true);
                thePlant->Die();
                mBoard->mChallenge->ZombieAtePlant(this, thePlant);

                // The first time the player loses a peashooter in the opening
                // levels, the game says so.
                if ((unsigned int)(mBoard->mTutorialState - TUTORIAL_LEVEL_1_PLANT_PEASHOOTER) <= 2
                    && mApp->IsFirstTimeAdventureMode()
                    && thePlant->mPlantCol > 4)
                {
                    if (mBoard->mTutorialTimer <= 14 && aSeedType == SEED_PEASHOOTER)
                    {
                        Sexy::String aAdvice;
                        TodStringTranslate(&aAdvice, "[ADVICE_PEASHOOTER_DIED]");
                        mBoard->DisplayAdvice(aAdvice, MESSAGE_STYLE_HINT_TALL_FAST, (AdviceType)ADVICE_PEASHOOTER_DIED);
                    }
                }
            }
        }
    }
}

// ==========================================================================
// Zombie::RemoveIceTrap(void)
// @001AF4A8  40 bytes
// ==========================================================================
void Zombie::RemoveIceTrap()
{
    mIceTrapCounter = 0;
    if (mZombieType == ZOMBIE_BALLOON)
        BalloonPropellerHatSpin(true);

    UpdateAnimSpeed();
    {
        StartZombieSound();
        return;
    }
}

// ==========================================================================
// Zombie::RemoveButter(void)
// @001AF4D0  134 bytes
// ==========================================================================
void Zombie::RemoveButter()
{
    if (mZombieType == ZOMBIE_BALLOON)
        BalloonPropellerHatSpin(true);

    // A zombie with a pea head, a gatling head or one of the other special
    // heads has to have that head's own animation rate restored.
    if ((unsigned int)(mZombieType - 27) <= 5)
    {
        Reanimation *aHeadReanim = mApp->ReanimationTryToGet(mSpecialHeadReanimID);
        if (aHeadReanim != nullptr)
        {
            if (mZombieType == ZOMBIE_PEA_HEAD && aHeadReanim->IsAnimPlaying("anim_shooting"))
            {
                aHeadReanim->SetAnimRate(35.0f);
            }
            else if (mZombieType == ZOMBIE_GATLING_HEAD && aHeadReanim->IsAnimPlaying("anim_shooting"))
            {
                aHeadReanim->SetAnimRate(38.0f);
            }
            else
            {
                aHeadReanim->SetAnimRate(15.0f);
            }
        }
    }

    UpdateAnimSpeed();
    {
        StartZombieSound();
        return;
    }
}

// ==========================================================================
// Zombie::RemoveColdEffects(void)
// @001AF560  42 bytes
// ==========================================================================
int Zombie::RemoveColdEffects()
{
    if (mIceTrapCounter > 0)
        RemoveIceTrap();

    if (mChilledCounter > 0)
    {
        mChilledCounter = 0;
        UpdateAnimSpeed();
        return 0;
    }

    return 0;
}

// ==========================================================================
// Zombie::DropHead(unsigned int)
// @001AF58C  882 bytes
// ==========================================================================
Zombie * Zombie::DropHead(unsigned int theDamageFlags)
{
    if (!CanLoseBodyParts() || !mHasHead)
        return this;

    if (mYuckyFaceCounter > 0)
    {
        mYuckyFaceCounter = 0;
        UpdateAnimSpeed();
    }

    mHasHead = false;
    ReanimShowPrefix("anim_head", -1);
    ReanimShowPrefix("anim_hair", -1);
    ReanimShowPrefix("anim_tongue", -1);

    // A damage that does not leave the body behind keeps the head attached.
    if ((theDamageFlags & 0x10) != 0)
        return this;

    // A zombie with one of the add-on heads (pea, wall-nut, jalapeno, gatling,
    // squash, tall-nut) just loses that head reanimation.
    if ((unsigned int)(mZombieType - 27) <= 5)
    {
        Reanimation *aHeadReanim = mApp->ReanimationGet(mSpecialHeadReanimID);
        aHeadReanim->ReanimationDie();
        mSpecialHeadReanimID = (ReanimationID)(theDamageFlags & 0x10);
        // 0x1AF58C returns this. The head reanimation is already dead; the
        // pointer it left in r0 is not what the function hands back.
        return this;
    }

    // The head particle starts where the head was.
    int aRenderOrder = mRenderOrder;
    ZombieDrawPosition aPos;
    GetDrawPos(aPos);

    int aParticleOrder = aRenderOrder + 1;
    float aPosX = ((mPosX + aPos.mImageOffsetX) + 11.0f) + (float)aPos.mHeadX;
    float aPosY = ((((mPosY + aPos.mImageOffsetY) + 21.0f) + aPos.mBodyY) + (float)aPos.mHeadY);

    if (mBodyReanimID != 0)
        GetTrackPosition("anim_head1", aPosX, aPosY);

    // Which head particle: a burned or a zombiquarium zombie has its own.
    int aEffect;
    if (mZombiePhase == PHASE_ZOMBIE_BURNED)
        aEffect = 73;
    else if (mInPool)
        aEffect = 75;
    else
        aEffect = 6;

    switch (mZombieType)
    {
        case ZOMBIE_DANCER:
            aParticleOrder = mRenderOrder - 1;
            break;
        case ZOMBIE_NEWSPAPER:
            aEffect = 18;
            break;
        case ZOMBIE_POGO:
            PogoBreak(theDamageFlags);
            aEffect = 62;
            break;
        case ZOMBIE_BALLOON:
            aEffect = 19;
            ReanimShowPrefix("anim_hat", -1);
            ReanimShowPrefix("hat", -1);
            break;
        case ZOMBIE_POLEVAULTER:
            DropPole();
            break;
        case ZOMBIE_FLAG:
            DropFlag();
            break;
        default:
            break;
    }

    TodParticleSystem *aHead = (TodParticleSystem *)mApp->AddTodParticle(aPosX, aPosY, aParticleOrder, (ParticleEffect)aEffect);
    OverrideParticleColor(aHead);
    OverrideParticleScale(aHead);

    if (aHead != nullptr)
    {
        // A few types draw the head from the particle's own image, so it is
        // cleared for them.
        switch (mZombieType)
        {
            case ZOMBIE_DANCER:
                ReanimShowPrefix("Zombie_disco_chops", -1);
                ReanimShowPrefix("Zombie_disco_glasses", -1);
                break;
            case ZOMBIE_BACKUP_DANCER:
                ReanimShowPrefix("Zombie_disco_chops", -1);
                ReanimShowPrefix("Zombie_backup_stash", -1);
                break;
            case ZOMBIE_BOBSLED:
            case ZOMBIE_LADDER:
            case ZOMBIE_IMP:
            case ZOMBIE_FOOTBALL:
            case ZOMBIE_POLEVAULTER:
            case ZOMBIE_SNORKEL:
            case ZOMBIE_DIGGER:
            case ZOMBIE_DOLPHIN_RIDER:
            case ZOMBIE_YETI:
                break;
            default:
                aHead->OverrideImage(nullptr, nullptr);
                break;
        }
    }

    // The three cosmetic modes each throw their own particle on top of the
    // head: the mustache, the sunglasses and the future (hat) mode.
    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);

    if (mBoard->mMustacheMode)
    {
        if (aBodyReanim->TrackExistsById(ReanimTrackId_zombie_mustache) != 0)
        {
            ReanimShowPrefix("Zombie_mustache", -1);
            TodParticleSystem *aMustache = (TodParticleSystem *)mApp->AddTodParticle(aPosX, aPosY, aParticleOrder, (ParticleEffect)95);
            OverrideParticleColor(aMustache);
            OverrideParticleScale(aMustache);
            if (aBodyReanim->GetImageOverride("Zombie_mustache") != 0 && aMustache != nullptr)
                aMustache->OverrideImage(nullptr, nullptr);
        }
    }

    if (mBoard->mSuperMowerMode)
    {
        Sexy::Image *aGlasses = aBodyReanim->GetImageOverride("anim_head1");
        if (aGlasses != 0)
        {
            int aFrame;
            if (aGlasses == IMAGE_REANIM_ZOMBIE_HEAD_SUNGLASSES1)
                aFrame = 0;
            else if (aGlasses == IMAGE_REANIM_ZOMBIE_HEAD_SUNGLASSES2)
                aFrame = 1;
            else if (aGlasses == IMAGE_REANIM_ZOMBIE_HEAD_SUNGLASSES3)
                aFrame = 2;
            else if (aGlasses == IMAGE_REANIM_ZOMBIE_HEAD_SUNGLASSES4)
                aFrame = 3;
            else
                aFrame = -1;

            if (aFrame >= 0)
            {
                TodParticleSystem *aGlassesParticle = (TodParticleSystem *)mApp->AddTodParticle(aPosX, aPosY, aParticleOrder, (ParticleEffect)96);
                OverrideParticleColor(aGlassesParticle);
                OverrideParticleScale(aGlassesParticle);
                if (aGlassesParticle != nullptr)
                    aGlassesParticle->OverrideFrame(nullptr, aFrame);
            }
        }
    }

    if (mBoard->mFutureMode && mZombiePhase != PHASE_ZOMBIE_BURNED)
    {
        TodParticleSystem *aHat = (TodParticleSystem *)mApp->AddTodParticle(aPosX, aPosY, aParticleOrder, (ParticleEffect)97);
        OverrideParticleScale(aHat);
    }

    mApp->PlayFoley(FOLEY_LIMBS_POP);
    return this;
}

// ==========================================================================
// Zombie::UpdateYeti(void)
// @001AF974  56 bytes
