void Zombie::UpdateYeti()
{
    // The yeti runs for the lawn edge as soon as it has lost its object and
    // still has its head.
    if (!mHasObject && mHasHead && !IsDeadOrDying() && mZombiePhase == PHASE_ZOMBIE_NORMAL && mPhaseCounter == 0)
    {
        mHasObject = false;
        mZombiePhase = PHASE_YETI_RUNNING;
        {
            PickRandomSpeed();
            return;
        }
    }

    return;
}

// ==========================================================================
// Zombie::StopZombieSound(void)
// @001AF9AC  170 bytes
// ==========================================================================
void Zombie::StopZombieSound()
{
    if (mZombieType == ZOMBIE_DANCER || mZombieType == ZOMBIE_BACKUP_DANCER)
    {
        bool aDancerStillPlaying = false;
        if (mApp->mBoard != nullptr)
        {
            Zombie *aZombie = nullptr;
            while (mApp->mBoard->IterateZombies(aZombie))
            {
                if (aZombie->mHasHead
                    && !aZombie->IsDeadOrDying()
                    && aZombie->IsOnBoard()
                    && (aZombie->mZombieType == ZOMBIE_DANCER
                        || aZombie->mZombieType == ZOMBIE_BACKUP_DANCER))
                {
                    aDancerStillPlaying = true;
                    break;
                }
            }
        }

        if (!aDancerStillPlaying)
            mApp->mSoundSystem->StopFoley(FOLEY_DANCER);
    }

    // Each jack-in-the-box or tunneling miner owns one shared loop reference.
    if (mPlayingSong)
    {
        mPlayingSong = false;
        if (mZombieType == ZOMBIE_JACK_IN_THE_BOX)
            mApp->mSoundSystem->StopFoley(FOLEY_JACKINTHEBOX);
        else if (mZombieType == ZOMBIE_DIGGER)
            mApp->mSoundSystem->StopFoley(FOLEY_DIGGER);
    }
}

// ==========================================================================
// Zombie::DiggerLoseAxe(void)
// @001AFA58  88 bytes
// ==========================================================================
void Zombie::DiggerLoseAxe()
{
    if (mZombiePhase == PHASE_DIGGER_TUNNELING)
    {
        mPhaseCounter = 200;
        mZombiePhase = PHASE_DIGGER_TUNNELING_PAUSE_WITHOUT_AXE;
        SetAnimRate(0.0f);
        UpdateAnimSpeed();
        AttachmentDetachCrossFadeParticleType(mAttachmentID, (ParticleEffect)33, nullptr);
        StopZombieSound();
    }

    mHasObject = false;
    ReanimShowTrack("Zombie_digger_pickaxe", -1);
    ReanimShowTrack("Zombie_digger_dirt", -1);
}

// ==========================================================================
// Zombie::UpdateZombieDigger(void)
// @001AFAB8  656 bytes
// ==========================================================================
// 0xC2F00000 is -120, not -80. The rise tails return SetAnimRate's r0; the
// stunned early-out returns the body reanim ReanimationGet left in r0.
void Zombie::UpdateZombieDigger()
{
    switch (mZombiePhase)
    {
        case PHASE_DIGGER_TUNNELING:
            if (mPosX >= 10.0f)
                return;

            mAltitude = -120.0f;
            mZombiePhase = PHASE_DIGGER_RISING;
            mPhaseCounter = 130;
            PlayZombieReanim("anim_drill", REANIM_LOOP, 0, 20.0f);
            mApp->PlayFoley(FOLEY_DIRT_RISE);
            mApp->PlayFoley(FOLEY_WAKEUP);
            AttachmentDetachCrossFadeParticleType(mAttachmentID, (ParticleEffect)33, nullptr);
            StopZombieSound();
            mApp->AddTodParticle(mPosX + 60.0f, mPosY + 118.0f, mRenderOrder + 1, (ParticleEffect)32);
            {
                mApp
                ->AddReanimation(mPosX + 13.0f, mPosY + 97.0f, mRenderOrder + 1, REANIM_DIGGER_DIRT)
                ->SetAnimRate(24.0f);
                return;
            }

        case PHASE_DIGGER_RISING:
        {
            int aCurve;
            if (mPhaseCounter > 40)
                aCurve = TodAnimateCurve(130, 40, mPhaseCounter, -120, 20, CURVE_EASE_OUT);
            else
                aCurve = TodAnimateCurve(30, 0, mPhaseCounter, 20, 0, CURVE_EASE_IN);
            mAltitude = (float)aCurve;

            if (mPhaseCounter == 30)
            {
                Reanimation *aLanding = PlayZombieReanim("anim_landing", REANIM_PLAY_ONCE_AND_HOLD, 0, 12.0f);
                if (mPhaseCounter != 0)
                    return;
            }
            else if (mPhaseCounter != 0)
            {
                return;
            }

            mZombiePhase = PHASE_DIGGER_STUNNED;
            mAltitude = 0.0f;
            {
                PlayZombieReanim("anim_dizzy", REANIM_LOOP, 10, 12.0f);
                return;
            }
        }

        case PHASE_DIGGER_TUNNELING_PAUSE_WITHOUT_AXE:
            if (mPhaseCounter == 150)
            {
                AddAttachedReanim(23, 93, REANIM_ZOMBIE_SURPRISE);
                if (mPhaseCounter != 0)
                    return;
            }
            else if (mPhaseCounter != 0)
            {
                return;
            }

            mZombiePhase = PHASE_DIGGER_RISE_WITHOUT_AXE;
            mAltitude = -120.0f;
            mPhaseCounter = 130;
            PlayZombieReanim("anim_landing", REANIM_PLAY_ONCE_AND_HOLD, 0, 0.0f);
            mApp->PlayFoley(FOLEY_DIRT_RISE);
            mApp->AddTodParticle(mPosX + 60.0f, mPosY + 118.0f, mRenderOrder + 1, (ParticleEffect)32);
            {
                mApp
                ->AddReanimation(mPosX + 13.0f, mPosY + 97.0f, mRenderOrder + 1, REANIM_DIGGER_DIRT)
                ->SetAnimRate(24.0f);
                return;
            }

        case PHASE_DIGGER_RISE_WITHOUT_AXE:
        {
            int aCurve;
            if (mPhaseCounter <= 40)
                aCurve = TodAnimateCurve(30, 0, mPhaseCounter, 20, 0, CURVE_EASE_IN);
            else
                aCurve = TodAnimateCurve(130, 40, mPhaseCounter, -120, 20, CURVE_EASE_OUT);
            mAltitude = (float)aCurve;

            if (mPhaseCounter == 30)
            {
                Reanimation *aLanding = PlayZombieReanim("anim_landing", REANIM_PLAY_ONCE_AND_HOLD, 20, 12.0f);
                if (mPhaseCounter != 0)
                    return;
            }
            else if (mPhaseCounter != 0)
            {
                return;
            }

            mZombiePhase = PHASE_DIGGER_WALKING_WITHOUT_AXE;
            mAltitude = 0.0f;
            {
                StartWalkAnim(20);
                return;
            }
        }

        case PHASE_DIGGER_STUNNED:
        {
            // mLoopCount > 1 only while the digger still has its axe.
            Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
            if (aBodyReanim->mLoopCount <= 1)
                return;
            mZombiePhase = PHASE_DIGGER_WALKING;
            {
                StartWalkAnim(20);
                return;
            }
        }

        default:
            break;
    }
    return;
}
