// ==========================================================================
// Zombie::BossBungeeLeave(void)
// @001B1B64  72 bytes
// ==========================================================================
Reanimation * Zombie::BossBungeeLeave()
{
  mZombiePhase = PHASE_BOSS_BUNGEES_LEAVE;

  // Walk this zombie's four follower ids and kill off any that are still alive.
  for ( int i = 0; i < 4; i++ )
  {
    Zombie *aFollower = mBoard->ZombieTryToGet(mFollowerZombieID[i]);
    if ( aFollower != nullptr && aFollower->mBodyHealth > 0 )
      aFollower->DieWithLoot();
  }

  return PlayZombieReanim("anim_bungee_1_leave", REANIM_PLAY_ONCE_AND_HOLD, 20, 18.0f);
}
// ==========================================================================
// Zombie::MowDown(void)
// @001B1BB0  512 bytes
// ==========================================================================
void Zombie::MowDown()
{
  // Already dead, already mowered, or the boss: nothing to do.
  if ( mDead )
    return;
  if ( mZombiePhase == PHASE_ZOMBIE_MOWERED )
    return;
  if ( mZombieType == ZOMBIE_BOSS )
    return;

  // The two vehicles explode instead of being run down.
  if ( mZombieType == ZOMBIE_CATAPULT || mZombieType == ZOMBIE_ZAMBONI )
  {
    ParticleEffect anEffect = (mZombieType == ZOMBIE_CATAPULT)
      ? (ParticleEffect)66 : (ParticleEffect)64;
    mApp->AddTodParticle(mPosX + 80.0f, mPosY + 60.0f, mRenderOrder + 1, anEffect);
    mApp->PlayFoley(FOLEY_EXPLOSION);
    {
        DieWithLoot();
        return;
    }
  }

  // Everything the mower passes through is destroyed outright, except the types
  // that leave a corpse: the dying/burned phases, the gargantuars, the vehicles,
  // the boss, the pole vaulter, the dolphin rider, the jack-in-the-box, the
  // flying zombies, and anything already in the pool.
  bool aLeavesCorpse =
    ((mZombiePhase & ~2u) == PHASE_ZOMBIE_DYING)
    || ((mZombiePhase - 1) <= 1)
    || ((mZombiePhase & ~8u) == 50)
    || ((unsigned int)(mZombieType - 23) <= 1)
    || mZombieType == ZOMBIE_REDEYE_GARGANTUAR
    || mZombieType == ZOMBIE_POLEVAULTER
    || ((unsigned int)(mZombieType - 19) <= 1)
    || mZombieType == ZOMBIE_ZAMBONI;

  if ( aLeavesCorpse || IsBobsledTeamWithSled() || IsFlying() || mInPool )
  {
    // The puff of smoke, then the head and limbs come off.
    Reanimation *aPuff = mApp->AddReanimation(mPosX - 73.0f, mPosY - 56.0f,
                                              mRenderOrder + 2, REANIM_PUFF);
    aPuff->SetFramesForLayer("anim_puff");
    mApp->AddTodParticle(mPosX + 110.0f, (float)mPosY, mRenderOrder + 1, (ParticleEffect)67);

    // The graveyard levels keep the body parts attached. 2 is the grave square
    // in the binary's GridSquareType; this tree's enum stops at HIGH_GROUND.
    if ( mBoard->mGridSquareType[mRow][mTargetCol] != (GridSquareType)2 )
    {
      DropHead(0);
      DropArm(0);
      DropHelm(0);
      DropShield(0);
    }
    {
        DieWithLoot();
        return;
    }
  }

  if ( mIceTrapCounter > 0 )
    RemoveIceTrap();
  if ( mButteredCounter > 0 )
    mButteredCounter = 0;

  DropShield(0);
  DropHelm(0);

  // The carried item goes first, then the head for the types that have one.
  if ( mZombieType == ZOMBIE_FLAG )
    DropFlag();
  else if ( mZombieType == ZOMBIE_POLEVAULTER )
    DropPole();
  else if ( mZombieType == ZOMBIE_NEWSPAPER || mZombieType == ZOMBIE_DANCER )
    DropHead(0);
  else if ( mZombieType == ZOMBIE_POGO )
  {
    DropHead(0);
    mAltitude = 0.0f;
  }

  // The mowered body reanimation, then the phase that owns it.
  Reanimation *aMowered = mApp->AddReanimation(0.0f, 0.0f, mRenderOrder, REANIM_LAWN_MOWERED_ZOMBIE);
  aMowered->mIsAttachment = false;
  aMowered->mLoopType = REANIM_PLAY_ONCE_AND_HOLD;
  aMowered->SetAnimRate(8.0f);
  mMoweredReanimID = mApp->ReanimationGetID(aMowered);
  mZombiePhase = PHASE_ZOMBIE_MOWERED;
  DropLoot();
  return;
}
// ==========================================================================
// Zombie::UpdateZombiePosition(void)
// @001B1DC8  178 bytes
// ==========================================================================
float Zombie::UpdateZombiePosition()
{
  // Bungee, boss, a grave rise, and the zombiquarium height never walk.
  // Those exits leave r0 as this; the only caller ignores the float.
  if ( mZombieType == ZOMBIE_BUNGEE || mZombieType == ZOMBIE_BOSS
       || mZombiePhase == PHASE_RISING_FROM_GRAVE
       || mZombieHeight == HEIGHT_ZOMBIQUARIUM )
    return mPosY;

  UpdateZombieWalking();
  CheckForZombieStep();
  if ( mBlowingAway )
  {
    mPosX += 10.0f;
    if ( mX > 850 )
    {
      DieWithLoot();
      return mPosY;
    }
  }
  if ( mZombieHeight != HEIGHT_ZOMBIE_NORMAL )
    return mPosY;

  float aRowY = GetPosYBasedOnRow(mRow);
  float aDelta = aRowY - mPosY;
  if ( aDelta > 1.0f )
    aDelta = 1.0f;
  else if ( aDelta < -1.0f )
    aDelta = -1.0f;
  if ( aDelta != 0.0f )
    mPosY += aDelta;
  return aRowY;
}

// ==========================================================================
// Zombie::PickBungeeZombieTarget(int)
// @001B1E7C  292 bytes
// ==========================================================================
void Zombie::PickBungeeZombieTarget(int theTargetCol)
{
  // theTargetCol == -1 scans every column; any other value scans only that column.
  // Empty cells weigh 1, a real plant weighs 10000. Gravebusters and cob
  // cannons are never grabbed. Sun-makers are skipped once the remaining
  // sunflowers equal the bungees already aimed at them.
  TodWeightedGridArray aCells[MAX_GRID_SIZE_X * MAX_GRID_SIZE_Y];
  int aCount = 0;
  int aBungeesOnSun = CountBungeesTargetingSunFlowers();
  int aSunsLeft = mBoard->CountSunFlowers() - 1;

  for ( int aCol = 0; aCol < MAX_GRID_SIZE_X; aCol++ )
  {
    if ( theTargetCol != -1 && theTargetCol != aCol )
      continue;
    for ( int aRow = 0; aRow < MAX_GRID_SIZE_Y; aRow++ )
    {
      if ( mBoard->GetGraveStoneAt(aCol, aRow) != nullptr )
        continue;
      if ( mBoard->mGridSquareType[aCol][aRow] == GRIDSQUARE_DIRT )
        continue;

      int aWeight = 1;
      Plant *aPlant = mBoard->GetTopPlantAt(aCol, aRow, TOPPLANT_PUMPKIN_ORDER);
      if ( aPlant != nullptr )
      {
        if ( aBungeesOnSun == aSunsLeft && aPlant->MakesSun() )
          continue;
        if ( aPlant->mSeedType == SEED_GRAVEBUSTER || aPlant->mSeedType == SEED_COBCANNON )
          continue;
        aWeight = 10000;
      }
      if ( mBoard->BungeeIsTargetingCell(aCol, aRow) != 0 )
        continue;

      aCells[aCount].mX = aCol;
      aCells[aCount].mY = aRow;
      aCells[aCount].mWeight = aWeight;
      aCount++;
    }
  }

  if ( aCount == 0 )
  {
    DieNoLoot();
    return;
  }

  TodWeightedGridArray *aPick = TodPickFromWeightedGridArray(aCells, aCount);
  mTargetCol = aPick->mX;
  SetRow(aPick->mY);
  mPosX = (float)mBoard->GridToPixelX(mTargetCol, mRow);
  mPosY = GetPosYBasedOnRow(mRow);
}// ==========================================================================
// Zombie::BossBungeeSpawn(void)
// @001B1FA0  98 bytes
// ==========================================================================
int Zombie::BossBungeeSpawn()
{
  // 0x53 is PHASE_BOSS_BUNGEES_DROP. Hex-Rays prints the immediate as &dword_50+3.
  // The +4 walk is mFollowerZombieID[0..2], not a cast of this.
  mZombiePhase = PHASE_BOSS_BUNGEES_DROP;
  int aId = 0;
  for ( int i = 0; i < 3; i++ )
  {
    Zombie *aBungee = mBoard->AddZombieInRow(ZOMBIE_BUNGEE, 0, 0, true);
    aBungee->PickBungeeZombieTarget(mTargetCol + i);
    aBungee->mAltitude = aBungee->mPosY - 50.0f;
    aId = mBoard->ZombieGetID(aBungee);
    mFollowerZombieID[i] = static_cast<ZombieID>(aId);
  }
  return aId;
}// ==========================================================================
// Zombie::UpdateZombieBungee(void)
// @001B2008  284 bytes
// ==========================================================================
void Zombie::UpdateZombieBungee()
{
  if ( IsDeadOrDying() )
    return;
  if ( IsImmobilizied() )
    return;

  if ( mZombiePhase == PHASE_BUNGEE_DIVING || mZombiePhase == PHASE_BUNGEE_DIVING_SCREAMING )
  {
    float aOldAltitude = mAltitude;
    mAltitude -= 8.0f;
    // The approach sound fires once when crossing 2596 downward.
    if ( mAltitude <= 2596.0f && aOldAltitude > 2596.0f && mRelatedZombieID == ZOMBIEID_NULL )
      mApp->PlayFoley(FOLEY_GRASSSTEP);
    BungeeLanding();
  }
  else if ( mZombiePhase == PHASE_BUNGEE_AT_BOTTOM )
  {
    if ( mPhaseCounter <= 0 )
    {
      BungeeStealTarget();
      mZombiePhase = PHASE_BUNGEE_GRABBING;
    }
  }
  else if ( mZombiePhase == PHASE_BUNGEE_GRABBING )
  {
    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
    if ( aBodyReanim->mLoopCount > 0 )
    {
      BungeeLiftTarget();
      mZombiePhase = PHASE_BUNGEE_RISING;
    }
  }
  else if ( mZombiePhase == PHASE_BUNGEE_HIT_OUCHY )
  {
    if ( mPhaseCounter <= 0 )
      DieWithLoot();
  }
  else if ( mZombiePhase == PHASE_BUNGEE_RISING )
  {
    mAltitude += 8.0f;
    if ( mAltitude >= 600.0f )
      DieNoLoot();
  }
  else if ( mZombiePhase == PHASE_BUNGEE_CUTSCENE )
  {
    // Fifth argument is the integer 0, not a float. Curve 12 is CURVE_SIN_WAVE.
    int aAltitude = TodAnimateCurve(200, 0, mPhaseCounter, 40, 0, CURVE_SIN_WAVE);
    if ( mPhaseCounter <= 0 )
      mPhaseCounter = 200;
    mAltitude = (float)aAltitude;
  }

  mX = (int)mPosX;
  mY = (int)mPosY;
}// ==========================================================================
// Zombie::UpdateZombieJackInTheBox(void)
// @001B212C  330 bytes
// ==========================================================================
void Zombie::UpdateZombieJackInTheBox()
{
  if ( mZombiePhase == PHASE_JACK_IN_THE_BOX_RUNNING )
  {
    // The box pops either when its run-down reaches zero, or when the level is
    // "Little Trouble" and the zombie is already eating.
    if ( (mPhaseCounter <= 0 && mHasHead)
      || (mApp->mGameMode == GAMEMODE_MP_VS && mIsEating) )
    {
      mPhaseCounter = 110;
      mZombiePhase = PHASE_JACK_IN_THE_BOX_POPPING;
      StopZombieSound();
      mApp->PlaySample(SOUND_BOING, true);
      {
          PlayZombieReanim("anim_pop", REANIM_PLAY_ONCE_AND_HOLD, 20, 28.0f);
          return;
      }
    }
    return;
  }

  if ( mZombiePhase != PHASE_JACK_IN_THE_BOX_POPPING )
    return;

  // The pop plays out; the squeak lands 80 frames in and the bang at the end.
  if ( mPhaseCounter == 80 )
    mApp->PlayFoley(FOLEY_JACKINTHEBOX);

  if ( mPhaseCounter > 0 )
    return;

  mApp->PlayFoley(FOLEY_EXPLOSION);
  int aCenterX = mX + mWidth / 2;
  int aCenterY = mY + mHeight / 2;

  // The explosion kills in a radius. In the versus mode it spares the other
  // player's zombies (mask 0x7F); everywhere else it takes everything (0xFF)
  // and also clears the plants.
  if ( mMindControlled )
  {
    mBoard->KillAllZombiesInRadius(mRow, aCenterX, aCenterY, 115, 1, true, 0x7F);
  }
  else
  {
    mBoard->KillAllZombiesInRadius(mRow, aCenterX, aCenterY, 115, 1, true, 0xFF);
    mBoard->KillAllPlantsInRadius(aCenterX, aCenterY, 90);
  }

  mApp->AddTodParticle((float)aCenterX, (float)aCenterY,
                       mRenderOrder, (ParticleEffect)5);  // PARTICLE_JACK_EXPLOSION
  mBoard->ShakeBoard(4, -6);
  DieNoLoot();

  if ( mApp->IsScaryPotterLevel() )
    mBoard->mChallenge->ScaryPotterJackExplode(aCenterX, aCenterY);
  return;
}
// ==========================================================================
// Zombie::UpdateZombieJalapenoHead(void)
// @001B2284  118 bytes
// ==========================================================================
void Zombie::UpdateZombieJalapenoHead()
{
  // The jalapeno head only fires while the zombie still has its head and is not
  // already counting a phase down.
  if ( !mHasHead || mPhaseCounter != 0 )
    return;

  mApp->PlayFoley(FOLEY_JALAPENO_IGNITE);
  mApp->PlayFoley(FOLEY_JUICY);
  mBoard->DoFwoosh(mRow);
  mBoard->ShakeBoard(3, -4);

  // Everything standing in the zombie's own row is burned down.
  Plant *aPlant = nullptr;
  while ( mBoard->IteratePlants(aPlant) )
  {
    if ( aPlant->mRow == mRow && !aPlant->NotOnGround() )
      aPlant->Die();
  }
  DieNoLoot();
}
// ==========================================================================
// Zombie::BobsledDie(void)
// @001B22FC  88 bytes
// ==========================================================================
void Zombie::BobsledDie()
{
    if (!IsBobsledTeamWithSled() || !IsOnBoard())
        return;

    // The sled's leader dies first, then every rider still following it.
    Zombie *aLeader = this;
    if (mRelatedZombieID != 0)
        aLeader = mBoard->ZombieGet(mRelatedZombieID);
    if (!aLeader->mDead)
        aLeader->DieNoLoot();

    for (int i = 0; i < 4; i++)
    {
        Zombie *aFollower = mBoard->ZombieGet(mFollowerZombieID[i]);
        if (!aFollower->mDead)
            aFollower->DieNoLoot();
    }
}
// ==========================================================================
// Zombie::BungeeDie(void)
// @001B2354  82 bytes
// ==========================================================================
void Zombie::BungeeDie()
{
    BungeeDropPlant();

    // The plant this bungee was carrying: if it is still alive, kill it.
    if (mTargetPlantID != 0
        && (unsigned int)(unsigned __int16)mTargetPlantID < mBoard->mPlants.mMaxSize)
    {
        PlantSlot *aPlantSlot = mBoard->mPlants.mBlock
                              + (unsigned short)mTargetPlantID;
        if (mTargetPlantID == aPlantSlot->mID)
            aPlantSlot->mItem.Die();
    }

    Zombie *aZombie = mBoard->ZombieTryToGet(mRelatedZombieID);
    if (aZombie != nullptr && !aZombie->mDead)
        aZombie->DieNoLoot();
}
// ==========================================================================
// Zombie::UpdateDeath(void)
// @001B23A8  1212 bytes
// ==========================================================================
void Zombie::UpdateDeath()
{
    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr)
    {
        DieNoLoot();
        return;
    }

    if (mZombieHeight == HEIGHT_FALLING)
        UpdateZombieFalling();

    // A dying gargantuar shakes the board twice on its way down.
    if (mZombieType == ZOMBIE_GARGANTUAR || mZombieType == ZOMBIE_REDEYE_GARGANTUAR)
    {
        if (aBodyReanim->ShouldTriggerTimedEvent(0.89f))
            mBoard->ShakeBoard(0, 3);
        else if (aBodyReanim->ShouldTriggerTimedEvent(0.98f))
            mBoard->ShakeBoard(0, 1);
    }

    if (!mInPool && mZombieType != ZOMBIE_SNORKEL && mZombieType != ZOMBIE_ZAMBONI)
    {
        // How far into the death animation the body has to be before it hits the
        // ground and grunts.  -1 means this zombie never plays the fall sound.
        float aFallTime = -1.0f;
        switch (mZombieType)
        {
            case ZOMBIE_NORMAL:
            case ZOMBIE_FLAG:
            case ZOMBIE_TRAFFIC_CONE:
            case ZOMBIE_PAIL:
            case ZOMBIE_DOOR:
            case ZOMBIE_DUCKY_TUBE:
            case ZOMBIE_TRASHCAN:
            case ZOMBIE_PEA_HEAD:
            case ZOMBIE_WALLNUT_HEAD:
            case ZOMBIE_JALAPENO_HEAD:
            case ZOMBIE_GATLING_HEAD:
            case ZOMBIE_SQUASH_HEAD:
            case ZOMBIE_TALLNUT_HEAD:
                // The ordinary deaths take their cue from whichever death
                // animation the body happens to be playing.  The binary also
                // queries anim_walnutdeath here and discards the answer.
                aBodyReanim->IsAnimPlaying("anim_walnutdeath");
                if (aBodyReanim->IsAnimPlaying("anim_superlongdeath"))
                    aFallTime = 0.788f;
                else if (aBodyReanim->IsAnimPlaying("anim_death2"))
                    aFallTime = 0.71f;
                else
                    aFallTime = 0.77f;
                break;

            case ZOMBIE_POLEVAULTER:
            case ZOMBIE_BALLOON:
            case ZOMBIE_YETI:
                aFallTime = 0.68f;
                break;

            case ZOMBIE_FOOTBALL:
                aFallTime = 0.52f;
                break;

            case ZOMBIE_NEWSPAPER:
                aFallTime = 0.63f;
                break;

            case ZOMBIE_DANCER:
            case ZOMBIE_BACKUP_DANCER:
                aFallTime = 0.83f;
                break;

            case ZOMBIE_BOBSLED:
                aFallTime = 0.81f;
                break;

            case ZOMBIE_JACK_IN_THE_BOX:
                aFallTime = 0.64f;
                break;

            case ZOMBIE_DIGGER:
                aFallTime = 0.85f;
                break;

            case ZOMBIE_POGO:
                aFallTime = 0.84f;
                break;

            case ZOMBIE_LADDER:
                aFallTime = 0.62f;
                break;

            case ZOMBIE_GARGANTUAR:
            case ZOMBIE_REDEYE_GARGANTUAR:
                aFallTime = 0.86f;
                break;

            default:
                break;
        }

        if (aFallTime > 0.0f && aBodyReanim->ShouldTriggerTimedEvent(aFallTime))
        {
            mApp->PlayFoley(FOLEY_ZOMBIE_FALLING);
            if (mZombieType == ZOMBIE_GARGANTUAR || mZombieType == ZOMBIE_REDEYE_GARGANTUAR)
                mApp->PlayFoley(FOLEY_THUMP);
            if (mBoard->mDaisyMode)
                DoDaisies();
        }
    }

    if (mZombieType == ZOMBIE_BOSS)
    {
        // The boss goes off in a long series of small explosions.
        if (aBodyReanim->ShouldTriggerTimedEvent(0.1f)
            || aBodyReanim->ShouldTriggerTimedEvent(0.12f)
            || aBodyReanim->ShouldTriggerTimedEvent(0.15f)
            || aBodyReanim->ShouldTriggerTimedEvent(0.19f)
            || aBodyReanim->ShouldTriggerTimedEvent(0.2f)
            || aBodyReanim->ShouldTriggerTimedEvent(0.26f)
            || aBodyReanim->ShouldTriggerTimedEvent(0.3f)
            || aBodyReanim->ShouldTriggerTimedEvent(0.4f)
            || aBodyReanim->ShouldTriggerTimedEvent(0.42f)
            || aBodyReanim->ShouldTriggerTimedEvent(0.5f)
            || aBodyReanim->ShouldTriggerTimedEvent(0.58f)
            || aBodyReanim->ShouldTriggerTimedEvent(0.61f)
            || aBodyReanim->ShouldTriggerTimedEvent(0.71f))
        {
            float aExplosionPosX = RandRangeFloat(600.0f, 750.0f);
            float aExplosionPosY = RandRangeFloat(50.0f, 300.0f);
            mApp->AddTodParticle(aExplosionPosX, aExplosionPosY,
                                 RenderLayer::RENDER_LAYER_TOP,
                                 PARTICLE_BOSS_EXPLOSION);
            mApp->PlayFoley(FOLEY_BOSS_EXPLOSION_SMALL);
        }

        Reanimation *aHeadReanim = mApp->ReanimationTryToGet(mSpecialHeadReanimID);
        if (aBodyReanim->ShouldTriggerTimedEvent(0.93f))
        {
            mBoard->ShakeBoard(1, 2);
            mApp->PlayFoley(FOLEY_BOSS_EXPLOSION_SMALL);
            mApp->PlayFoley(FOLEY_THUMP);
        }
        if (aBodyReanim->ShouldTriggerTimedEvent(0.99f))
            aHeadReanim->PlayReanim("anim_flag", REANIM_PLAY_ONCE_AND_HOLD, 20, 30.0f);
        if (aHeadReanim->IsAnimPlaying("anim_flag") && aHeadReanim->mLoopCount > 0)
            aHeadReanim->PlayReanim("anim_flag_loop", REANIM_LOOP, 20, 17.0f);
        if (aBodyReanim->mLoopCount > 0)
            DropLoot();
    }

    if (mZombieType == ZOMBIE_ZAMBONI)
    {
        if (mPhaseCounter > 0)
        {
            mPhaseCounter--;
            if (mPhaseCounter == 0)
            {
                // The wheelie track decides which of the two explosions is used.
                if (aBodyReanim->IsTrackShowing("anim_wheelie2"))
                    mApp->AddTodParticle(mPosX + 80.0f, mPosY + 60.0f, mRenderOrder + 1,
                                         PARTICLE_ZAMBONI_EXPLOSION2);
                else
                    mApp->AddTodParticle(mPosX + 80.0f, mPosY + 60.0f, mRenderOrder + 1,
                                         PARTICLE_ZAMBONI_EXPLOSION);
                DieWithLoot();
                mApp->PlayFoley(FOLEY_EXPLOSION);
            }
            return;
        }
    }
    else if (mZombieType == ZOMBIE_CATAPULT)
    {
        mPhaseCounter--;
        if (mPhaseCounter == 0)
        {
            mApp->AddTodParticle(mPosX + 80.0f, mPosY + 60.0f, mRenderOrder + 1,
                                 PARTICLE_CATAPULT_EXPLOSION);
            DieWithLoot();
            mApp->PlayFoley(FOLEY_EXPLOSION);
        }
        return;
    }

    // Once the body animation has looped at least once the corpse starts to fade.
    if (mZombieFade == -1 && aBodyReanim->mLoopCount > 0 && mZombieType != ZOMBIE_BOSS)
        mZombieFade = mInPool ? 10 : 100;
}
// ==========================================================================
// Zombie::PlayDeathAnim(unsigned int)
// @001B2874  668 bytes
// ==========================================================================
void Zombie::PlayDeathAnim(unsigned int theDamageFlags)
{
    // Already dying, burnt or mowed down: nothing left to start.
    if (mZombiePhase == PHASE_ZOMBIE_DYING || mZombiePhase == PHASE_ZOMBIE_BURNED
        || mZombiePhase == PHASE_ZOMBIE_MOWERED)
        return;

    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr || aBodyReanim->TrackExistsById(ReanimTrackId_anim_death) == 0)
    {
        DieNoLoot();
        return;
    }

    // A dolphin rider only gets its death animation while it is still in the
    // pool; a snorkel caught between the water and the lawn dies outright.
    if (mZombieType == ZOMBIE_DOLPHIN_RIDER)
    {
        if (mZombiePhase != PHASE_DOLPHIN_WALKING_IN_POOL)
        {
            DieNoLoot();
            return;
        }
    }
    else if (mZombiePhase == PHASE_SNORKEL_WALKING || mZombiePhase == PHASE_SNORKEL_INTO_POOL)
    {
        DieNoLoot();
        return;
    }

    if (mIceTrapCounter > 0)
    {
        AddAttachedParticle(75, 106, PARTICLE_ICE_TRAP_RELEASE);
        mIceTrapCounter = 0;
    }
    if (mButteredCounter > 0)
        mButteredCounter = 0;
    if (mYuckyFace)
    {
        ShowYuckyFace(false);
        mYuckyFace = false;
        mYuckyFaceCounter = 0;
    }

    // DAMAGE_DOESNT_LEAVE_BODY: only the three big zombies stay behind.
    if ((theDamageFlags & 0x10) != 0)
    {
        if (mZombieType != ZOMBIE_GARGANTUAR && mZombieType != ZOMBIE_BOSS
            && mZombieType != ZOMBIE_REDEYE_GARGANTUAR)
        {
            DieNoLoot();
            return;
        }
    }

    if (mZombieType == ZOMBIE_POGO)
        mAltitude = 0.0f;

    AttachmentReanimTypeDie(mAttachmentID, REANIM_ZOMBIE_SURPRISE);
    StopEating();

    if (mShieldType != 0)
        DropShield(1);

    if (mZombieType == ZOMBIE_SQUASH_HEAD && !mHasHead)
    {
        mApp->RemoveReanimation(mSpecialHeadReanimID);
        mSpecialHeadReanimID = REANIMATIONID_NULL;
    }

    mVelX = 0.0f;
    mZombiePhase = PHASE_ZOMBIE_DYING;

    if (mZombieHeight == HEIGHT_ZOMBIQUARIUM)
    {
        PlayZombieReanim("anim_aquarium_death", REANIM_PLAY_ONCE_AND_HOLD, 20, 14.0f);
        return;
    }
    if (mZombieHeight == HEIGHT_UP_LADDER)
        mZombieHeight = HEIGHT_FALLING;

    // How fast the death animation plays depends on the zombie.
    float aDeathAnimRate;
    if (mZombieType == ZOMBIE_FOOTBALL)
    {
        aDeathAnimRate = 24.0f;
    }
    else if (mZombieType == ZOMBIE_GARGANTUAR || mZombieType == ZOMBIE_REDEYE_GARGANTUAR)
    {
        aDeathAnimRate = 14.0f;
        mApp->PlayFoley(FOLEY_GARGANTUDEATH);
    }
    else if (mZombieType == ZOMBIE_SNORKEL)
    {
        aDeathAnimRate = 14.0f;
    }
    else if (mZombieType == ZOMBIE_DIGGER)
    {
        aDeathAnimRate = 18.0f;
    }
    else if (mZombieType == ZOMBIE_YETI)
    {
        aDeathAnimRate = 14.0f;
    }
    else if (mZombieType == ZOMBIE_BOSS)
    {
        aDeathAnimRate = 18.0f;
        BossDie();
        Reanimation *aHeadReanim = mApp->ReanimationGet(mSpecialHeadReanimID);
        aHeadReanim->PlayReanim("anim_death", REANIM_PLAY_ONCE_AND_HOLD, 20, 18.0f);
    }
    else
    {
        aDeathAnimRate = RandRangeFloat(24.0f, 30.0f);
    }

    // Which death track is used is mostly a one-in-a-hundred roll, but water,
    // a walnut's long death and a rare "superlong" death take priority.
    const char *aDeathTrackName = "anim_death";
    int aDeathAnimHit = Rand(100);
    bool aCanDoSuperLongDeath = mApp->HasFinishedAdventure() || mBoard->mLevel > 5;

    if (mInPool && aBodyReanim->TrackExistsById(ReanimTrackId_anim_waterdeath) != 0)
    {
        ReanimIgnoreClipRect("Zombie_duckytube", false);
        aDeathTrackName = "anim_waterdeath";
    }
    else if (mWalnutDeath && aBodyReanim->TrackExistsById(ReanimTrackId_anim_superlongdeath) != 0)
    {
        aDeathAnimRate = 14.0f;
        aDeathTrackName = "anim_walnutdeath";
    }
    // 0x1B2874: the 99-roll only picks anim_superlongdeath when the track
    // exists, the adventure/level gate is open, the zombie is not chilled
    // and at most five zombies are on screen. All five are one condition.
    else if (aDeathAnimHit == 99
             && aBodyReanim->TrackExistsById(ReanimTrackId_anim_superlongdeath) != 0
             && aCanDoSuperLongDeath
             && mChilledCounter == 0
             && mBoard->CountZombiesOnScreen() <= 5)
    {
        aDeathAnimRate = 14.0f;
        aDeathTrackName = "anim_superlongdeath";
    }
    else if (aDeathAnimHit > 50 && aBodyReanim->TrackExistsById(ReanimTrackId_anim_death2) != 0)
    {
        aDeathTrackName = "anim_death2";
    }

    PlayZombieReanim(aDeathTrackName, REANIM_PLAY_ONCE_AND_HOLD, 20, aDeathAnimRate);
    ReanimShowPrefix("anim_tongue", -1);  // RENDER_GROUP_HIDDEN
}
// ==========================================================================
// Zombie::UpdateDamageStates(unsigned int)
// @001B2B48  150 bytes
// ==========================================================================
void Zombie::UpdateDamageStates(unsigned int theDamageFlags)
{
    if (!CanLoseBodyParts())
        return;

    // An arm comes off once the body is down to two thirds of its health.
    if (mHasArm && mBodyHealth < 2 * mBodyMaxHealth / 3 && mBodyHealth > 0)
        DropArm(theDamageFlags);

    // The head comes off at a third; that is also when the loot drops.
    if (mHasHead && mBodyHealth < mBodyMaxHealth / 3)
    {
        DropHead(theDamageFlags);
        DropLoot();
        StopZombieSound();

        if (mBoard->HasLevelAwardDropped())
            PlayDeathAnim(theDamageFlags);

        // A snorkel zombie that loses its head while walking in the pool dies
        // outright instead of leaving a corpse behind.
        if (mZombiePhase == PHASE_SNORKEL_WALKING_IN_POOL)
            DieNoLoot();
    }

}
// ==========================================================================
// Zombie::AnimateChewSound(void)
// @001B2BE0  258 bytes
// ==========================================================================
void Zombie::AnimateChewSound()
{
    // The snorkel zombie eats underwater and has its own sound handling.
    if (mZombiePhase == PHASE_SNORKEL_UP_TO_EAT)
        return;

    Plant *aPlant = FindPlantTarget((ZombieAttackType)0);
    if (aPlant == nullptr)
    {
        // Nothing in the mouth: a mind-controlled zombie chomps more softly.
        if (mMindControlled)
            mApp->PlayFoley(FOLEY_CHOMP_SOFT);
        else
            mApp->PlayFoley(FOLEY_CHOMP);
        return;
    }

    // An awake hypno-shroom turns the zombie as it goes down.
    if (aPlant->mSeedType == SEED_HYPNOSHROOM && !aPlant->mIsAsleep)
    {
        mApp->PlayFoley(FOLEY_FLOOP);
        aPlant->Die();
        StartMindControlled();
        mApp->AddTodParticle(mPosX + 60.0f, mPosY + 40.0f, mRenderOrder + 1, PARTICLE_MIND_CONTROL);
        TrySpawnLevelAward();

        // The recruit switches sides and takes the mind-controlled walk speed.
        mAnimTicksPerFrame = 18;
        mVelX = 0.17f;
        UpdateAnimSpeed();
        return;
    }

    // Garlic: the zombie pulls a disgusted face, which drives it to another row.
    if (aPlant->mSeedType == SEED_GARLIC)
    {
        if (mYuckyFace)
            return;

        mYuckyFaceCounter = 0;
        mYuckyFace = true;
        UpdateAnimSpeed();
        mApp->PlayFoley(FOLEY_CHOMP);
        return;
    }

    // A nut is chewed softly, and only lets go when it has had enough.
    if (aPlant->mSeedType == SEED_WALLNUT || aPlant->mSeedType == SEED_TALLNUT)
    {
        if (!mBloated)
        {
            mApp->PlayFoley(FOLEY_CHOMP_SOFT);
            return;
        }

        if (mWalnutDeath)
            return;

        // The nut finally gives way and takes the zombie with it.
        mWalnutDeath = true;
        mApp->PlayFoley(FOLEY_CHOMP);
        PlayDeathAnim(0);
        return;
    }

    // A pumpkin shell is soft too, but it never bloats the zombie.
    if (aPlant->mSeedType == SEED_PUMPKINSHELL)
        mApp->PlayFoley(FOLEY_CHOMP_SOFT);
    else
        mApp->PlayFoley(FOLEY_CHOMP);
}
// ==========================================================================
// Zombie::Animate(void)
// @001B2CEC  346 bytes
// ==========================================================================
Zombie * Zombie::Animate()
{
    mPrevFrame = mFrame;

    // A popping jack-in-the-box, a maddening newspaper or a tunnelling digger
    // holds its animation; so does an immobilised zombie.
    if (mZombiePhase == PHASE_JACK_IN_THE_BOX_POPPING
        || mZombiePhase == PHASE_NEWSPAPER_MADDENING
        || (unsigned int)(mZombiePhase - 33) <= 3
        || IsImmobilizied())
        return this;

    mAnimCounter++;
    if (mYuckyFace)
        UpdateYuckyFace();

    if (mIsEating && mHasHead)
    {
        // Chewing runs at half speed while the zombie is chilled.
        int aFrameLength = mChilledCounter <= 0 ? 6 : 12;
        if (mAnimCounter >= mAnimFrames * aFrameLength)
            mAnimCounter = aFrameLength;
        mFrame = mAnimCounter / aFrameLength;

        Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
        if (aBodyReanim != nullptr)
        {
            // The chomp sound and the chew particle go off at two points in the
            // bite, and both depend on which zombie is doing the chewing.
            float aChewSoundTime = 0.14f;
            float aChewEffectTime = 0.68f;
            if (mZombieType == ZOMBIE_POLEVAULTER)
            {
                aChewSoundTime = 0.38f;
                aChewEffectTime = 0.8f;
            }
            else if (mZombieType == ZOMBIE_NEWSPAPER || mZombieType == ZOMBIE_LADDER)
            {
                aChewSoundTime = 0.42f;
                aChewEffectTime = 0.42f;
            }
            else if (mZombieType == ZOMBIE_JACK_IN_THE_BOX)
            {
                aChewSoundTime = 0.53f;
                aChewEffectTime = 0.53f;
            }
            else if (mZombieType == ZOMBIE_BOBSLED)
            {
                aChewSoundTime = 0.33f;
                aChewEffectTime = 0.83f;
            }
            else if (mZombieType == ZOMBIE_IMP)
            {
                aChewSoundTime = 0.33f;
                aChewEffectTime = 0.79f;
            }

            if (aBodyReanim->ShouldTriggerTimedEvent(aChewSoundTime)
                || aBodyReanim->ShouldTriggerTimedEvent(aChewEffectTime))
            {
                AnimateChewSound();
                AnimateChewEffect();
                return this;
            }
            return this;
        }

        if (mAnimCounter == 4 * aFrameLength)
            AnimateChewSound();
        if (mAnimCounter == 7 * aFrameLength && !mMindControlled)
            AnimateChewEffect();
        return this;
    }
    else
    {
        // Not eating: the animation frame just advances at the current rate.
        if (mAnimCounter >= mAnimFrames * mAnimTicksPerFrame)
            mAnimCounter = 0;
        mFrame = mAnimCounter / mAnimTicksPerFrame;
    }

    return this;
}
// ==========================================================================
// Zombie::BossStartDeath(void)
// @001B2E58  102 bytes
// ==========================================================================
int Zombie::BossStartDeath()
{
    // The head comes off and leaves; the explosion and the rumble accompany it.
    mZombiePhase = PHASE_BOSS_HEAD_LEAVE;
    PlayZombieReanim("anim_head_leave", REANIM_PLAY_ONCE_AND_HOLD, 0, 24.0f);
    mApp->AddTodParticle(700.0f, 150.0f, RenderLayer::RENDER_LAYER_TOP,
                         (ParticleEffect)81);  // PARTICLE_BOSS_EXPLOSION
    mApp->PlaySample(SOUND_BOSSEXPLOSION, true);
    mApp->PlayFoley(FOLEY_GARGANTUDEATH);
    return BossDie();
}
// ==========================================================================
// Zombie::BossSetupReanim(void)
// @001B2ECC  182 bytes
// ==========================================================================
void Zombie::BossSetupReanim()
{
    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
    aBodyReanim->AssignRenderGroupToPrefix("Boss_innerleg", 4);
    aBodyReanim->AssignRenderGroupToPrefix("Boss_outerleg", 5);
    aBodyReanim->AssignRenderGroupToPrefix("Boss_body2", 5);
    aBodyReanim->AssignRenderGroupToPrefix("Boss_innerarm", 6);
    aBodyReanim->AssignRenderGroupToPrefix("Boss_RV", 6);

    // 0x5F is the driver reanim. +0x154 is mSpecialHeadReanimID, not the fireball.
    Reanimation *aDriverReanim = mApp->AddReanimation(0.0f, 0.0f, 0, REANIM_BOSS_DRIVER);
    aDriverReanim->PlayReanim("anim_idle", REANIM_LOOP, 0, 18.0f);
    mSpecialHeadReanimID = mApp->ReanimationGetID(aDriverReanim);

    // MOVT immediates are 28.0f and -84.0f. +0x30 is mFrameBasePose.
    // 0x3F99999A is 1.2f on both scale terms.
    ReanimatorTrackInstance *aHeadTrack = aBodyReanim->GetTrackInstanceByName("Boss_head2");
    AttachEffect *aEffect = AttachReanim(aHeadTrack->mAttachmentID, aDriverReanim, 28.0f, -84.0f);
    aBodyReanim->mFrameBasePose = 0;
    aEffect->mDontDrawIfParentHidden = true;
    aEffect->mOffset.m00 = 1.2f;
    aEffect->mOffset.m11 = 1.2f;
}
// ==========================================================================
// Zombie::DrawBossPart(Sexy::Graphics *,BossPart)
// @001B2FA0  108 bytes
// ==========================================================================
void Zombie::DrawBossPart(Sexy::Graphics *g, BossPart theBossPart)
{
    ZombieDrawPosition aDrawPos;
    GetDrawPos(aDrawPos);
    switch (theBossPart)
    {
        case 0:
            DrawReanim(g, aDrawPos, 4);
            break;
        case 1:
            DrawReanim(g, aDrawPos, 5);
            break;
        case 2:
            DrawReanim(g, aDrawPos, 0);
            break;
        case 3:
            DrawBossBackArm(g, aDrawPos);
            break;
        case 4:
            DrawBossFireBall(g, aDrawPos);
            break;
        default:
            break;
    }
}

// ==========================================================================
// Zombie::PreloadZombieResources(ZombieType)
// @001B300C  218 bytes
// ==========================================================================
int Zombie::PreloadZombieResources(ZombieType theZombieType)
{
    // The zombie definition record is not modelled in this tree, so its
    // reanimation word is read at +4 the way the neighbouring bodies do.
    ReanimationType aBodyReanimType = GetZombieDefinition(theZombieType)->mReanimationType;
    if (aBodyReanimType != REANIM_NONE)
        ReanimatorEnsureDefinitionLoaded(aBodyReanimType, true);

    switch (theZombieType)
    {
        case ZOMBIE_DIGGER:
            ReanimatorEnsureDefinitionLoaded(REANIM_DIGGER_DIRT, true);
            ReanimatorEnsureDefinitionLoaded(REANIM_ZOMBIE_CHARRED_DIGGER, true);
            break;

        case ZOMBIE_BOSS:
            ReanimatorEnsureDefinitionLoaded(REANIM_BOSS_DRIVER, true);
            ReanimatorEnsureDefinitionLoaded(REANIM_BOSS_FIREBALL, true);
            ReanimatorEnsureDefinitionLoaded(REANIM_BOSS_ICEBALL, true);
            // Everything the boss can summon.
            for (int i = 0; i < 12; i++)
            {
                int aSummonedType = gBossZombieList[i];
                ReanimationType aSummonedReanim = GetZombieDefinition((ZombieType)aSummonedType)->mReanimationType;
                ReanimatorEnsureDefinitionLoaded(aSummonedReanim, true);
            }
            break;

        case ZOMBIE_DANCER:
            ReanimatorEnsureDefinitionLoaded(REANIM_BACKUP_DANCER, true);
            break;

        default:
            break;
    }

    if (theZombieType == ZOMBIE_GARGANTUAR || theZombieType == ZOMBIE_REDEYE_GARGANTUAR)
    {
        ReanimatorEnsureDefinitionLoaded(REANIM_IMP, true);
        ReanimatorEnsureDefinitionLoaded(REANIM_ZOMBIE_CHARRED_IMP, true);
        ReanimatorEnsureDefinitionLoaded(REANIM_ZOMBIE_CHARRED_GARGANTUAR, true);
    }
    else if (theZombieType == ZOMBIE_ZAMBONI)
    {
        ReanimatorEnsureDefinitionLoaded(REANIM_IMP, true);
        ReanimatorEnsureDefinitionLoaded(REANIM_ZOMBIE_CHARRED_ZAMBONI, true);
    }
    else if (theZombieType == ZOMBIE_CATAPULT)
    {
        ReanimatorEnsureDefinitionLoaded(REANIM_ZOMBIE_CHARRED_CATAPULT, true);
    }

    ReanimatorEnsureDefinitionLoaded(REANIM_PUFF, true);
    ReanimatorEnsureDefinitionLoaded(REANIM_ZOMBIE_CHARRED, true);
    return ReanimatorEnsureDefinitionLoaded(REANIM_LAWN_MOWERED_ZOMBIE, true);
}
// ==========================================================================
// Zombie::ApplyBossSmokeParticles(bool)
// @001B30F0  254 bytes
// ==========================================================================
void Zombie::ApplyBossSmokeParticles(bool theEnable)
{
    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    ReanimatorTrackInstance *aHeadTrack = aBodyReanim->GetTrackInstanceByName("Boss_head");
    AttachmentDetachCrossFadeParticleType(aHeadTrack->mAttachmentID, (ParticleEffect)60, nullptr);
    if (!theEnable)
        return;

    // The two always-on smoke trails on the boss's head.
    TodParticleSystem *aSmoke1 = mApp->AddTodParticle(0.0f, 0.0f, 0, (ParticleEffect)60);
    TodParticleSystem *aSmoke2 = mApp->AddTodParticle(0.0f, 0.0f, 0, (ParticleEffect)60);

    if (aSmoke1 != nullptr)
    {
        AttachEffect *aEffect = aBodyReanim->AttachParticleToTrack("Boss_head", aSmoke1, 120.0f, 30.0f);
        aEffect->mDontDrawIfParentHidden = true;
        aEffect->mDontPropogateColor = true;
    }
    if (aSmoke2 != nullptr)
    {
        AttachEffect *aEffect = aBodyReanim->AttachParticleToTrack("Boss_head", aSmoke2, 205.0f, 58.0f);
        aEffect->mDontDrawIfParentHidden = true;
        aEffect->mDontPropogateColor = true;
    }

    // Below a tenth of its health the boss trails a third plume as well.
    if (mBodyHealth >= mBodyMaxHealth / 10)
        return;

    TodParticleSystem *aSmoke3 = mApp->AddTodParticle(0.0f, 0.0f, 0, (ParticleEffect)60);
    if (aSmoke3 == nullptr)
        return;
    AttachEffect *aEffect = aBodyReanim->AttachParticleToTrack("Boss_head", aSmoke3, 193.0f, 27.0f);
    aEffect->mDontDrawIfParentHidden = true;
    aEffect->mDontPropogateColor = true;
}
// ==========================================================================
// Zombie::TakeBodyDamage(int,unsigned int)
// @001B31FC  980 bytes
// ==========================================================================
void Zombie::TakeBodyDamage(int theDamage, unsigned int theDamageFlags)
{
    // DAMAGE_DOESNT_CAUSE_FLASH: a hit that should not make the zombie flash.
    if ((theDamageFlags & 8) == 0)
        mJustGotShotCounter = 25;

    if ((theDamageFlags & 4) != 0)  // DAMAGE_FREEZE
        ApplyChill(false);

    int aHealthBefore = mBodyHealth;
    int aDamageIndexBefore = GetBodyDamageIndex();
    mBodyHealth -= theDamage;
    int aDamageIndexAfter = GetBodyDamageIndex();
    bool aIndexChanged = aDamageIndexBefore != aDamageIndexAfter;

    if (mZombieType == ZOMBIE_ZAMBONI)
    {
        Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
        if ((theDamageFlags & 8) == 0)
            mApp->PlayFoley(FOLEY_SHIELD_HIT);

        if ((theDamageFlags & 0x20) != 0)  // DAMAGE_SPIKE
        {
            aBodyReanim->SetImageOverride("Zombie_zamboni_1",
                                          IMAGE_REANIM_ZOMBIE_ZAMBONI_1_DAMAGE2);
            aBodyReanim->SetImageOverride("Zombie_zamboni_2",
                                          IMAGE_REANIM_ZOMBIE_ZAMBONI_2_DAMAGE2);
            ZamboniDeath(theDamageFlags);
        }
        else if (mBodyHealth > 0)
        {
            if (aIndexChanged && aDamageIndexAfter == 1)
            {
                aBodyReanim->SetImageOverride("Zombie_zamboni_1",
                                              IMAGE_REANIM_ZOMBIE_ZAMBONI_1_DAMAGE1);
                aBodyReanim->SetImageOverride("Zombie_zamboni_2",
                                              IMAGE_REANIM_ZOMBIE_ZAMBONI_2_DAMAGE1);
            }
            else if (aIndexChanged && aDamageIndexAfter == 2)
            {
                aBodyReanim->SetImageOverride("Zombie_zamboni_1",
                                              IMAGE_REANIM_ZOMBIE_ZAMBONI_1_DAMAGE2);
                aBodyReanim->SetImageOverride("Zombie_zamboni_2",
                                              IMAGE_REANIM_ZOMBIE_ZAMBONI_2_DAMAGE2);
                AddAttachedParticle(27, 72, (ParticleEffect)60);  // PARTICLE_ZAMBONI_SMOKE
            }
        }
        else
        {
            ZamboniDeath(theDamageFlags);
        }
    }
    else if (mZombieType == ZOMBIE_CATAPULT)
    {
        Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
        if ((theDamageFlags & 0x20) != 0 || mBodyHealth <= 0)
        {
            aBodyReanim->SetImageOverride("Zombie_catapult_siding",
                                          IMAGE_REANIM_ZOMBIE_CATAPULT_SIDING_DAMAGE);
            CatapultDeath(theDamageFlags);
        }
        else if (aIndexChanged)
        {
            if (aDamageIndexAfter == 1)
                aBodyReanim->SetImageOverride("Zombie_catapult_siding",
                                              IMAGE_REANIM_ZOMBIE_CATAPULT_SIDING_DAMAGE);
            else if (aDamageIndexAfter == 2)
                AddAttachedParticle(47, 77, (ParticleEffect)60);  // PARTICLE_ZAMBONI_SMOKE
        }
    }
    else if (mZombieType == ZOMBIE_GARGANTUAR || mZombieType == ZOMBIE_REDEYE_GARGANTUAR)
    {
        Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
        if (aIndexChanged)
        {
            if (aDamageIndexAfter == 1)
            {
                aBodyReanim->SetImageOverride("Zombie_gargantua_body1",
                                              IMAGE_REANIM_ZOMBIE_GARGANTUAR_BODY1_2);
                aBodyReanim->SetImageOverride("Zombie_gargantuar_outerarm_lower",
                                              IMAGE_REANIM_ZOMBIE_GARGANTUAR_OUTERARM_LOWER2);
            }
            else if (aDamageIndexAfter == 2)
            {
                aBodyReanim->SetImageOverride("Zombie_gargantua_body1",
                                              IMAGE_REANIM_ZOMBIE_GARGANTUAR_BODY1_3);
                aBodyReanim->SetImageOverride("Zombie_gargantuar_outerleg_foot",
                                              IMAGE_REANIM_ZOMBIE_GARGANTUAR_FOOT2);
                aBodyReanim->SetImageOverride("Zombie_gargantuar_outerarm_lower",
                                              IMAGE_REANIM_ZOMBIE_GARGANTUAR_OUTERARM_LOWER2);
                if (mZombieType == ZOMBIE_REDEYE_GARGANTUAR)
                    aBodyReanim->SetImageOverride("anim_head1",
                                                  IMAGE_REANIM_ZOMBIE_GARGANTUAR_HEAD2_REDEYE);
                else
                    aBodyReanim->SetImageOverride("anim_head1",
                                                  IMAGE_REANIM_ZOMBIE_GARGANTUAR_HEAD2);
            }
        }
    }
    else if (mZombieType == ZOMBIE_BOSS)
    {
        if ((theDamageFlags & 8) == 0)
            mApp->PlayFoley(FOLEY_SHIELD_HIT);

        Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
        if (aIndexChanged)
        {
            if (aDamageIndexAfter == 1)
            {
                aBodyReanim->SetImageOverride("Boss_head",
                                              IMAGE_REANIM_ZOMBIE_BOSS_HEAD_DAMAGE1);
                aBodyReanim->SetImageOverride("Boss_jaw",
                                              IMAGE_REANIM_ZOMBIE_BOSS_JAW_DAMAGE1);
                aBodyReanim->SetImageOverride("Boss_outerarm_hand",
                                              IMAGE_REANIM_ZOMBIE_BOSS_OUTERARM_HAND_DAMAGE1);
                aBodyReanim->SetImageOverride("Boss_outerarm_thumb2",
                                              IMAGE_REANIM_ZOMBIE_BOSS_OUTERARM_THUMB_DAMAGE1);
                aBodyReanim->SetImageOverride("Boss_innerleg_foot",
                                              IMAGE_REANIM_ZOMBIE_BOSS_FOOT_DAMAGE1);
            }
            else if (aDamageIndexAfter == 2)
            {
                aBodyReanim->SetImageOverride("Boss_head",
                                              IMAGE_REANIM_ZOMBIE_BOSS_HEAD_DAMAGE2);
                aBodyReanim->SetImageOverride("Boss_jaw",
                                              IMAGE_REANIM_ZOMBIE_BOSS_JAW_DAMAGE2);
                aBodyReanim->SetImageOverride("Boss_outerarm_hand",
                                              IMAGE_REANIM_ZOMBIE_BOSS_OUTERARM_HAND_DAMAGE2);
                aBodyReanim->SetImageOverride("Boss_outerarm_thumb2",
                                              IMAGE_REANIM_ZOMBIE_BOSS_OUTERARM_THUMB_DAMAGE2);
                aBodyReanim->SetImageOverride("Boss_outerleg_foot",
                                              IMAGE_REANIM_ZOMBIE_BOSS_FOOT_DAMAGE2);
                ApplyBossSmokeParticles(true);
            }
        }

        // The boss puffs smoke the moment its health crosses a tenth of its max.
        if (aHealthBefore >= mBodyMaxHealth / 10 && mBodyHealth < mBodyMaxHealth / 10)
        {
            mApp->AddTodParticle(770.0f, 260.0f, RenderLayer::RENDER_LAYER_TOP,
                                 (ParticleEffect)81);  // PARTICLE_BOSS_EXPLOSION
            mApp->PlayFoley(FOLEY_BOSS_EXPLOSION_SMALL);
            ApplyBossSmokeParticles(true);
        }

        // The boss never dies from body damage alone; it is finished by its own
        // death sequence.
        if (mBodyHealth <= 0)
            mBodyHealth = 1;
        return;
    }
    else
    {
        UpdateDamageStates(theDamageFlags);
    }

    if (mBodyHealth <= 0)
    {
        mBodyHealth = 0;
        PlayDeathAnim(theDamageFlags);
        // 0x1B31FC returns this. DropLoot's coin is not the function's result.
        DropLoot();
        return;
    }
    return;
}
// ==========================================================================
// Zombie::TakeDamage(int,unsigned int)
// @001B368C  120 bytes
// ==========================================================================
void Zombie::TakeDamage(int theDamage, unsigned int theDamageFlags)
{
    // A jack-in-the-box zombie is invulnerable while it is popping.
    if (mZombiePhase == PHASE_JACK_IN_THE_BOX_POPPING)
        return;

    if (IsDeadOrDying())
        return;

    int aDamageRemaining = theDamage;
    if (IsFlying())
        aDamageRemaining = TakeFlyingDamage(theDamage, theDamageFlags);

    if (aDamageRemaining <= 0)
        return;

    // theDamageFlags bit 0 = the damage passes the shield by; bit 1 = it hits the shield and
    // the body at once, so the body still takes the full original damage rather
    // than what is left of it after the shield.
    if (mShieldType != 0 && (theDamageFlags & 1) == 0)
    {
        int aShieldDamage = TakeShieldDamage(theDamage, theDamageFlags);
        aDamageRemaining = (theDamageFlags & 2) != 0 ? theDamage : aShieldDamage;
        if (aDamageRemaining <= 0)
            return;
    }

    if (mHelmType != 0)
    {
        aDamageRemaining = TakeHelmDamage(theDamage, theDamageFlags);
        if (aDamageRemaining <= 0)
            return;
    }

    {
        TakeBodyDamage(aDamageRemaining, theDamageFlags);
        return;
    }
}
// ==========================================================================
// Zombie::UpdateZombieSnorkel(void)
// @001B3704  692 bytes
// ==========================================================================
void Zombie::UpdateZombieSnorkel()
{
    bool aWalkingBackwards = IsWalkingBackwards();

    switch (mZombiePhase)
    {
        case PHASE_SNORKEL_WALKING:
            // Walk until the pool edge, then dive in.
            if (!aWalkingBackwards && mX > 700 && mX <= 720)
            {
                mZombiePhase = PHASE_SNORKEL_INTO_POOL;
                mVelX = 0.2f;
                PlayZombieReanim("anim_jumpinpool", REANIM_PLAY_ONCE_AND_HOLD, 20, 16.0f);
            }
            break;

        case PHASE_SNORKEL_INTO_POOL:
        {
            Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
            mAltitude = TodAnimateCurveFloat(0, 1000, (int)(aBodyReanim->mAnimTime * 1000.0f),
                                             0.0f, 10.0f, CURVE_LINEAR);
            if (aBodyReanim->ShouldTriggerTimedEvent(0.83f))
            {
                // The splash as the zombie hits the water.
                Reanimation *aSplash = mApp->AddReanimation((float)(mX - 47), (float)(mY + 73),
                                                            mRenderOrder + 1, REANIM_SPLASH);
                aSplash->OverrideScale(1.2f, 0.8f);
                mApp->AddTodParticle((float)(mX - 10), (float)(mY + 115), mRenderOrder + 1,
                                     PARTICLE_PLANTING_POOL);
                mApp->PlayFoley(FOLEY_ZOMBIE_ENTERING_WATER);
            }
            if (aBodyReanim->mLoopCount > 0)
            {
                mZombiePhase = PHASE_SNORKEL_WALKING_IN_POOL;
                mInPool = true;
                PlayZombieReanim("anim_swim", REANIM_LOOP_FULL_LAST_FRAME, 0, 12.0f);
            }
            break;
        }

        case PHASE_SNORKEL_WALKING_IN_POOL:
            if (!mHasHead)
            {
                TakeDamage(1800, 9U);
            }
            else if ((mX <= 25 && !aWalkingBackwards) || (mX > 640 && aWalkingBackwards))
            {
                // The TV binary loads 0xC2B40000: -90.0f.
                mAltitude = -90.0f;
                mZombieHeight = HEIGHT_OUT_OF_POOL;
                mZombiePhase = PHASE_SNORKEL_WALKING;
                mPosX += aWalkingBackwards ? 15.0f : -15.0f;
                PoolSplash(false);
                StartWalkAnim(0);
            }
            else if (mIsEating)
            {
                mZombiePhase = PHASE_SNORKEL_UP_TO_EAT;
                PlayZombieReanim("anim_uptoeat", REANIM_PLAY_ONCE_AND_HOLD, 0, 24.0f);
            }
            break;

        case PHASE_SNORKEL_UP_TO_EAT:
        {
            Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
            if (!mIsEating)
            {
                mZombiePhase = PHASE_SNORKEL_DOWN_FROM_EAT;
                PlayZombieReanim("anim_uptoeat", REANIM_PLAY_ONCE_AND_HOLD, 0, -24.0f);
            }
            else if (aBodyReanim->mLoopCount > 0)
            {
                mZombiePhase = PHASE_SNORKEL_EATING_IN_POOL;
                PlayZombieReanim("anim_eat", REANIM_LOOP, 0, 0.0f);
            }
            break;
        }

        case PHASE_SNORKEL_EATING_IN_POOL:
            if (!mIsEating)
            {
                mZombiePhase = PHASE_SNORKEL_DOWN_FROM_EAT;
                PlayZombieReanim("anim_uptoeat", REANIM_PLAY_ONCE_AND_HOLD, 0, -24.0f);
            }
            break;

        case PHASE_SNORKEL_DOWN_FROM_EAT:
        {
            Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
            if (aBodyReanim->mLoopCount > 0)
            {
                mZombiePhase = PHASE_SNORKEL_WALKING_IN_POOL;
                PlayZombieReanim("anim_swim", REANIM_LOOP_FULL_LAST_FRAME, 0, 0.0f);
                PickRandomSpeed();
            }
            break;
        }

        default:
            break;
    }
}
// ==========================================================================
// Zombie::UpdateZombieSquashHead(void)
// @001B39D8  616 bytes
// ==========================================================================
int Zombie::UpdateZombieSquashHead()
{
    // The squash head has two lives: while the head is still on, it can be
    // knocked off and reanimates onto the lawn as a separate object.
    if (mHasHead && mVariant)
    {
        if (mZombiePhase == PHASE_SQUASH_PRE_LAUNCH)
        {
            StopEating();
            PlayZombieReanim("anim_idle", REANIM_LOOP, 20, 12.0f);
            mHasHead = false;

            // The head launches off the body.
            Reanimation *aHeadReanim = mApp->ReanimationGet(mSpecialHeadReanimID);
            aHeadReanim->PlayReanim("anim_jumpup", REANIM_PLAY_ONCE_AND_HOLD, 20, 24.0f);
            aHeadReanim->mRenderOrder = mRenderOrder + 1;
            aHeadReanim->SetPosition(mPosX + 6.0f, mPosY - 21.0f);

            ReanimatorTrackInstance *aHeadTrack = mApp->ReanimationGet(mBodyReanimID)->GetTrackInstanceByName("anim_head1");
            AttachmentDetach(aHeadTrack->mAttachmentID);
            aHeadReanim->mLoopCount = 0;
            aHeadReanim->mAnimRate = 64.0f;
            aHeadReanim->mOverlayMatrix.m00 = 64.0f;

            mZombiePhase = PHASE_SQUASH_RISING;
            mAttachmentID = 95;  // ATTACHMENTID_SQUASH_HEAD
        }
    }

    if (mZombiePhase == PHASE_SQUASH_RISING)
    {
        // Rise over the square the body is standing in.
        int aGridX = mBoard->PixelToGridXKeepOnBoard(mX, mY);
        int aTargetX = mBoard->GridToPixelX(aGridX, mRow);
        int aOffsetX = TodAnimateCurve(50, 20, mAttachmentID, 0, (int)((float)aTargetX - mPosX),
                                       CURVE_LINEAR);
        int aOffsetY = TodAnimateCurve(50, 20, mAttachmentID, 0, -74, CURVE_LINEAR);
        mApp->ReanimationGet(mSpecialHeadReanimID)
            ->SetPosition((mPosX + 6.0f) + (float)aOffsetX, (mPosY - 21.0f) + (float)aOffsetY);

        if (mAttachmentID == 0)
        {
            mApp->ReanimationGet(mSpecialHeadReanimID)
                ->PlayReanim("anim_jumpdown", REANIM_PLAY_ONCE_AND_HOLD, 0, 60.0f);
            mZombiePhase = PHASE_SQUASH_FALLING;
            mAttachmentID = 10;
        }
    }

    if (mZombiePhase == PHASE_SQUASH_FALLING)
    {
        int aOffsetY = TodAnimateCurve(10, 0, mAttachmentID, -20, 74, CURVE_LINEAR);
        int aGridX = mBoard->PixelToGridXKeepOnBoard(mX, mY);
        int aTargetX = mBoard->GridToPixelX(aGridX, mRow);
        mApp->ReanimationGet(mSpecialHeadReanimID)
            ->SetPosition((float)aTargetX + 6.0f, (mPosY - 21.0f) + (float)aOffsetY);

        // The landing frame is the one that crushes whatever is underneath.
        if (mAttachmentID == 2)
            SquishAllInSquare(mBoard->PixelToGridXKeepOnBoard(mX, mY), mRow, (ZombieAttackType)0);

        if (mAttachmentID == 0)
        {
            mZombiePhase = PHASE_SQUASH_DONE_FALLING;
            mAttachmentID = 100;
            mBoard->ShakeBoard(1, 4);
            mApp->PlayFoley(FOLEY_THUMP);
        }
    }

    if (mZombiePhase == PHASE_SQUASH_DONE_FALLING && mAttachmentID == 0)
    {
        // The head is spent: kill it and take the body with it.
        mApp->ReanimationGet(mSpecialHeadReanimID)->ReanimationDie();
        mSpecialHeadReanimID = REANIMATIONID_NULL;
        {
      TakeDamage(1800, 9U);
      return 0;
    }
    }
    return 0;
}
// ==========================================================================
// Zombie::UpdateZombieBobsled(void)
// @001B3C50  322 bytes
// ==========================================================================
float Zombie::UpdateZombieBobsled()
{
    if (mZombiePhase == PHASE_BOBSLED_CRASHING)
    {
        if (mPhaseCounter != 0)
            return mPosY;

        // The sled has stopped: the team breaks up and every rider walks on its
        // own again.
        mZombiePhase = PHASE_ZOMBIE_NORMAL;
        if (GetBobsledPosition() != 0)
            return mPosY;

        for (int i = 0; i < 3; i++)  // three riders follow the sled leader
        {
            Zombie *aFollower = mBoard->ZombieGet(mFollowerZombieID[i]);
            aFollower->mRelatedZombieID = ZOMBIEID_NULL;
            mFollowerZombieID[i] = ZOMBIEID_NULL;
            aFollower->PickRandomSpeed();
        }
        PickRandomSpeed();
        return mPosY;
    }

    if (mZombiePhase == PHASE_BOBSLED_SLIDING)
    {
        if (mPhaseCounter == 0)
        {
            mZombiePhase = PHASE_BOBSLED_BOARDING;
            PlayZombieReanim("anim_jump", REANIM_PLAY_ONCE_AND_HOLD, 0, 20.0f);
        }
    }
    else
    {
        if (mZombiePhase != PHASE_BOBSLED_BOARDING)
            return mPosY;

        // While the team boards, the riders bob up and down; the two outside
        // riders start higher than the ones next to the leader.
        Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
        int aCounter = (int)(aBodyReanim->mAnimTime * 50.0f);
        int aPosition = GetBobsledPosition();
        if (aPosition == 1 || aPosition == 3)
            mAltitude = TodAnimateCurveFloat(0, 50, aCounter, 8.0f, 18.0f, CURVE_LINEAR);
        else
            mAltitude = TodAnimateCurveFloat(0, 50, aCounter, -9.0f, 18.0f, CURVE_LINEAR);
    }

    // The sled clears a path through the ice, and takes crash damage when it
    // reaches the ice's left edge.
    if (mBoard->mIceTimer[mRow] < 500)
        mBoard->mIceTimer[mRow] = 500;

    if (mPosX + 10.0f < (float)mBoard->mIceMinX[mRow] && GetBobsledPosition() == 0)
        TakeDamage(6, 8U);
        return mPosY;

    return mPosY;
}
// ==========================================================================
// Zombie::UpdateZombiquarium(void)
// @001B3D9C  674 bytes
// ==========================================================================
void Zombie::UpdateZombiquarium()
{
    if (IsDeadOrDying())
        return;

    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);

    if (mZombiePhase == PHASE_ZOMBIQUARIUM_BITE)
    {
        // After eating, resume the slow swim before choosing another heading.
        if (aBodyReanim->mLoopCount > 0)
        {
            PlayZombieReanim("anim_aquarium_swim", REANIM_LOOP, 20, RandRangeFloat(8.0f, 10.0f));
            mZombiePhase = PHASE_ZOMBIQUARIUM_DRIFT;
            mPhaseCounter = 100;
        }
    }
    else if (!ZombiquariumFindClosestBrain() && mPhaseCounter == 0)
    {
        // No brain in reach: drift in a random direction, or head straight for
        // the side of the tank. The heading lives in mVelZ, which this state
        // uses as an angle rather than as a vertical velocity.
        int aHeading = Rand(7);
        if (aHeading <= 4)
        {
            mZombiePhase = PHASE_ZOMBIQUARIUM_ACCEL;
            mVelZ = RandRangeFloat(0.0f, 6.2832f);  // any angle
        }
        else
        {
            mVelZ = aHeading == 5 ? 0.0f : 3.14159f;
            mZombiePhase = PHASE_ZOMBIQUARIUM_BACK_AND_FORTH;
        }
        mPhaseCounter = RandRangeInt(300, 1000);
        aBodyReanim->SetAnimRate(RandRangeFloat(15.0f, 20.0f));
    }

    // The tank is the rectangle x in [0, 680], y in [100, 400]; a heading that
    // would carry the zombie out of it is slowed right down.
    float aHeadingCos = cosf(mVelZ);
    float aHeadingSin = sinf(mVelZ);
    float aSpeed;
    if ((mPosX < 0.0f && aHeadingCos < 0.0f) || (mPosX > 680.0f && aHeadingCos > 0.0f))
    {
        aSpeed = 0.3f * mVelX;
        if (mPhaseCounter >= 100)
            mPhaseCounter = 100;
    }
    else if ((mPosY < 100.0f && aHeadingSin < 0.0f) || (mPosY > 400.0f && aHeadingSin > 0.0f))
    {
        aSpeed = 0.3f * mVelX;
        if (mPhaseCounter >= 100)
            mPhaseCounter = 100;
    }
    else if (mZombiePhase == PHASE_ZOMBIQUARIUM_ACCEL)
    {
        aSpeed = 0.5f;
    }
    else if (mZombiePhase == PHASE_ZOMBIQUARIUM_BACK_AND_FORTH)
    {
        // Bounce off the two side walls rather than turning at the edge.
        if (mPosX < 200.0f && aHeadingCos < 0.0f)
            mVelZ = 0.0f;
        if (mPosX > 550.0f && aHeadingCos > 0.0f)
            mVelZ = 3.14159f;
        aSpeed = 0.3f;
    }
    else if (mZombiePhase == PHASE_ZOMBIQUARIUM_DRIFT || mZombiePhase == PHASE_ZOMBIQUARIUM_BITE)
    {
        aSpeed = 0.05f;
    }
    else
    {
        aSpeed = 0.5f;
    }

    // The speed creeps up towards the target instead of jumping straight to it.
    mVelX = mVelX + 0.01f > aSpeed ? aSpeed : mVelX + 0.01f;
    mPosX = mPosX + mVelX * aHeadingCos;
    mPosY = mPosY + mVelX * aHeadingSin;

    if (!mBoard->HasLevelAwardDropped())
    {
        if (mSummonCounter > 0)
        {
            mSummonCounter--;
            if (mSummonCounter == 0)
            {
                // A sun token drifts out of the zombiquarium.
                mApp->PlayFoley(FOLEY_SPAWN_SUN);
                mBoard->AddCoin(mX + 50, mY + 40, COIN_SUN, COIN_MOTION_FROM_PLANT);
                mSummonCounter = RandRangeInt(1000, 1500);
            }
        }

        // Hunger costs ten health every hundred ticks.
        if (mZombieAge % 100 == 0)
        {
            TakeDamage(10, 8U);
            if (IsDeadOrDying())
                mApp->PlaySample(SOUND_ZOMBAQUARIUM_DIE, true);
        }
    }
}
// ==========================================================================
// Zombie::EatZombie(Zombie*)
// @001B406C  56 bytes
// ==========================================================================
Zombie * Zombie::EatZombie(Zombie *theZombie)
{
  // 8 is the standard chomp damage; flag 9 leaves no flash and ignores shields.
  theZombie->TakeDamage(8, 9u);
  Zombie *aResult = StartEating();

  // The eater swallows audibly once its prey's body is gone.
  if (theZombie->mBodyHealth <= 0)
    mApp->PlaySample(SOUND_GULP, true);

  return aResult;
}
// ==========================================================================
// Zombie::CheckIfPreyCaught(void)
// @001B40AC  278 bytes
// ==========================================================================
void Zombie::CheckIfPreyCaught()
{
    // Only the plain walking zombies hunt. Everything that is doing something
    // else -- bungee, gargantuar, zamboni, catapult, boss, a bouncing pogo or a
    // sled team -- is skipped outright.
    if (mZombieType == ZOMBIE_BUNGEE || mZombieType == ZOMBIE_REDEYE_GARGANTUAR
        || mZombieType == ZOMBIE_ZAMBONI || mZombieType == ZOMBIE_CATAPULT
        || mZombieType == ZOMBIE_GARGANTUAR || mZombieType == ZOMBIE_BOSS
        || IsBouncingPogo() || IsBobsledTeamWithSled())
        return;

    // Phases in which the zombie is mid-manoeuvre: vaulting, digging, rising
    // from the grave, reading the newspaper, being thrown or landing as an imp,
    // dancing, swimming, snorkelling, placing a ladder.
    if (mZombiePhase == PHASE_POLEVAULTER_PRE_VAULT || mZombiePhase == PHASE_POLEVAULTER_IN_VAULT
        || (unsigned int)(mZombiePhase - PHASE_DIGGER_RISING) <= 3
        || mZombiePhase == PHASE_RISING_FROM_GRAVE || mZombiePhase == PHASE_NEWSPAPER_MADDENING
        || (unsigned int)(mZombiePhase - PHASE_IMP_GETTING_THROWN) <= 1
        || (unsigned int)(mZombiePhase - PHASE_DANCER_RISING) <= 4
        || (unsigned int)(mZombiePhase - PHASE_DANCER_SNAPPING_FINGERS) <= 2
        || (unsigned int)(mZombiePhase - PHASE_DOLPHIN_WALKING_WITHOUT_DOLPHIN) <= 2
        || mZombiePhase == PHASE_LADDER_PLACING)
        return;

    // Heights that cannot eat either: hanging from a bungee, climbing a ladder,
    // moving in or out of the pool, held by a tangle kelp, or falling.
    if (mZombieHeight == HEIGHT_GETTING_BUNGEE_DROPPED || mZombieHeight == HEIGHT_UP_LADDER
        || (unsigned int)(mZombieHeight - HEIGHT_IN_TO_POOL) <= 1
        || IsTangleKelpTarget() || mZombieHeight == HEIGHT_FALLING
        || !mHasHead || IsFlying())
        return;

    // A chilled zombie takes twice as long between bites.
    int aEatInterval = mChilledCounter > 0 ? 16 : 8;
    if (mZombieAge % aEatInterval != 0)
        return;

    Zombie *aPrey = FindZombieTarget();
    if (aPrey != nullptr)
    {
        EatZombie(aPrey);
        return;
    }

    if (!mMindControlled)
    {
        Plant *aPlant = FindPlantTarget((ZombieAttackType)0);  // ATTACKTYPE_CHEW
        if (aPlant != nullptr)
        {
            EatPlant(aPlant);
            return;
        }
    }

    // Nothing in reach: an I, Zombie brain is the last chance, and otherwise the
    // zombie stops chewing.
    if ((!mApp->IsIZombieLevel() || !mBoard->mChallenge->IZombieEatBrain(this)) && mIsEating)
        StopEating();
}
// ==========================================================================
// Zombie::HitIceTrap(void)
// @001B41C4  156 bytes
// ==========================================================================
Reanimation * Zombie::HitIceTrap()
{
  // A zombie that is already cold, or already trapped in ice, freezes for
  // less time than one caught out in the open.
  bool aAlreadyCold = (mChilledCounter > 0 || mIceTrapCounter != 0);

  ApplyChill(true);
  if (!CanBeFrozen())
    return nullptr;

  if (mInPool)
    mIceTrapCounter = 300;
  else if (aAlreadyCold)
    mIceTrapCounter = RandRangeInt(300, 400);
  else
    mIceTrapCounter = RandRangeInt(400, 600);

  StopZombieSound();

  // A frozen balloon zombie stops spinning its propeller hat.
  if (mZombieType == ZOMBIE_BALLOON)
    BalloonPropellerHatSpin(false);

  // Freezing the boss mid-spit puts its fireball out.
  if (mZombiePhase == PHASE_BOSS_HEAD_SPIT)
    mBoard->RemoveParticleByType((ParticleEffect)76);  // PARTICLE_ZOMBIE_BOSS_FIREBALL

  TakeDamage(20, 1u);
  UpdateAnimSpeed();
  return nullptr;
}
// ==========================================================================
// Zombie::ApplyBurn(void)
// @001B4260  804 bytes
// ==========================================================================
void Zombie::ApplyBurn()
{
    if (mDead || mZombiePhase == PHASE_ZOMBIE_BURNED)
        return;

    // +0x34 == 25 is ZOMBIE_BOSS, not a phase. Hex-Rays printed the boss test
    // as a phase compare.
    if (mBodyHealth >= 1800 || mZombieType == ZOMBIE_BOSS)
    {
        TakeDamage(1800, 0x12u);
        return;
    }

    // +0x34 == 31 is ZOMBIE_SQUASH_HEAD. The head reanim is dropped only when
    // the squash head is already gone.
    if (mZombieType == ZOMBIE_SQUASH_HEAD && !mHasHead)
    {
        mApp->RemoveReanimation(mSpecialHeadReanimID);
        mSpecialHeadReanimID = REANIMATIONID_NULL;
    }

    if (mIceTrapCounter > 0)
        RemoveIceTrap();
    if (mButteredCounter > 0)
        mButteredCounter = 0;

    AttachmentDetachCrossFadeParticleType(mAttachmentID, PARTICLE_ZAMBONI_SMOKE, nullptr);
    BungeeDropPlant();

    // +0x38 is mZombiePhase. BIC #2 / BIC #8 are phase tests, not type tests.
    ZombiePhase aPhase = mZombiePhase;
    if ((aPhase & ~2) == PHASE_POLEVAULTER_IN_VAULT
        || (aPhase & ~2) == PHASE_ZOMBIE_DYING
        || aPhase == PHASE_IMP_GETTING_THROWN
        || (aPhase & ~8) == PHASE_DANCER_RISING
        || (unsigned)(aPhase - PHASE_DOLPHIN_INTO_POOL) <= 2
        || (unsigned)(aPhase - PHASE_DIGGER_TUNNELING) <= 3
        || mInPool)
    {
        DieWithLoot();
        if (mZombieType == ZOMBIE_BOBSLED)
            BobsledBurn();
        return;
    }

    // Types 19..20 and 27..32 have no charred body. A sled team, a flyer, or
    // a headless zombie takes the same path.
    ZombieType aType = mZombieType;
    bool aHasCharredBody = (unsigned)(aType - ZOMBIE_YETI) > 1
                        && (unsigned)(aType - ZOMBIE_PEA_HEAD) > 5;
    if (!aHasCharredBody || IsBobsledTeamWithSled() || IsFlying() || !mHasHead)
    {
        SetAnimRate(0.0f);
        Reanimation *aHeadReanim = mApp->ReanimationTryToGet(mSpecialHeadReanimID);
        if (aHeadReanim != nullptr)
            aHeadReanim->SetAnimRate(0.0f);

        mJustGotShotCounter = 0;
        mZombiePhase = PHASE_ZOMBIE_BURNED;
        mPhaseCounter = 300;
        DropLoot();
        if (mZombieType == ZOMBIE_BALLOON)
        {
            // ADDS #0x44 then BL FindReanimAttachment: the id is passed by address.
            ReanimatorTrackInstance *aHatTrack =
                mApp->ReanimationGet(mBodyReanimID)->GetTrackInstanceByName("hat");
            Reanimation *aHatReanim = FindReanimAttachment(aHatTrack->mAttachmentID);
            if (aHatReanim != nullptr)
                aHatReanim->SetAnimRate(0.0f);
        }
        if (mZombieType == ZOMBIE_BOBSLED)
            BobsledBurn();
        return;
    }

    float aBurnX = mPosX + 22.0f;
    float aBurnY = mPosY - 10.0f;
    ReanimationType aBurnReanimType = REANIM_ZOMBIE_CHARRED;

    switch (mZombieType)
    {
        case ZOMBIE_BALLOON:
            aBurnY += 31.0f;
            break;
        case ZOMBIE_IMP:
            aBurnReanimType = REANIM_ZOMBIE_CHARRED_IMP;
            aBurnX -= 6.0f;
            break;
        case ZOMBIE_DIGGER:
            aBurnReanimType = REANIM_ZOMBIE_CHARRED_DIGGER;
            if (IsWalkingBackwards())
                aBurnX += 14.0f;
            break;
        case ZOMBIE_ZAMBONI:
            aBurnReanimType = REANIM_ZOMBIE_CHARRED_ZAMBONI;
            aBurnY -= 16.0f;
            aBurnX += 61.0f;
            break;
        case ZOMBIE_CATAPULT:
            aBurnReanimType = REANIM_ZOMBIE_CHARRED_CATAPULT;
            aBurnY -= 20.0f;
            aBurnX -= 36.0f;
            break;
        default:
            break;
    }
    if (mZombieType == ZOMBIE_GARGANTUAR || mZombieType == ZOMBIE_REDEYE_GARGANTUAR)
    {
        aBurnReanimType = REANIM_ZOMBIE_CHARRED_GARGANTUAR;
        aBurnX -= 15.0f;
        aBurnY -= 10.0f;
    }

    Reanimation *aCharred = mApp->AddReanimation(aBurnX, aBurnY, mRenderOrder,
                                                 aBurnReanimType);
    float aRateScale = RandRangeFloat(0.9f, 1.1f);
    aCharred->SetAnimRate(aRateScale * aCharred->mAnimRate);

    if (mZombiePhase == PHASE_DIGGER_WALKING_WITHOUT_AXE)
        aCharred->SetFramesForLayer("anim_crumble_noaxe");
    else if (mZombieType == ZOMBIE_DIGGER)
        aCharred->SetFramesForLayer("anim_crumble");
    else if ((mZombieType == ZOMBIE_GARGANTUAR || mZombieType == ZOMBIE_REDEYE_GARGANTUAR)
             && !mHasObject)
    {
        aCharred->SetImageOverride("impblink", IMAGE_BLANK);
        aCharred->SetImageOverride("imphead", IMAGE_BLANK);
    }

    // Overlay writes are m00/m11 and m02/m12 (+0x34/+0x44/+0x3C/+0x48), not m20/m21.
    if (mScaleZombie != 1.0f)
    {
        float aScaleDelta = 1.0f - mScaleZombie;
        aCharred->mOverlayMatrix.m00 = mScaleZombie;
        aCharred->mOverlayMatrix.m11 = mScaleZombie;
        aCharred->mOverlayMatrix.m02 += aScaleDelta * 20.0f;
        aCharred->mOverlayMatrix.m12 += aScaleDelta * 120.0f;
        aCharred->OverrideScale(mScaleZombie, mScaleZombie);
    }
    if (IsWalkingBackwards())
    {
        aCharred->OverrideScale(-mScaleZombie, mScaleZombie);
        aCharred->mOverlayMatrix.m02 += mScaleZombie * 60.0f;
    }

    DieWithLoot();
    if (mZombieType == ZOMBIE_BOBSLED)
        BobsledBurn();
}
// ==========================================================================
// Zombie::BobsledBurn(void)
// @001B45B0  60 bytes
// ==========================================================================
int Zombie::BobsledBurn()
{
    if (!IsBobsledTeamWithSled())
        return 0;

    // The whole team burns: the sled's leader first, then the riders behind it.
    Zombie *aLeader = this;
    if (mRelatedZombieID != 0)
        aLeader = mBoard->ZombieGet(mRelatedZombieID);
    aLeader->ApplyBurn();

    for (int i = 0; i < 3; i++)
    {
        Zombie *aFollower = mBoard->ZombieGet(mFollowerZombieID[i]);
        aFollower->ApplyBurn();
    }
    return 0;
}
// ==========================================================================
// Zombie::UpdateZombieGargantuar(void)
// @001B45EC  890 bytes
// ==========================================================================
void Zombie::UpdateZombieGargantuar()
{
    if (mZombiePhase == PHASE_GARGANTUAR_SMASHING)
    {
        Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
        if (aBodyReanim->ShouldTriggerTimedEvent(0.64f))
        {
            Plant *aPlant = FindPlantTarget((ZombieAttackType)0);  // ATTACKTYPE_CHEW
            if (aPlant != nullptr)
            {
                // A spikerock fights back: it wounds the gargantuar and is only
                // squashed once it is dead.
                if (aPlant->mSeedType != SEED_SPIKEROCK
                    || (TakeDamage(20, 32U), aPlant->SpikeRockTakeDamage(),
                        aPlant->mPlantHealth <= 0))
                {
                    SquishAllInSquare(aPlant->mPlantCol, aPlant->mRow, (ZombieAttackType)0);
                }
            }

            if (mApp->IsScaryPotterLevel())
            {
                int aGridX = mBoard->PixelToGridX((int)mPosX, (int)mPosY);
                GridItem *aScaryPot = mBoard->GetScaryPotAt(aGridX, mRow);
                if (aScaryPot != nullptr)
                    mBoard->mChallenge->ScaryPotterOpenPot(aScaryPot);
            }

            if (mApp->IsIZombieLevel())
            {
                GridItem *aBrain = mBoard->mChallenge->IZombieGetBrainTarget(this);
                if (aBrain != nullptr)
                    mBoard->mChallenge->IZombieSquishBrain(aBrain);
            }

            mApp->PlayFoley(FOLEY_THUMP);
            mBoard->ShakeBoard(0, 3);
        }

        if (aBodyReanim->mLoopCount > 0)
        {
            mZombiePhase = PHASE_ZOMBIE_NORMAL;
            {
                StartWalkAnim(20);
                return;
            }
        }
        return;
    }

    // How far the gargantuar stands from the front of the lawn, which decides
    // how far the imp it throws is carried.
    float aThrowingDistance = mPosX - 360.0f;
    if (mZombiePhase == PHASE_GARGANTUAR_THROWING)
    {
        Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
        if (aBodyReanim->ShouldTriggerTimedEvent(0.74f))
        {
            mHasObject = false;
            ReanimShowPrefix("Zombie_imp", -1);                    // RENDER_GROUP_HIDDEN
            ReanimShowTrack("Zombie_gargantuar_whiterope", -1);    // RENDER_GROUP_HIDDEN
            mApp->PlayFoley(FOLEY_SWING);

            Zombie *aImp = mBoard->AddZombie(ZOMBIE_IMP, mFromWave, false);
            if (aImp == nullptr)
                return;

            float aThrowDistance = 40.0f;
            if (mBoard->StageHasRoof())
            {
                aThrowDistance = -140.0f;
                aThrowingDistance -= 180.0f;
            }
            if (aThrowingDistance >= aThrowDistance)
            {
                if (aThrowingDistance > 140.0f)
                    aThrowDistance = aThrowingDistance - RandRangeFloat(0.0f, 100.0f);
                else
                    aThrowDistance = aThrowingDistance;
            }

            aImp->mPosX = mPosX - 133.0f;
            aImp->mPosY = GetPosYBasedOnRow(mRow);
            aImp->SetRow(mRow);
            aImp->mVariant = false;
            aImp->mRenderOrder = mRenderOrder + 1;
            aImp->mZombiePhase = PHASE_IMP_GETTING_THROWN;
            aImp->mChilledCounter = mChilledCounter;
            aImp->mVelZ = aThrowDistance * 0.0083333f;
            aImp->mAltitude = 88.0f;
            aImp->mVelX = 3.0f;
            aImp->PlayZombieReanim("anim_thrown", REANIM_PLAY_ONCE_AND_HOLD, 0, 18.0f);
            aImp->UpdateReanim();
            mApp->PlayFoley(FOLEY_IMP);
        }

        if (aBodyReanim->mLoopCount > 0)
        {
            mZombiePhase = PHASE_ZOMBIE_NORMAL;
            {
                StartWalkAnim(20);
                return;
            }
        }
        return;
    }

    if (!IsImmobilizied() && mHasHead)
    {
        // Half health and still holding its imp: wind up for a throw instead.
        if (mHasObject && mBodyHealth < mBodyMaxHealth / 2 && aThrowingDistance > 40.0f)
        {
            mZombiePhase = PHASE_GARGANTUAR_THROWING;
            {
                PlayZombieReanim("anim_throw", REANIM_PLAY_ONCE_AND_HOLD, 20, 24.0f);
                return;
            }
        }

        // Otherwise look for something worth smashing: a plant, a scary pot or
        // an I, Zombie brain.
        bool aCanSmash = FindPlantTarget((ZombieAttackType)0) != nullptr;
        if (!aCanSmash && mApp->IsScaryPotterLevel())
        {
            int aGridX = mBoard->PixelToGridX((int)mPosX, (int)mPosY);
            aCanSmash = mBoard->GetScaryPotAt(aGridX, mRow) != nullptr;
        }
        else if (!aCanSmash && mApp->IsIZombieLevel())
        {
            aCanSmash = mBoard->mChallenge->IZombieGetBrainTarget(this) != nullptr;
        }

        if (aCanSmash)
        {
            mZombiePhase = PHASE_GARGANTUAR_SMASHING;
            mApp->PlayFoley(FOLEY_LOW_GROAN);
            {
                PlayZombieReanim("anim_smash", REANIM_PLAY_ONCE_AND_HOLD, 20, 16.0f);
                return;
            }
        }
    }

    return;
}
// ==========================================================================
// Zombie::UpdateActions(void)
// @001B4968  464 bytes
// ==========================================================================
float Zombie::UpdateActions()
{
    // Each zombie height and each zombie type has its own update, and they are
    // run as a flat chain of independent tests -- every one of them re-reads
    // mZombieHeight / mZombieType rather than falling through.
    if (mZombieHeight == 6)  // HEIGHT_UP_LADDER
        UpdateClimbingLadder();
    if (mZombieHeight == 10)  // HEIGHT_ZOMBIQUARIUM
        UpdateZombiquarium();
    if ((unsigned int)(mZombieHeight - 1) <= 1 || mInPool)
    {
        UpdateZombiePool();
        if ((unsigned int)(mZombieHeight - 4) <= 1)
            UpdateZombieHighGround();
    }
    else if ((unsigned int)(mZombieHeight - 4) <= 1)
    {
        UpdateZombieHighGround();
    }
    if (mZombieHeight == 7)  // HEIGHT_FALLING
        UpdateZombieFalling();
    if (mZombieHeight == 8)  // HEIGHT_CHIMNEY
        UpdateZombieChimney();

    if (mZombieType == ZOMBIE_POLEVAULTER)
        UpdateZombiePolevaulter();
    if (mZombieType == ZOMBIE_CATAPULT)
        UpdateZombieCatapult();
    if (mZombieType == ZOMBIE_DOLPHIN_RIDER)
        UpdateZombieDolphinRider();
    if (mZombieType == ZOMBIE_SNORKEL)
        UpdateZombieSnorkel();
    if (mZombieType == ZOMBIE_BALLOON)
        UpdateZombieFlyer();
    if (mZombieType == ZOMBIE_NEWSPAPER)
        UpdateZombieNewspaper();
    if (mZombieType == ZOMBIE_DIGGER)
        UpdateZombieDigger();
    if (mZombieType == ZOMBIE_JACK_IN_THE_BOX)
        UpdateZombieJackInTheBox();
    if (mZombieType == ZOMBIE_GARGANTUAR || mZombieType == ZOMBIE_REDEYE_GARGANTUAR)
        UpdateZombieGargantuar();
    if (mZombieType == ZOMBIE_BOBSLED)
        UpdateZombieBobsled();
    if (mZombieType == ZOMBIE_ZAMBONI)
        UpdateZamboni();
    if (mZombieType == ZOMBIE_LADDER)
        UpdateLadder();
    if (mZombieType == ZOMBIE_YETI)
        UpdateYeti();
    if (mZombieType == ZOMBIE_DANCER)
        UpdateZombieDancer();
    if (mZombieType == ZOMBIE_BACKUP_DANCER)
        UpdateZombieBackupDancer();
    if (mZombieType == ZOMBIE_IMP)
        UpdateZombieImp();
    if (mZombieType == ZOMBIE_PEA_HEAD)
        UpdateZombiePeaHead();
    if (mZombieType == ZOMBIE_JALAPENO_HEAD)
        UpdateZombieJalapenoHead();
    if (mZombieType == ZOMBIE_GATLING_HEAD)
        UpdateZombieGatlingHead();
    if (mZombieType == ZOMBIE_SQUASH_HEAD)
        return UpdateZombieSquashHead();

    return 0.0f;
}
// ==========================================================================
// Zombie::UpdateBoss(void)
// @001B4B38  1098 bytes
// ==========================================================================
void Zombie::UpdateBoss()
{
    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);

    // During the level-intro cutscene the boss only rumbles in the background.
    if (mApp->mGameScene == SCENE_LEVEL_INTRO)
    {
        if (aBodyReanim->ShouldTriggerTimedEvent(0.24f)
            || aBodyReanim->ShouldTriggerTimedEvent(0.79f))
        {
            mApp->PlayFoley(FOLEY_THUMP);
            mBoard->ShakeBoard(1, 4);
        }
        return;
    }

    Reanimation *aHeadReanim = mApp->ReanimationGet(mSpecialHeadReanimID);
    UpdateBossFireball();

    if (mIceTrapCounter != 0)
    {
        aHeadReanim->SetAnimRate(0.0f);
    }
    else
    {
        // The four attack cooldowns tick down while the boss is not frozen.
        if (mSummonCounter > 0)
            mSummonCounter--;
        if (mBossBungeeCounter > 0)
            mBossBungeeCounter--;
        if (mBossStompCounter > 0)
            mBossStompCounter--;
        if (mBossHeadCounter > 0)
            mBossHeadCounter--;

        if (mChilledCounter <= 0)
        {
            if (aHeadReanim->mAnimRate == 0.0f)
                aHeadReanim->SetAnimRate(12.0f);
        }
        else
        {
            aHeadReanim->SetAnimRate(6.0f);
        }
    }

    switch (mZombiePhase)
    {
        case PHASE_BOSS_ENTER:
            BossPlayIdle();
            return;

        case PHASE_BOSS_IDLE:
            // One point of body health left means the boss is on its way out.
            if (mBodyHealth == 1)
            {
                PlayDeathAnim(0);
                return;
            }
            if (mPhaseCounter > 0)
                return;

            {
                int aDamageIndex = GetBodyDamageIndex();
                if (aDamageIndex != mBossMode)
                {
                    mBossMode = aDamageIndex;
                    if (aDamageIndex != 1)
                    {
                        BossRVAttack();
                        return;
                    }
                }
                else
                {
                    if (mBossStompCounter == 0)
                    {
                        BossStompAttack();
                        return;
                    }
                    if (mBossBungeeCounter != 0)
                    {
                        if (mBossHeadCounter != 0)
                        {
                            if (mSummonCounter != 0)
                                mPhaseCounter = RandRangeInt(100, 200);
                            else
                                BossSpawnAttack();
                        }
                        else
                        {
                            BossHeadAttack();
                        }
                        return;
                    }

                    // Nothing else is pending: once in a while send the bungees,
                    // otherwise drop the RV (more often in adventure mode).
                    if (Rand(mApp->IsAdventureMode() ? 4 : 2) == 0)
                    {
                        mBossBungeeCounter = RandRangeInt(4000, 5000);
                        BossRVAttack();
                        return;
                    }
                }
                BossBungeeAttack();
                return;
            }

        case PHASE_BOSS_SPAWNING:
            if (aBodyReanim->ShouldTriggerTimedEvent(0.6f))
                BossSpawnContact();
            break;

        case PHASE_BOSS_STOMPING:
            // The stomp lands later when it has a target two rows in.
            if (aBodyReanim->ShouldTriggerTimedEvent(mTargetRow > 1 ? 0.55f : 0.5f))
                BossStompContact();
            break;

        case PHASE_BOSS_BUNGEES_ENTER:
            if (aBodyReanim->ShouldTriggerTimedEvent(0.4f))
                BossBungeeSpawn();
            return;

        case PHASE_BOSS_BUNGEES_DROP:
            if (BossAreBungeesDone())
                BossBungeeLeave();
            return;

        case PHASE_BOSS_BUNGEES_LEAVE:
            break;

        case PHASE_BOSS_DROP_RV:
            if (aBodyReanim->ShouldTriggerTimedEvent(0.65f))
                BossRVLanding();
            break;

        case PHASE_BOSS_HEAD_ENTER:
            if (GetBodyDamageIndex() == 2 && aBodyReanim->ShouldTriggerTimedEvent(0.37f))
                ApplyBossSmokeParticles(true);
            if (aBodyReanim->ShouldTriggerTimedEvent(0.55f))
                mApp->PlayFoley(FOLEY_HYDRAULIC);
            if (aBodyReanim->mLoopCount > 0)
            {
                mZombiePhase = PHASE_BOSS_HEAD_IDLE_BEFORE_SPIT;
                PlayZombieReanim("anim_head_idle", REANIM_LOOP, 0, 12.0f);
                mPhaseCounter = 500;
            }
            return;

        case PHASE_BOSS_HEAD_IDLE_BEFORE_SPIT:
            if (mBodyHealth != 1)
            {
                if (mPhaseCounter == 0)
                    BossHeadSpit();
                return;
            }
            BossStartDeath();
            return;

        case PHASE_BOSS_HEAD_IDLE_AFTER_SPIT:
            if (mBodyHealth != 1)
            {
                if (mPhaseCounter == 0)
                {
                    mZombiePhase = PHASE_BOSS_HEAD_LEAVE;
                    PlayZombieReanim("anim_head_leave", REANIM_PLAY_ONCE_AND_HOLD, 0, 12.0f);
                }
                return;
            }
            BossStartDeath();
            return;

        case PHASE_BOSS_HEAD_SPIT:
            if (aBodyReanim->ShouldTriggerTimedEvent(0.37f))
                BossHeadSpitEffect();
            if (aBodyReanim->ShouldTriggerTimedEvent(0.42f))
                BossHeadSpitContact();
            if (aBodyReanim->mLoopCount > 0)
            {
                Reanimation *aHeadIdleReanim = mApp->ReanimationTryToGet(mSpecialHeadReanimID);
                aHeadIdleReanim->PlayReanim("anim_idle", REANIM_LOOP, 20, 18.0f);
                mZombiePhase = PHASE_BOSS_HEAD_IDLE_AFTER_SPIT;
                PlayZombieReanim("anim_head_idle", REANIM_LOOP, 0, 12.0f);
                mPhaseCounter = 300;
            }
            return;

        case PHASE_BOSS_HEAD_LEAVE:
            if (aBodyReanim->ShouldTriggerTimedEvent(0.23f))
            {
                mChilledCounter = 0;
                UpdateAnimSpeed();
            }
            if (aBodyReanim->ShouldTriggerTimedEvent(0.48f)
                || aBodyReanim->ShouldTriggerTimedEvent(0.8f))
            {
                mApp->PlayFoley(FOLEY_THUMP);
            }
            if (aBodyReanim->mLoopCount > 0)
            {
                ApplyBossSmokeParticles(false);
                BossPlayIdle();
            }
            return;

        default:
            return;
    }

    if (aBodyReanim->mLoopCount > 0)
        BossPlayIdle();
}
// ==========================================================================
// Zombie::IsFireResistant(void)
// @001B4F98  36 bytes
// ==========================================================================
int Zombie::IsFireResistant()
{
  // The catapult carries a wooden machine and the zamboni is a vehicle.
  if (mZombieType == ZOMBIE_CATAPULT || mZombieType == ZOMBIE_ZAMBONI)
    return 1;

  // The shield type itself is the answer for 1 (SHIELDTYPE_DOOR); the two
  // metal shields, 3 (SHIELDTYPE_LADDER) and 4 (SHIELDTYPE_TRASHCAN), also
  // resist fire, and nothing else does.
  if (mShieldType == 1)
    return 1;

  return (mShieldType == 3 || mShieldType == 4);
}
// ==========================================================================
// Zombie::EnableMustache(bool)
// @001B4FBC  146 bytes
// ==========================================================================
void Zombie::EnableMustache(bool theEnable)
{
    // Only a plain, headed zombie gets the mustache: not a UI zombie (mFromWave
    // -3) and not one of the six "head" variants (types 27..32).
    if (mFromWave == -3 || !mHasHead || (unsigned int)(mZombieType - ZOMBIE_PEA_HEAD) <= 5)
        return;

    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr || !aBodyReanim->TrackExists("zombie_mustache"))
        return;

    if (theEnable)
    {
        aBodyReanim->AssignRenderGroupToPrefix("Zombie_mustache", 0);
        int aMustacheType = RandRangeInt(1, 3);
        if (aMustacheType == 1)
            aBodyReanim->SetImageOverride("Zombie_mustache", nullptr);
        else if (aMustacheType == 2)
            aBodyReanim->SetImageOverride("Zombie_mustache", IMAGE_REANIM_ZOMBIE_MUSTACHE2);
        else if (aMustacheType == 3)
            aBodyReanim->SetImageOverride("Zombie_mustache", IMAGE_REANIM_ZOMBIE_MUSTACHE3);
        return;
    }

    aBodyReanim->AssignRenderGroupToPrefix("Zombie_mustache", -1);
}
// ==========================================================================
// Zombie::EnableFuture(bool)
// @001B5068  132 bytes
// ==========================================================================
void Zombie::EnableFuture(bool theEnable)
{
    // Same eligibility as the mustache, minus the head test: not a UI zombie
    // (mFromWave -3) and not one of the six "head" variants (types 27..32).
    if (mFromWave == -3 || (unsigned int)(mZombieType - ZOMBIE_PEA_HEAD) <= 5)
        return;

    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr)
        return;
    if (aBodyReanim->mReanimationType != REANIM_ZOMBIE)
        return;

    Sexy::Image *aHeadImage = nullptr;
    if (theEnable)
    {
        // Which of the four sunglasses frames a zombie wears is its board id
        // modulo four.
        switch (mBoard->ZombieGetID(this) & 3)
        {
            case 1:  aHeadImage = IMAGE_REANIM_ZOMBIE_HEAD_SUNGLASSES2; break;
            case 2:  aHeadImage = IMAGE_REANIM_ZOMBIE_HEAD_SUNGLASSES3; break;
            case 3:  aHeadImage = IMAGE_REANIM_ZOMBIE_HEAD_SUNGLASSES4; break;
            default: aHeadImage = IMAGE_REANIM_ZOMBIE_HEAD_SUNGLASSES1; break;
        }
    }

    aBodyReanim->SetImageOverride("anim_head1", aHeadImage);
}
// ==========================================================================
// Zombie::EnableDanceMode(bool)
// @001B5108  54 bytes
// ==========================================================================
void Zombie::EnableDanceMode(bool theEnable)
{
    (void)theEnable;
    // UI and cutscene zombies (from-wave -3 and -2) stay as they are.
    if ((unsigned int)(mFromWave + 3) <= 1)
        return;

    if (ZombieNotWalking())
        return;

    if (IsDeadOrDying() != 0)
        return;

    // A plain zombie, a flag zombie, or a bucket zombie starts the dance walk.
    if ((mZombieType & ~2) == 0 || mZombieType == ZOMBIE_PAIL)
        {
            StartWalkAnim(0);
            return;
        }

    return;
}
// ==========================================================================
// Zombie::SetupWaterTrack(char const*)
// @001B5140  38 bytes
// ==========================================================================
void Zombie::SetupWaterTrack(char const *theTrackName)
{
    ReanimatorTrackInstance *aTrack = mApp->ReanimationGet(mBodyReanimID)->GetTrackInstanceByName(theTrackName);
    aTrack->mIgnoreClipRect = true;
    aTrack->mIgnoreColorOverride = true;
    aTrack->mIgnoreExtraAdditiveColor = true;
}
// ==========================================================================
// Zombie::LoadPlainZombieReanim(void)
// @001B5168  174 bytes
// ==========================================================================
Reanimation * Zombie::LoadPlainZombieReanim()
{
    // The plain body's attack window, the same one the plain zombie definition
    // installs.
    mZombieAttackRect.mX = 20;
    mZombieAttackRect.mY = 0;
    mZombieAttackRect.mWidth = 50;
    mZombieAttackRect.mHeight = 115;

    Reanimation *aBodyReanim = mApp->ReanimationTryToGet(mBodyReanimID);
    if (aBodyReanim == nullptr)
        return aBodyReanim;

    SetupReanimLayers(aBodyReanim, mZombieType);

    if (mBoard != nullptr)
    {
        EnableMustache(mBoard->mMustacheMode);
        EnableFuture(mBoard->mFutureMode);
    }

    // A ducky tube -- or any zombie that ends up on a pool row -- gets its
    // water tracks switched on.
    if ((mBoard != nullptr && mBoard->mPlantRow[mRow] == 2)  // PLANTROW_POOL
        || mZombieType == ZOMBIE_DUCKY_TUBE)
    {
        ReanimShowPrefix("zombie_duckytube", 0);
        ReanimIgnoreClipRect("Zombie_duckytube", true);
        ReanimIgnoreClipRect("Zombie_outerarm_hand", true);
        ReanimIgnoreClipRect("Zombie_innerarm3", true);
        SetupWaterTrack("Zombie_whitewater");
        SetupWaterTrack("Zombie_whitewater2");
        return aBodyReanim;
    }

    return aBodyReanim;
}
// ==========================================================================
// Zombie::ZombieInitialize(int,ZombieType,bool,Zombie*,int,bool)
// @001B5230  6172 bytes
// ==========================================================================
void Zombie::ZombieInitialize(int theRow, ZombieType theType, bool theVariant, Zombie *theParentZombie, int theFromWave, bool theVisible)
{
    // 303000 is RENDER_LAYER_ZOMBIE. The third argument of MakeRenderOrder is
    // the offset inside that layer; 4 is where a plain zombie sits.
    int aRenderLayer = 303000;
    int aRenderOffset = 4;
    int aDelay = 0;

    mRow = theRow;
    mFromWave = theFromWave;
    mPosX = 780.0f + Rand(40);
    mPosY = GetPosYBasedOnRow(theRow);
    mVariant = theVariant;
    mWidth = 120;
    mHeight = 120;
    mHasHead = true;
    mHasArm = true;
    mZombieType = theType;
    mVelX = 0.0f;
    mVelZ = 0.0f;
    mFrame = 0;
    mPrevFrame = 0;
    mIsEating = false;
    mJustGotShotCounter = 0;
    mShieldJustGotShotCounter = 0;
    mShieldRecoilCounter = 0;
    mChilledCounter = 0;
    mIceTrapCounter = 0;
    mButteredCounter = 0;
    mMindControlled = false;
    mBlowingAway = false;
    mHasObject = false;
    mInPool = false;
    mOnHighGround = false;
    mHelmType = 0;                              // HELMTYPE_NONE
    mShieldType = 0;                            // SHIELDTYPE_NONE
    mYuckyFace = false;
    mYuckyFaceCounter = 0;
    mWalnutDeath = false;
    mZombieInitWord = 0;
    mAnimCounter = 0;
    mGroanCounter = RandRangeInt(400, 500);
    mAnimTicksPerFrame = 12;
    mAnimFrames = 12;
    mZombieRect.mHeight = 115;
    mZombieAttackRect.mHeight = 115;
    mZombieAge = 0;
    mZombiePhase = PHASE_ZOMBIE_NORMAL;
    mZombieHeight = 0;
    mPhaseCounter = 0;
    mHitUmbrella = false;
    mDroppedLoot = false;
    mRelatedZombieID = (ZombieID)0;
    mZombieRect.mY = 0;
    mZombieAttackRect.mY = 0;
    mCachedZombieRect.mX = 0;
    mCachedZombieRect.mY = 0;
    mCachedZombieRect.mWidth = 0;
    mCachedZombieRect.mHeight = 0;
    mPlayingSong = false;
    mFlatTires = false;
    mShieldHealth = 0;
    mHelmHealth = 0;
    mFlyingHealth = 0;
    mAttachmentID = 0;
    mSummonCounter = 0;
    mZombieRect.mX = 36;
    mZombieRect.mWidth = 42;
    mZombieAttackRect.mX = 50;
    mZombieAttackRect.mWidth = 20;
    mTargetCol = -1;
    mZombieFade = -1;
    mUseLadderCol = -1;
    mBossStompCounter = -1;
    mBossBungeeCounter = -1;
    mBossHeadCounter = -1;
    mBodyReanimID = (ReanimationID)0;
    mAltitude = 0.0f;
    mOriginalAnimRate = 0.0f;
    mTargetPlantID = (PlantID)0;
    mBossMode = 0;
    mBossFireBallReanimID = (ReanimationID)0;
    mSpecialHeadReanimID = (ReanimationID)0;
    mTargetRow = -1;
    mFireballRow = -1;
    mIsFireBall = false;
    mMoweredReanimID = (ReanimationID)0;
    mLastPortalX = -1;
    mVisible = theVisible;
    mFollowerZombieID[0] = (ZombieID)0;
    mFollowerZombieID[1] = (ZombieID)0;
    mFollowerZombieID[2] = (ZombieID)0;
    mFollowerZombieID[3] = (ZombieID)0;
    mScaleZombie = 1.0f;

    // A flag wave spawns its zombies further right so they take longer to arrive.
    if (mBoard != nullptr && mBoard->IsFlagWave(mFromWave))
        mPosX += 40.0f;

    PickRandomSpeed();
    mBodyHealth = 270;
    ZombieDefinition *aZombieDef = GetZombieDefinition(mZombieType);
    if (aZombieDef->mReanimationType != REANIM_NONE)
        LoadReanim(aZombieDef->mReanimationType);

    // The types whose setup does not depend on anything but the type itself.
    switch (theType)
    {
    case ZOMBIE_NORMAL:
    case ZOMBIE_DUCKY_TUBE:
        aRenderOffset = 4;
        LoadPlainZombieReanim();
        return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);

    case ZOMBIE_TRAFFIC_CONE:
        aRenderOffset = 4;
        LoadPlainZombieReanim();
        ReanimShowPrefix("anim_cone", 0);
        ReanimShowPrefix("anim_hair", -1);
        mHelmType = 1;                          // HELMTYPE_TRAFFIC_CONE
        mHelmHealth = 370;
        return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
    case ZOMBIE_PAIL:
        LoadPlainZombieReanim();
        ReanimShowPrefix("anim_bucket", 0);
        ReanimShowPrefix("anim_hair", -1);
        mHelmType = 2;                          // HELMTYPE_PAIL
        mHelmHealth = 1100;
        aRenderOffset = 4;
        return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);

    case ZOMBIE_DOOR:
        mShieldType = 1;                        // SHIELDTYPE_DOOR
        mShieldHealth = 1100;
        aRenderOffset = 4;
        LoadPlainZombieReanim();
        AttachShield();
        return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
    case ZOMBIE_TRASHCAN:
        mShieldType = 4;                        // SHIELDTYPE_TRASHCAN
        mShieldHealth = 800;
        aRenderOffset = 4;
        LoadPlainZombieReanim();
        AttachShield();
        return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);

    case ZOMBIE_YETI:
        mBodyHealth = 1350;
        aRenderOffset = 4;
        mPhaseCounter = RandRangeInt(1500, 2000);
        mHasObject = true;
        mZombieAttackRect.mX = 20;
        mZombieAttackRect.mY = 0;
        mZombieAttackRect.mWidth = 50;
        mZombieAttackRect.mHeight = 115;
        return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
    case ZOMBIE_LADDER:
        mBodyHealth = 500;
        mShieldHealth = 500;
        mShieldType = 3;                        // SHIELDTYPE_LADDER
        mZombieAttackRect.mX = 10;
        mZombieAttackRect.mY = 0;
        mZombieAttackRect.mWidth = 50;
        mZombieAttackRect.mHeight = 115;
        if (IsOnBoard())
        {
            mZombiePhase = PHASE_LADDER_CARRYING;
            StartWalkAnim(0);
        }
        aRenderOffset = 4;
        AttachShield();
        return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
    default:
        break;
    }

    if (theType != ZOMBIE_BUNGEE)
    {
        switch (theType)
        {
        case ZOMBIE_FOOTBALL:
            mZombieRect.mWidth = 57;
            mZombieRect.mX = 50;
            mZombieRect.mHeight = 115;
            mZombieRect.mY = 0;
            aRenderOffset = 4;
            ReanimShowPrefix("anim_hair", -1);
            mVariant = false;
            mHelmType = 3;                      // HELMTYPE_FOOTBALL
            mHelmHealth = 1400;
            mAnimTicksPerFrame = 6;
            return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
        case ZOMBIE_DIGGER:
            mZombieRect.mX = 50;
            mZombieRect.mWidth = 28;
            mZombieRect.mHeight = 115;
            mHelmType = 4;                      // HELMTYPE_DIGGER
            mHelmHealth = 100;
            mVariant = false;
            mZombieRect.mY = 0;
            mHasObject = true;
            (mApp->ReanimationGet(mBodyReanimID))->SetTruncateDisappearingFrames(nullptr, false);
            if (IsOnBoard())
            {
                mZombiePhase = PHASE_DIGGER_TUNNELING;
                AddAttachedParticle(60, 100, (ParticleEffect)33);   // PARTICLE_DIGGER_RISE
                PlayZombieReanim("anim_dig", REANIM_LOOP_FULL_LAST_FRAME, 0, 12.0f);
                PickRandomSpeed();
                aRenderOffset = 7;
            }
            else
            {
                aRenderOffset = 4;
                mZombiePhase = PHASE_DIGGER_CUTSCENE;
            }
            return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
        case ZOMBIE_POLEVAULTER:
            mBodyHealth = 500;
            mAnimTicksPerFrame = 6;
            mZombiePhase = PHASE_POLEVAULTER_PRE_VAULT;
            mHasObject = true;
            mVariant = false;
            mPosX = 870.0f + Rand(10);
            if (IsOnBoard())
            {
                PlayZombieReanim("anim_run", REANIM_LOOP, 0, 0.0f);
                PickRandomSpeed();
            }
            aRenderOffset = 4;
            if (mApp->IsWallnutBowlingLevel())
            {
                mZombieAttackRect.mX = -229;
                mZombieAttackRect.mY = 0;
                mZombieAttackRect.mWidth = 270;
            }
            else
            {
                mZombieAttackRect.mY = 0;
                mZombieAttackRect.mX = -29;
                mZombieAttackRect.mWidth = 70;
            }
            mZombieAttackRect.mHeight = 115;
            return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
        case ZOMBIE_DOLPHIN_RIDER:
            mBodyHealth = 500;
            mAnimTicksPerFrame = 6;
            mZombiePhase = PHASE_DOLPHIN_WALKING;
            mVariant = false;
            if (IsOnBoard())
            {
                PlayZombieReanim("anim_walkdolphin", REANIM_LOOP, 0, 0.0f);
                PickRandomSpeed();
            }
            SetupWaterTrack("Zombie_dolphinrider_whitewater");
            aRenderOffset = 4;
            SetupWaterTrack("Zombie_dolphinrider_dolphininwater");
            return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
        default:
            break;
        }

        // Gargantuars share one body between the normal and the red-eyed kind.
        if (theType == ZOMBIE_GARGANTUAR || theType == ZOMBIE_REDEYE_GARGANTUAR)
        {
            mBodyHealth = 3000;
            if (mApp->IsCoopMode() && mApp->IsWallnutBowlingLevel())
                mBodyHealth = 7200;
            mAnimFrames = 24;
            mAnimTicksPerFrame = 8;
            mWidth = 180;
            mHeight = 180;
            mPosX = 845.0f + Rand(10);
            mVariant = false;
            mZombieRect.mX = -17;
            mZombieRect.mY = -38;
            mZombieRect.mWidth = 125;
            mZombieRect.mHeight = 154;
            mZombieAttackRect.mY = -38;
            mZombieAttackRect.mX = -30;
            mZombieAttackRect.mWidth = 89;
            mZombieAttackRect.mHeight = 154;
            mHasObject = true;

            // Level 48 keeps the plain telephone pole; everywhere else the pole
            // is usually replaced by a duck or a little zombie.
            int aVariant = Rand(100);
            Reanimation *aBodyReanim;
            if (!IsOnBoard() || mBoard->mLevel == 48)
            {
                aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
            }
            else if (aVariant > 9)
            {
                aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
                if (aVariant <= 34)
                {
                    // The pole becomes a rubber duck.
                    aBodyReanim->SetImageOverride(
                        "Zombie_gargantuar_telephonepole",
                        IMAGE_REANIM_ZOMBIE_GARGANTUAR_DUCKXING);
                }
            }
            else
            {
                aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
                // The pole becomes a little zombie.
                aBodyReanim->SetImageOverride(
                    "Zombie_gargantuar_telephonepole",
                    IMAGE_REANIM_ZOMBIE_GARGANTUAR_ZOMBIE);
            }
            aRenderOffset = 9;
            if (mZombieType == ZOMBIE_REDEYE_GARGANTUAR)
            {
                aBodyReanim->SetImageOverride("anim_head1", IMAGE_REANIM_ZOMBIE_GARGANTUAR_HEAD_REDEYE);
                mBodyHealth = 6000;
            }
            return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
        }
        switch (theType)
        {
        case ZOMBIE_ZAMBONI:
            mBodyHealth = 1350;
            if (mApp->IsCoopMode() && mApp->IsWallnutBowlingLevel())
                mBodyHealth = 5400;
            mAnimFrames = 2;
            mAnimTicksPerFrame = 8;
            aRenderOffset = 9;
            mPosX = 800.0f + Rand(10);
            PlayZombieReanim("anim_drive", REANIM_LOOP, 0, 12.0f);
            mZombieRect.mX = 0;
            break;
        case ZOMBIE_CATAPULT:
            mBodyHealth = 850;
            mSummonCounter = 20;
            mPosX = 825.0f + Rand(10);
            if (IsOnBoard())
                PlayZombieReanim("anim_walk", REANIM_LOOP, 0, 5.5f);
            else
                PlayZombieReanim("anim_idle", REANIM_LOOP, 0, 8.0f);
            aRenderOffset = 4;
            mZombieRect.mX = 0;
            break;
        case ZOMBIE_SNORKEL:
            mZombieAttackRect.mX = -5;
            mZombieRect.mHeight = 115;
            mZombieAttackRect.mHeight = 115;
            mZombieRect.mX = 12;
            mZombieRect.mWidth = 62;
            mZombieAttackRect.mWidth = 55;
            mZombieRect.mY = 0;
            mZombieAttackRect.mY = 0;
            aRenderOffset = 4;
            SetupWaterTrack("Zombie_snorkle_whitewater");
            SetupWaterTrack("Zombie_snorkle_whitewater2");
            mVariant = false;
            mZombiePhase = PHASE_SNORKEL_WALKING;
            return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
        case ZOMBIE_JACK_IN_THE_BOX:
            mBodyHealth = 500;
            mAnimTicksPerFrame = 6;
            // The box opens after a random number of frames, and rarely much sooner.
            aDelay = Rand(300) + 450;
            if (Rand(20) == 0 && mApp->mGameMode != 76)
                aDelay /= 3;
            mZombieAttackRect.mHeight = 115;
            mZombieAttackRect.mX = 20;
            mZombieAttackRect.mY = 0;
            mZombieAttackRect.mWidth = 50;
            mPhaseCounter = 2 * (int)((float)aDelay / mVelX);
            if (mApp->IsScaryPotterLevel())
                mPhaseCounter = 10;
            if (IsOnBoard())
                mZombiePhase = PHASE_JACK_IN_THE_BOX_RUNNING;
            aRenderOffset = 4;
            return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
        case ZOMBIE_BOBSLED:
            if (theParentZombie != nullptr)
            {
                // Slot into the sled behind the leader and remember each other.
                if (theParentZombie->mFollowerZombieID[0] != 0)
                {
                    if (theParentZombie->mFollowerZombieID[1] != 0)
                    {
                        if (theParentZombie->mFollowerZombieID[2] != 0)
                        {
                            theParentZombie->mFollowerZombieID[3] = (ZombieID)mBoard->ZombieGetID(this);
                            mRelatedZombieID = (ZombieID)mBoard->ZombieGetID(theParentZombie);
                            mPosX = theParentZombie->mPosX + 200.0f;
                        }
                        else
                        {
                            theParentZombie->mFollowerZombieID[2] = (ZombieID)mBoard->ZombieGetID(this);
                            mRelatedZombieID = (ZombieID)mBoard->ZombieGetID(theParentZombie);
                            mPosX = theParentZombie->mPosX + 150.0f;
                        }
                        aRenderOffset = 0;
                        mAltitude = 9.0f;
                    }
                    else
                    {
                        theParentZombie->mFollowerZombieID[1] = (ZombieID)mBoard->ZombieGetID(this);
                        aRenderOffset = 2;
                        mRelatedZombieID = (ZombieID)mBoard->ZombieGetID(theParentZombie);
                        mAltitude = -7.0f;
                        mPosX = theParentZombie->mPosX + 100.0f;
                    }
                }
                else
                {
                    theParentZombie->mFollowerZombieID[0] = (ZombieID)mBoard->ZombieGetID(this);
                    aRenderOffset = 1;
                    mRelatedZombieID = (ZombieID)mBoard->ZombieGetID(theParentZombie);
                    mAltitude = 9.0f;
                    mPosX = theParentZombie->mPosX + 50.0f;
                }
            }
            else
            {
                aRenderOffset = 3;
                mPosX = 880.0f;
                mAltitude = -9.0f;
                mHelmType = 7;                  // HELMTYPE_BOBSLED
                mHelmHealth = 300;
                mZombieRect.mX = -50;
                mZombieRect.mY = 0;
                mZombieRect.mWidth = 275;
                mZombieRect.mHeight = 115;
            }
            mZombiePhase = PHASE_BOBSLED_SLIDING;
            mVelX = 0.6f;
            mPhaseCounter = 500;
            mVariant = false;
            if (theFromWave == -2)
            {
                PlayZombieReanim("anim_jump", REANIM_PLAY_ONCE_AND_HOLD, 0, 20.0f);
                (mApp->ReanimationGet(mBodyReanimID))->mAnimTime = 1.0f;
                mAltitude = 18.0f;
            }
            else if (IsOnBoard())
            {
                PlayZombieReanim("anim_push", REANIM_LOOP, 0, 30.0f);
            }
            return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);

        default:
            // Everything left: the flag zombie, the pogo, the heads, the imp, the boss.
            if (theType == ZOMBIE_FLAG)
            {
                mHasObject = true;
                aRenderOffset = 4;
                LoadPlainZombieReanim();
                Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
                Reanimation *aFlag = mApp->AddReanimation(0.0f, 0.0f, 0, REANIM_FLAG);
                aFlag->PlayReanim("Zombie_flag", REANIM_LOOP, 0, 15.0f);
                mSpecialHeadReanimID = mApp->ReanimationGetID(aFlag);
                ReanimatorTrackInstance *aHandTrack = aBodyReanim->GetTrackInstanceByName("Zombie_flaghand");
                AttachReanim(aHandTrack->mAttachmentID, aFlag, 0.0f, 0.0f);
                aBodyReanim->mFrameBasePose = 0;
                mPosX = 800.0f;
                return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
            }
            if (theType == ZOMBIE_POGO)
            {
                mVariant = false;
                mZombiePhase = PHASE_POGO_BOUNCING;
                aRenderOffset = 4;
                mPhaseCounter = Rand(80) + 1;
                mZombieAttackRect.mY = 0;
                mZombieAttackRect.mHeight = 115;
                mHasObject = true;
                mZombieAttackRect.mX = 10;
                mZombieAttackRect.mWidth = 30;
                mBodyHealth = 500;
                PlayZombieReanim("anim_pogo", REANIM_PLAY_ONCE_AND_HOLD, 0, 40.0f);
                (mApp->ReanimationGet(mBodyReanimID))->mAnimTime = 1.0f;
                return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
            }
            switch (theType)
            {
            case ZOMBIE_NEWSPAPER:
                mZombieAttackRect.mX = 20;
                mZombieAttackRect.mWidth = 50;
                mZombieAttackRect.mY = 0;
                mVariant = false;
                mZombieAttackRect.mHeight = 115;
                mZombiePhase = PHASE_NEWSPAPER_READING;
                mShieldType = 2;                    // SHIELDTYPE_NEWSPAPER
                mShieldHealth = 150;
                aRenderOffset = 4;
                AttachShield();
                return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
            case ZOMBIE_BALLOON:
                {
                    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
                    aBodyReanim->SetTruncateDisappearingFrames(nullptr, false);
                    if (IsOnBoard())
                    {
                        mZombiePhase = PHASE_BALLOON_FLYING;
                        mAltitude = 25.0f;
                        PlayZombieReanim("anim_idle", REANIM_LOOP, 0, aBodyReanim->mAnimRate);
                    }
                    else
                    {
                        SetAnimRate(RandRangeFloat(8.0f, 10.0f));
                    }
                    aRenderOffset = 4;
                    Reanimation *aHat = mApp->AddReanimation(0.0f, 0.0f, 0, aZombieDef->mReanimationType);
                    aHat->SetFramesForLayer("Propeller");
                    aHat->mLoopType = REANIM_LOOP_FULL_LAST_FRAME;
                    aHat->AttachToAnotherReanimation(aBodyReanim, "hat");
                    mFlyingHealth = 20;
                    mZombieAttackRect.mX = 20;
                    mZombieRect.mX = 36;
                    mZombieRect.mY = 30;
                    mZombieAttackRect.mY = 30;
                    mZombieRect.mWidth = 42;
                    mZombieRect.mHeight = 115;
                    mZombieAttackRect.mHeight = 115;
                    mZombieAttackRect.mWidth = 50;
                    mVariant = false;
                    return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
                }
            case ZOMBIE_DANCER:
                if (IsOnBoard())
                {
                    mZombiePhase = PHASE_DANCER_DANCING_IN;
                    mPhaseCounter = Rand(12) + 300;
                    mVelX = 0.5f;
                    PlayZombieReanim("anim_moonwalk", REANIM_LOOP, 0, 24.0f);
                }
                else
                {
                    PlayZombieReanim("anim_armraise", REANIM_LOOP, 0, 12.0f);
                }
                mBodyHealth = 500;
                mVariant = false;
                aRenderOffset = 8;
                return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
            case ZOMBIE_BACKUP_DANCER:
                if (!IsOnBoard())
                    PlayZombieReanim("anim_armraise", REANIM_LOOP, 0, 12.0f);
                mZombiePhase = PHASE_DANCER_DANCING_LEFT;
                mVariant = false;
                aRenderOffset = 8;
                return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);

            default:
                break;
            }
            if (theType == ZOMBIE_IMP)
            {
                if (!IsOnBoard())
                    PlayZombieReanim("anim_walk", REANIM_LOOP, 0, 12.0f);
                if (mApp->IsIZombieLevel())
                    mBodyHealth = 70;
                aRenderOffset = 4;
                return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
            }
            if (theType == ZOMBIE_BOSS)
            {
                mPosX = 0.0f;
                mPosY = 0.0f;
                mZombieRect.mY = 80;
                mZombieRect.mWidth = 90;
                mZombieRect.mHeight = 430;
                mZombieRect.mX = 700;
                mZombieAttackRect.mX = 0;
                mZombieAttackRect.mY = 0;
                mZombieAttackRect.mWidth = 0;
                mZombieAttackRect.mHeight = 0;
                mBodyHealth = mApp->IsAdventureMode() ? 40000 : 60000;
                if (IsOnBoard())
                {
                    PlayZombieReanim("anim_enter", REANIM_PLAY_ONCE_AND_HOLD, 0, 12.0f);
                    mSummonCounter = 500;
                    mBossHeadCounter = 5000;
                    mZombiePhase = PHASE_BOSS_ENTER;
                }
                else
                {
                    PlayZombieReanim("anim_head_idle", REANIM_LOOP, 0, 12.0f);
                }
                aRenderLayer = 400000;              // RENDER_LAYER_TOP
                BossSetupReanim();
                aRenderOffset = 4;
                return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
            }
            switch (theType)
            {
            case ZOMBIE_PEA_HEAD:
            case ZOMBIE_GATLING_HEAD:
                {
                    // Both wear a replacement head hung off the body's "anim_head1" track.
                    LoadPlainZombieReanim();
                    ReanimShowPrefix("anim_hair", -1);
                    ReanimShowPrefix("anim_head2", -1);
                    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
                    if (IsOnBoard())
                        aBodyReanim->SetFramesForLayer("anim_walk2");
                    ReanimatorTrackInstance *aHeadTrack = aBodyReanim->GetTrackInstanceByName("anim_head1");
                    aBodyReanim->SetImageOverride("anim_head1", IMAGE_BLANK);
                    ReanimationType aHeadType = (theType == ZOMBIE_PEA_HEAD) ? REANIM_PEASHOOTER : REANIM_GATLINGPEA;
                    Reanimation *aHead = mApp->AddReanimation(0.0f, 0.0f, 0, aHeadType);
                    aHead->PlayReanim("anim_head_idle", REANIM_LOOP, 0, 15.0f);
                    mSpecialHeadReanimID = mApp->ReanimationGetID(aHead);
                    AttachEffect *aEffect = AttachReanim(aHeadTrack->mAttachmentID, aHead, 0.0f, 0.0f);
                    aBodyReanim->mFrameBasePose = 0;
                    TodScaleRotateTransformMatrix(aEffect->mOffset, 66.0f, -4.5f, 0.2f, -1.0f, 1.0f);
                    mVariant = false;
                    mPhaseCounter = 150;
                    aRenderOffset = 4;
                    return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
                }
            case ZOMBIE_WALLNUT_HEAD:
                {
                    LoadPlainZombieReanim();
                    ReanimShowPrefix("anim_hair", -1);
                    ReanimShowPrefix("anim_head", -1);
                    ReanimShowPrefix("Zombie_tie", -1);
                    aRenderOffset = 4;
                    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
                    ReanimatorTrackInstance *aBodyTrack = aBodyReanim->GetTrackInstanceByName("Zombie_body");
                    Reanimation *aHead = mApp->AddReanimation(0.0f, 0.0f, 0, REANIM_WALLNUT);
                    aHead->PlayReanim("anim_idle", REANIM_LOOP, 0, 15.0f);
                    mSpecialHeadReanimID = mApp->ReanimationGetID(aHead);
                    AttachEffect *aEffect = AttachReanim(aBodyTrack->mAttachmentID, aHead, 0.0f, 0.0f);
                    aBodyReanim->mFrameBasePose = 0;
                    TodScaleRotateTransformMatrix(aEffect->mOffset, 50.0f, 0.0f, 0.2f, -0.8f, 0.8f);
                    mVariant = false;
                    mHelmType = 8;                  // HELMTYPE_WALLNUT
                    mHelmHealth = 1100;
                    return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
                }
            case ZOMBIE_TALLNUT_HEAD:
                {
                    LoadPlainZombieReanim();
                    ReanimShowPrefix("anim_hair", -1);
                    ReanimShowPrefix("anim_head", -1);
                    ReanimShowPrefix("Zombie_tie", -1);
                    aRenderOffset = 4;
                    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
                    ReanimatorTrackInstance *aBodyTrack = aBodyReanim->GetTrackInstanceByName("Zombie_body");
                    Reanimation *aHead = mApp->AddReanimation(0.0f, 0.0f, 0, REANIM_TALLNUT);
                    aHead->PlayReanim("anim_idle", REANIM_LOOP, 0, 15.0f);
                    mSpecialHeadReanimID = mApp->ReanimationGetID(aHead);
                    AttachEffect *aEffect = AttachReanim(aBodyTrack->mAttachmentID, aHead, 0.0f, 0.0f);
                    aBodyReanim->mFrameBasePose = 0;
                    TodScaleRotateTransformMatrix(aEffect->mOffset, 37.0f, 0.0f, 0.2f, -0.8f, 0.8f);
                    mVariant = false;
                    mHelmType = 9;                  // HELMTYPE_TALLNUT
                    mHelmHealth = 2200;
                    mPosX += 30.0f;
                    return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
                }
            case ZOMBIE_JALAPENO_HEAD:
                {
                    LoadPlainZombieReanim();
                    ReanimShowPrefix("anim_hair", -1);
                    ReanimShowPrefix("anim_head", -1);
                    ReanimShowPrefix("Zombie_tie", -1);
                    aRenderOffset = 4;
                    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
                    ReanimatorTrackInstance *aBodyTrack = aBodyReanim->GetTrackInstanceByName("Zombie_body");
                    Reanimation *aHead = mApp->AddReanimation(0.0f, 0.0f, 0, REANIM_JALAPENO);
                    aHead->PlayReanim("anim_idle", REANIM_LOOP, 0, 15.0f);
                    mSpecialHeadReanimID = mApp->ReanimationGetID(aHead);
                    AttachEffect *aEffect = AttachReanim(aBodyTrack->mAttachmentID, aHead, 0.0f, 0.0f);
                    aBodyReanim->mFrameBasePose = 0;
                    TodScaleRotateTransformMatrix(aEffect->mOffset, 55.0f, -15.0f, 0.2f, -1.0f, 1.0f);
                    mVariant = false;
                    mBodyHealth = 500;
                    mPhaseCounter = 2 * (int)((float)(Rand(175) + 275) / mVelX);
                    return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
                }
            case ZOMBIE_SQUASH_HEAD:
                {
                    LoadPlainZombieReanim();
                    ReanimShowPrefix("anim_hair", -1);
                    ReanimShowPrefix("anim_head2", -1);
                    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
                    if (IsOnBoard())
                        aBodyReanim->SetFramesForLayer("anim_walk2");
                    ReanimatorTrackInstance *aHeadTrack = aBodyReanim->GetTrackInstanceByName("anim_head1");
                    aRenderOffset = 4;
                    aBodyReanim->SetImageOverride("anim_head1", IMAGE_BLANK);
                    Reanimation *aHead = mApp->AddReanimation(0.0f, 0.0f, 0, REANIM_SQUASH);
                    aHead->PlayReanim("anim_idle", REANIM_LOOP, 0, 15.0f);
                    mSpecialHeadReanimID = mApp->ReanimationGetID(aHead);
                    AttachEffect *aEffect = AttachReanim(aHeadTrack->mAttachmentID, aHead, 0.0f, 0.0f);
                    aBodyReanim->mFrameBasePose = 0;
                    TodScaleRotateTransformMatrix(aEffect->mOffset, 55.0f, -15.0f, 0.2f, -0.75f, 0.75f);
                    mVariant = false;
                    mZombiePhase = PHASE_SQUASH_PRE_LAUNCH;
                    return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
                }

            default:
                aRenderOffset = 4;
                return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
            }
        }

        // The zamboni and the catapult sit higher and take the taller body.
        mVariant = false;
        mZombieRect.mY = -13;
        mZombieAttackRect.mY = -13;
        mZombieRect.mWidth = 153;
        mZombieRect.mHeight = 140;
        mZombieAttackRect.mHeight = 140;
        mZombieAttackRect.mX = 10;
        mZombieAttackRect.mWidth = 133;
        return FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
    }

    // The bungee hangs above the lawn and drops in.
    mAnimFrames = 4;
    mBodyHealth = 450;
    mAltitude = 3000.0f + RandRangeInt(0, 150);
    mVelX = 0.0f;
    if (!IsOnBoard())
    {
        mZombiePhase = PHASE_BUNGEE_CUTSCENE;
        mPhaseCounter = RandRangeInt(0, 200);
    }
    else
    {
        PickBungeeZombieTarget(-1);
        if (mDead)
            return;
        mZombiePhase = PHASE_BUNGEE_DIVING;
    }

    aRenderLayer = 301000;                      // RENDER_LAYER_GRAVE_STONE
    PlayZombieReanim("anim_drop", REANIM_LOOP, 0, 24.0f);
    aRenderOffset = 7;
    Reanimation *aBodyReanim = mApp->ReanimationGet(mBodyReanimID);
    aBodyReanim->AssignRenderGroupToPrefix("Zombie_bungi_rightarm_lower2", 2);
    aBodyReanim->AssignRenderGroupToPrefix("Zombie_bungi_rightarm_hand2", 2);
    aBodyReanim->AssignRenderGroupToPrefix("Zombie_bungi_leftarm_lower2", 2);
    aBodyReanim->AssignRenderGroupToPrefix("Zombie_bungi_leftarm_hand2", 2);
    aBodyReanim->SetTruncateDisappearingFrames(nullptr, false);
    mZombieRect.mX = -20;
    mZombieRect.mY = 22;
    mZombieRect.mWidth = 110;
    mZombieRect.mHeight = 94;
    mZombieAttackRect.mX = 0;
    mZombieAttackRect.mY = 0;
    mZombieAttackRect.mWidth = 0;
    mZombieAttackRect.mHeight = 0;
    mVariant = false;

    FinishInitialize(theType, theFromWave, aRenderLayer, aRenderOffset);
}

void Zombie::FinishInitialize(ZombieType theType, int theFromWave, int theRenderLayer, int theRenderOffset)
{
    // Zombiquarium zombies swim and drift instead of walking.
    if (IsOnBoard() && mApp->mGameMode == 24)
    {
        PlayZombieReanim("anim_aquarium_swim", REANIM_LOOP, 0, RandRangeFloat(8.0f, 10.0f));
        mZombieHeight = 10;
        mPhaseCounter = 200;
        mBodyHealth = 200;
        mZombiePhase = PHASE_ZOMBIQUARIUM_DRIFT;
        mSummonCounter = RandRangeInt(200, 400);
    }

    // Little Trouble runs its zombies at a quarter health and half speed.
    if (mApp->IsLittleTroubleLevel() && (IsOnBoard() || theFromWave == -2))
    {
        mBodyHealth /= 4;
        mHelmHealth /= 4;
        mShieldHealth /= 4;
        mFlyingHealth /= 4;
        mScaleZombie = 0.5f;
    }

    UpdateAnimSpeed();
    if (mVariant)
        ReanimShowPrefix("anim_tongue", 0);

    mShieldMaxHealth = mShieldHealth;
    mFlyingMaxHealth = mFlyingHealth;
    mX = (int)mPosX;
    mY = (int)mPosY;
    mBodyMaxHealth = mBodyHealth;
    mHelmMaxHealth = mHelmHealth;
    mDead = false;
    mRenderOrder = Board::MakeRenderOrder((RenderLayer)theRenderLayer, mRow, theRenderOffset);
    if (mZombieHeight == 10)
        mBodyMaxHealth = 300;

    if (IsOnBoard())
    {
        PlayZombieAppearSound();
        StartZombieSound();
    }

    // Only a plain zombie ever arrives bloated, and only rarely.
    mBloated = theType == ZOMBIE_NORMAL && PlatformRandomLong() % 300 == 1;
    UpdateReanim();
}

// ==========================================================================
// Zombie::SetupShieldReanims(ZombieType,Reanimation *)
// @001B6B0C  154 bytes
// ==========================================================================
// Static, like SetupDoorArms: the caller at 0x1C3418 loads the ZombieType into
// R0 and the reanimation into R1, and the body uses R1 as the Reanimation
// receiver for the whole of its switch. Zombie.h used to declare this as a
// non-static member, which pushed both arguments one register along.
void Zombie::SetupShieldReanims(ZombieType theZombieType, Reanimation *theReanim)
{
    // The track the shield hands are bound to; empty means "none".
    const char *aTrackName = "";

    switch (theZombieType)
    {
    case ZOMBIE_DOOR:
        SetupDoorArms(theReanim, true);
        theReanim->AssignRenderGroupToPrefix("Zombie_outerarm_screendoor", 3);
        aTrackName = "anim_screendoor";
        break;

    case ZOMBIE_TRASHCAN:
        SetupDoorArms(theReanim, true);
        theReanim->AssignRenderGroupToPrefix("Zombie_outerarm_screendoor", 3);
        theReanim->SetImageOverride("anim_screendoor", IMAGE_REANIM_ZOMBIE_TRASHCAN1);
        aTrackName = "anim_screendoor";
        break;

    case ZOMBIE_NEWSPAPER:
        theReanim->AssignRenderGroupToPrefix("Zombie_paper_hands", 3);
        aTrackName = "Zombie_paper_paper";
        break;

    default:
        // Only the ladder zombie has an outer-arm group to re-bind; it returns
        // straight away rather than falling through to the shared track bind.
        if (theZombieType == ZOMBIE_LADDER)
        {
            theReanim->AssignRenderGroupToPrefix("Zombie_outerarm", 3);
            theReanim->AssignRenderGroupToTrack("Zombie_ladder_1", 1);
            return;
        }
        break;
    }

    theReanim->AssignRenderGroupToTrack(aTrackName, 1);
}
// ==========================================================================
// Zombie::Zombie(void)
// @001B6BD4  152 bytes
// ==========================================================================
Zombie::Zombie()
{
    // GameObject's constructor has already registered the mX..mRenderOrder sync
    // block and zeroed it. The zombie registers its own state area -- the 317
    // bytes that start at mZombieType -- as a second block and then zero-fills
    // exactly that range. mCachedZombieRect lies past the end of the block, so
    // its four words are cleared individually.
    //
    // The vtable store and the placement-new of the GameObject base that the
    // transcription carried are gone: the class is a real polymorphic type now,
    // so the compiler emits both.
    mVisible = true;

    SyncBlockInfo aBlock = MakeSyncBlock(mZombieType, mWalnutDeath);
    mSyncBlocks.push_back(aBlock);

    mZombieRect.mX = 0;
    mZombieRect.mY = 0;
    mZombieRect.mWidth = 0;
    mZombieRect.mHeight = 0;
    mZombieAttackRect.mX = 0;
    mZombieAttackRect.mY = 0;
    mZombieAttackRect.mWidth = 0;
    mZombieAttackRect.mHeight = 0;
    mCachedZombieRect.mX = 0;
    mCachedZombieRect.mY = 0;
    mCachedZombieRect.mWidth = 0;
    mCachedZombieRect.mHeight = 0;

    memset(aBlock.mData, 0, aBlock.mSize);
}
