// ==========================================================================
// Zombie::CheckForBoardEdge(void)
// @001B6E44  212 bytes
// ==========================================================================
void Zombie::CheckForBoardEdge()
{
    if (IsWalkingBackwards() && mPosX > 850.0f)
    {
        DieNoLoot();
        return;
    }

    // How far left of the board a zombie of this type is allowed to drift, and
    // the tighter limit at which it starts taking damage. The four groups are
    // the vehicles and the giant zombies (which reach much further in), the
    // fast movers, the jumpers, and everything else.
    int aDamageX;
    int aEdgeX;
    switch (mZombieType)
    {
    case ZOMBIE_POLEVAULTER:
    case ZOMBIE_FOOTBALL:
    case ZOMBIE_REDEYE_GARGANTUAR:
        aDamageX = -30;
        aEdgeX = -100;
        break;

    case ZOMBIE_DANCER:
    case ZOMBIE_BACKUP_DANCER:
    case ZOMBIE_SNORKEL:
        aDamageX = -55;
        aEdgeX = -125;
        break;

    case ZOMBIE_GARGANTUAR:
    case ZOMBIE_CATAPULT:
    case ZOMBIE_ZAMBONI:
        aDamageX = -10;
        aEdgeX = -80;
        break;

    default:
        aDamageX = 20;
        aEdgeX = -50;
        break;
    }

    int aX = mX;
    if (aX <= aEdgeX && mHasHead)
    {
        if (mApp->IsIZombieLevel())
        {
            DieNoLoot();
            aX = mX;
        }
        else
        {
            // On a shop level the zombie buys its way out instead of ending the
            // level; everywhere else reaching the edge loses the level.
            if (mApp->CanShopLevel())
                BuySunMoneyItem();
            else
                mBoard->ZombiesWon(this);
            aX = mX;
        }
    }

    // A headless zombie is already past the point where losing the level
    // matters, so it just takes the damage.
    if (aX <= aDamageX && !mHasHead)
        TakeDamage(1800, 9);
}
// ==========================================================================
// Zombie::UpdatePlaying(void)
// @001B6F1C  416 bytes
// ==========================================================================
int Zombie::UpdatePlaying()
{
    // The groan counter runs down to a shared groan: exactly one zombie of the
    // wave is picked, and the pitch is only randomised on the little-trouble
    // level. A headless zombie, the boss and a level whose award has already
    // dropped all stay silent.
    mGroanCounter--;
    if (mGroanCounter == 0
        && Rand((int)mBoard->mZombies.mSize) == 0
        && mHasHead
        && mZombieType != ZOMBIE_BOSS
        && !mBoard->HasLevelAwardDropped())
    {
        int aPitch = 0;
        if (mApp->IsLittleTroubleLevel())
            aPitch = RandRangeFloat(40.0, 50.0);

        if (mZombieType == ZOMBIE_GARGANTUAR)
            mApp->PlayFoley(FOLEY_LOW_GROAN);
        else if (mVariant)
            mApp->PlayFoleyPitch(FOLEY_BRAINS, (float)aPitch);
        else
            mApp->PlayFoleyPitch(FOLEY_GROAN, (float)aPitch);

        mGroanCounter = Rand(1000) + 500;
    }

    if (mIceTrapCounter > 0)
    {
        mIceTrapCounter--;
        if (mIceTrapCounter == 0)
        {
            RemoveIceTrap();
            AddAttachedParticle(75, 106, ParticleEffect(59));
        }
    }

    if (mChilledCounter > 0)
    {
        mChilledCounter--;
        if (mChilledCounter == 0)
            UpdateAnimSpeed();
    }

    if (mButteredCounter > 0)
    {
        mButteredCounter--;
        if (mButteredCounter == 0)
            RemoveButter();
    }

    if (mZombiePhase == PHASE_RISING_FROM_GRAVE)
        return UpdateZombieRiseFromGrave();

    if (!IsImmobilizied())
    {
        UpdateActions();
        UpdateZombiePosition();
        CheckIfPreyCaught();
        CheckForPool();
        CheckForHighGround();
        CheckForBoardEdge();

        if (mZombieType == ZOMBIE_BOSS)
            UpdateBoss();
    }
    else if (mZombieType == ZOMBIE_BOSS)
    {
        // An immobilised boss still runs its scripted fight.
        UpdateBoss();
    }

    int result = IsDeadOrDying();
    if (result == 0 && mFromWave != -4)
    {
        // Only the vehicles and the catapult keep grinding forward once they are
        // nearly dead, and only a zombie that still has its head cares.
        if (((mZombieType == ZOMBIE_ZAMBONI || mZombieType == ZOMBIE_CATAPULT) && mBodyHealth <= 199)
            || !mHasHead)
        {
            int aDamage = (mZombieType == ZOMBIE_YETI) ? 10 : 1;
            if (mBodyMaxHealth >= 500)
                aDamage = 3;

            if (Rand(5) == 0)
                {
      TakeDamage(aDamage, 9);
      return 0;
    }
        }
    }
    return result;
}
// ==========================================================================
// Zombie::Update(void)
// @001B70BC  368 bytes
// ==========================================================================
int Zombie::Update()
{
    // The header's `int` is the leftover r0 of the last call: the binary's
    // Zombie::Update returns void, so every exit here yields 0.
    mZombieAge++;
    mCachedZombieRect.mWidth = 0;   // invalidates the cached zombie rect

    // Two ways past the game-scene filter: the level intro, where only a boss --
    // or a board the upsell cut scene still owns -- keeps updating, and the
    // ordinary path, where the same upsell test applies.
    bool aSkipGameObjects = false;
    bool aPastSceneFilter =
        (mZombieType == ZOMBIE_BOSS && mApp->mGameScene == SCENE_LEVEL_INTRO)
        || (IsOnBoard() && mBoard->mCutScene->ShouldRunUpsellBoard());

    if (!aPastSceneFilter)
    {
        if ((unsigned int)(mApp->mGameMode - GAMEMODE_MP_VS_DEBUG) > 1
            || mApp->mGameScene != SCENE_PLANTS_WON)
        {
            // Off the board and out of the intro there is nothing left to
            // animate, unless the zombie is still walking in from a wave.
            if (mApp->mGameScene != SCENE_PLAYING && IsOnBoard() && mFromWave != -4)
                return 0;
        }
        else
        {
            // The versus mode draws the plants-won scene with the zombies still
            // standing, so their per-type object update is skipped this frame.
            aSkipGameObjects = true;
        }
    }

    bool aRunTail = true;
    switch (mZombiePhase)
    {
    case PHASE_ZOMBIE_BURNED:
        UpdateBurn();
        break;

    case PHASE_ZOMBIE_MOWERED:
        UpdateMowered();
        break;

    case PHASE_ZOMBIE_DYING:
        UpdateDeath();
        UpdateZombieWalking();
        break;

    default:
        // Every other phase runs the shared object update first, and only then
        // reaches the common tail.
        aRunTail = false;
        if (mPhaseCounter > 0 && !IsImmobilizied())
            mPhaseCounter--;

        if (!aSkipGameObjects)
        {
            if (mApp->mGameScene == SCENE_ZOMBIES_WON)
            {
                UpdateZombieChimney();
                UpdateZombieWalkingIntoHouse();
            }
            else if (IsOnBoard())
            {
                UpdatePlaying();
            }

            if (mZombieType == ZOMBIE_BUNGEE)
                UpdateZombieBungee();
            if (mZombieType == ZOMBIE_POGO)
                UpdateZombiePogo();

            Animate();
            aRunTail = true;
        }
        break;
    }

    if (!aRunTail)
        return 0;

    if (mShieldJustGotShotCounter > 0)
        mShieldJustGotShotCounter--;
    mJustGotShotCounter--;
    if (mShieldRecoilCounter > 0)
        mShieldRecoilCounter--;

    if (mZombieFade > 0)
    {
        mZombieFade--;
        if (mZombieFade == 0)
            DieNoLoot();
    }

    // The rect the drawing code uses is derived from the float position.
    mX = (int)mPosX;
    mY = (int)mPosY;
    AttachmentUpdateAndMove(mAttachmentID, mPosX, mPosY);
    UpdateReanim();
    return 0;
}
